-- SRS review-card backfill — BATCH 10 of 10 (821 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter and
-- each is idempotent. Together the 10 batches equal backfill_srs_payload.sql.
-- Covers Top 2 preboards/mocks/reviewer + main-app banks + Top 2 banks.
WITH d(qid, patch) AS (
  VALUES
  ('87b83aa9-27','{"options": ["Neural ectoderm", "Surface ectoderm", "Mesoderm", "Neural crest"], "correct": 2, "explanation": "Mesoderm gives rise to the EOMs, ciliary muscle, vitreous, and Tenon''s capsule. Neural ectoderm forms the retina and pupil muscles; surface ectoderm forms the lens and glands."}'),
  ('bd817082-1w','{"options": ["Frontal bone + lesser wing of sphenoid", "Greater wing of sphenoid + zygomatic bone", "Maxilla + palatine + zygomatic", "Lamina papyracea of the ethmoid"], "correct": 1, "explanation": "The lateral (outer) wall is the thickest and strongest, formed by the greater wing of the sphenoid and the zygomatic bone. It carries the lateral orbital tubercle (attachment for the LR check ligament, Ligament of Lockwood, and lateral palpebral ligament)."}'),
  ('35274c10-2c','{"options": ["Roof", "Medial wall", "Floor", "Lateral wall"], "correct": 2, "explanation": "The orbital floor (maxilla + palatine + zygomatic) is triangular and the weakest wall; fracture leads to enophthalmos as orbital contents prolapse into the maxillary sinus. The medial wall is the thinnest, but the floor is the classic blow-out site."}'),
  ('fdeac03a-1l','{"options": ["CN#2, ophthalmic artery, sympathetic nerve", "CN#3, CN#4, CN#6", "CN#5 V2 and infraorbital artery", "Superior ophthalmic vein"], "correct": 0, "explanation": "The optic foramen (lesser wing of sphenoid) transmits CN#2 (optic nerve), the ophthalmic artery, and sympathetic fibers. CN#3, #4, #6 and the superior ophthalmic vein pass through the superior orbital fissure."}'),
  ('54c995eb-2d','{"options": ["Exenteration", "Evisceration", "Enucleation", "Keratoplasty"], "correct": 2, "explanation": "Enucleation removes the whole eyeball only. Evisceration removes the intraocular contents but leaves the sclera and EOMs; exenteration removes the entire orbital contents including eyelids and part of the bony orbit."}'),
  ('2e0ad3f5-3c','{"options": ["Enucleation", "Evisceration", "Exenteration", "Trabeculectomy"], "correct": 1, "explanation": "Evisceration removes intraocular contents with the sclera and EOMs left in place, often used for endophthalmitis unresponsive to antibiotics. Enucleation removes the whole globe; exenteration clears the entire orbit."}'),
  ('36407493-3r','{"options": ["Inferior rectus and inferior oblique", "Superior rectus and superior oblique", "Medial and lateral recti", "Levator palpebrae and Muller''s muscle"], "correct": 0, "explanation": "Tenon''s capsule thickens at its lower portion with the fascia of the inferior rectus and inferior oblique to form the Ligament of Lockwood, which supports the globe like a hammock."}'),
  ('8f0a7c03-1v','{"options": ["Orbicularis oculi", "Levator palpebrae superioris", "Muller''s muscle", "Sphincter pupillae"], "correct": 2, "explanation": "Muller''s muscle (superior tarsal muscle) is smooth muscle under sympathetic control; its loss in Horner''s syndrome causes a 1–2 mm ptosis. The LPS is CN#3, orbicularis oculi is CN#7."}'),
  ('de66d395-2h','{"options": ["CN#3", "CN#5", "CN#7", "CN#6"], "correct": 2, "explanation": "The orbicularis oculi is innervated by CN#7 (facial nerve). Damage causes lagophthalmos (inability to fully close the lid). The LPS that opens the lid is CN#3."}'),
  ('ec153cca-1k','{"options": ["Poliosis", "Madarosis", "Trichiasis", "Distichiasis"], "correct": 2, "explanation": "Trichiasis is misdirection of the cilia. Poliosis is whitening of the lashes, madarosis is loss of lashes, and distichiasis is an extra (supernumerary) row of lashes."}'),
  ('7dd5b636-17','{"options": ["The thickest skin in the body", "The thinnest skin in the body", "Heavily keratinized", "Rich in subcutaneous fat"], "correct": 1, "explanation": "Eyelid skin is the thinnest in the body, overlying loose areolar connective tissue that is devoid of fat (which is why it swells easily with edema)."}'),
  ('aac65de8-20','{"options": ["Limbus", "Lid margins", "Fornix", "Bulbar conjunctiva"], "correct": 2, "explanation": "Goblet cells are most numerous at the fornix, fewer in the bulbar conjunctiva, and ABSENT at the lid margins and limbus. Their mucin is the wetting agent of the precorneal tear film."}'),
  ('794078bc-1f','{"options": ["Superior", "Inferior", "Lateral", "Medial"], "correct": 3, "explanation": "There is NO medial fornix; the conjunctiva there is taken up by the plica semilunaris and caruncle. The superior fornix sits 10 mm from the limbus, the inferior 8 mm, and the lateral 14 mm."}'),
  ('c67682b2-14','{"options": ["Entrance of the optic nerve", "At the limbus", "Just behind the insertions of the recti muscles", "At the posterior pole"], "correct": 2, "explanation": "The sclera is thinnest (about 0.3 mm) just behind the recti insertions, in front of the equator. It is thickest (about 1 mm) at the entrance of the optic nerve."}'),
  ('2dc13be3-1p','{"options": ["Episclera", "Scleral stroma", "Lamina fusca", "Bowman''s membrane"], "correct": 2, "explanation": "The lamina fusca (dark layer) is the innermost scleral layer and contains melanocytes. The episclera is the outer vascular layer and the scleral stroma gives the sclera its white opacity."}'),
  ('33471de2-1n','{"options": ["Keratometer", "Pachymeter", "Tonometer", "Gonioscope"], "correct": 1, "explanation": "Central corneal thickness (about 0.52–0.56 mm) is measured by a pachymeter. A keratometer measures corneal curvature, and a tonometer measures intraocular pressure."}'),
  ('2ffe456f-2p','{"options": ["10%", "25%", "50%", "90%"], "correct": 3, "explanation": "The stroma is about 90% of corneal thickness, making it the thickest layer. It is avascular, rich in unmyelinated nasociliary nerves, and made of collagen lamellae in glycosaminoglycans."}'),
  ('bb36123f-1l','{"options": ["1.376 diopters", "43 diopters", "60 diopters", "20 diopters"], "correct": 1, "explanation": "The cornea contributes about 43 D, making it the most powerful single refractive element of the eye. 1.376 is its index of refraction, and about 60 D is the total power of the whole eye."}'),
  ('863a0ab5-1g','{"options": ["Nasociliary branch of CN#5", "Short ciliary nerve", "CN#7 (facial)", "CN#3 (oculomotor)"], "correct": 0, "explanation": "The nasociliary nerve (a branch of CN#5 ophthalmic division) supplies the whole cornea EXCEPT Descemet''s membrane and the endothelium. This dense sensory supply is why corneal abrasions are so painful."}'),
  ('3fb11fec-3k','{"options": ["Bowman''s membrane", "Dua''s layer", "Lamina fusca", "Bruch''s membrane"], "correct": 1, "explanation": "Dua''s layer (about 6–15 µm) sits between the stroma and Descemet''s membrane and is strong and impervious to air, withstanding up to roughly 2 bars (200 kPa)."}'),
  ('f79611a5-35','{"options": ["Pars plana", "Pars plicata", "Lamina fusca", "Ora serrata"], "correct": 1, "explanation": "The pars plicata (corona ciliaris), about 2 mm wide, is the most vascular part of the ciliary body and carries the ciliary processes. The pars plana is the least vascular and is the safe surgical entry site."}'),
  ('5c73896f-1f','{"options": ["The sympathetic nervous system", "Parasympathetic fibers of CN#3", "CN#5", "CN#7"], "correct": 1, "explanation": "The sphincter pupillae (miosis, <2 mm) is driven by parasympathetic fibers of CN#3 from the Edinger-Westphal nucleus via the short ciliary nerves. The dilator pupillae is sympathetic."}'),
  ('2d9ab3cb-18','{"options": ["Parasympathetic fibers of CN#3", "The sympathetic nervous system", "CN#4", "CN#6"], "correct": 1, "explanation": "The dilator pupillae (mydriasis, >5 mm) is under sympathetic control. The sphincter pupillae is parasympathetic (CN#3)."}'),
  ('9c2ab29d-1q','{"options": ["Inner sensory retina", "RPE and photoreceptors", "Iris", "Ciliary muscle"], "correct": 1, "explanation": "The choriocapillaris supplies the RPE and photoreceptors and accounts for roughly 65–85% of blood flow to the retina. The inner sensory retina is supplied by the central retinal artery."}'),
  ('91991341-23','{"options": ["Miosis", "Ptosis", "Anhidrosis", "Mydriasis"], "correct": 3, "explanation": "Horner''s syndrome (lesion of the sympathetic pathway) causes miosis (dilator pupillae), partial ptosis (Muller''s muscle), and facial anhidrosis. Mydriasis is the opposite and does not occur."}'),
  ('b7ad1ab6-1c','{"options": ["Argyll Robertson pupil", "A relative afferent pupillary defect (Marcus-Gunn)", "Adie''s tonic pupil", "Horner''s syndrome"], "correct": 1, "explanation": "The swinging-flashlight test detects an RAPD (Marcus-Gunn pupil): when the light swings to the affected eye, both pupils dilate because of the diminished afferent signal from optic nerve or severe retinal disease."}'),
  ('491cd2de-2f','{"options": ["440 nm", "507 nm", "535 nm", "555 nm"], "correct": 1, "explanation": "Rod rhodopsin (visual purple) peaks near 507 nm and mediates scotopic (dim-light) vision. The cone pigment iodopsin varies by cone type (blue 440, green 535, red 750 nm)."}'),
  ('a9405b5f-2s','{"options": ["Optic disc", "Fovea centralis", "Ora serrata", "Macula lutea"], "correct": 1, "explanation": "The fovea centralis is a 1.5 mm pit at the center of the macula; it is the thinnest, capillary-free region with the keenest vision. Its rim (parafovea) is the thickest part of the retina."}'),
  ('4c321087-1m','{"options": ["Fovea centralis", "Optic disc", "Macula lutea", "Ora serrata"], "correct": 1, "explanation": "The optic disc (optic nerve head) has no photoreceptors, producing the physiologic blind spot. It is about 1.5 mm in diameter and sits nasal to the fovea."}'),
  ('9a1926ce-1n','{"options": ["6 million", "13 million", "130 million", "1.2 million"], "correct": 2, "explanation": "There are about 130 million rods (peripheral retina, scotopic vision) versus about 6 million cones (central retina, photopic vision)."}'),
  ('947ddc68-20','{"options": ["Binasal hemianopsia", "Bitemporal hemianopsia", "Homonymous hemianopsia", "Total monocular blindness"], "correct": 1, "explanation": "Crossing (nasal) fibers at the chiasm carry the temporal visual fields, so their interruption (classically by a pituitary tumor) causes bitemporal hemianopsia. Damage to the uncrossed fibers gives binasal hemianopsia."}'),
  ('8c3fe19a-21','{"options": ["Area 17", "Area 18", "Area 19", "Area 4"], "correct": 0, "explanation": "The primary visual cortex is Brodmann area 17 on the medial occipital lobe, marked by the white line (stria of Gennari). Areas 18 and 19 are visual association cortex."}'),
  ('7936cf1b-18','{"options": ["Intraocular", "Intraorbital", "Intracanalicular", "Intracranial"], "correct": 1, "explanation": "The intraorbital part (about 30 mm, with an S-shaped curve that allows eye movement) is the longest. The intraocular part (0.7–1.0 mm) is the shortest."}'),
  ('2a161bee-19','{"options": ["Elevation", "Depression", "Intorsion", "Extorsion"], "correct": 2, "explanation": "The superior oblique''s primary action is intorsion, with depression as secondary and abduction as tertiary. It is innervated by CN#4."}'),
  ('0f3991a1-1a','{"options": ["Superior rectus", "Medial rectus", "Lateral rectus", "Superior oblique"], "correct": 2, "explanation": "CN#6 (abducens) innervates the lateral rectus (abduction). Remember LR6 SO4 and all the rest CN#3."}'),
  ('1a40966a-32','{"options": ["Superior rectus", "Inferior oblique", "Superior oblique", "Lateral rectus"], "correct": 1, "explanation": "The inferior oblique arises from the orbital floor (maxilla), not the Annulus of Zinn, and is the only EOM that does not form part of the muscle cone. It is also the shortest EOM."}'),
  ('76c8c7b4-1i','{"options": ["Levator palpebrae superioris", "Sphincter pupillae", "Superior oblique", "Inferior oblique"], "correct": 2, "explanation": "The superior oblique is innervated by CN#4, not CN#3. CN#3 supplies the LPS, sphincter pupillae, ciliary muscle, and all recti except the lateral rectus, plus the inferior oblique."}'),
  ('5819de79-25','{"options": ["Superior orbital fissure", "Foramen rotundum", "Foramen ovale", "Optic foramen"], "correct": 1, "explanation": "V2 exits via the foramen rotundum. V1 (ophthalmic) passes through the superior orbital fissure and V3 (mandibular) through the foramen ovale. Mnemonic: Standing Room Only."}'),
  ('fbacdd0b-2e','{"options": ["Edinger-Westphal nucleus", "Superior cervical ganglion", "Lateral geniculate body", "Pterygopalatine ganglion"], "correct": 0, "explanation": "The Edinger-Westphal nucleus (parasympathetic part of CN#3) sends fibers to the ciliary ganglion and then via the short ciliary nerves to the sphincter pupillae and ciliary muscle."}'),
  ('9d7950cd-1p','{"options": ["External carotid artery", "Internal carotid artery", "Middle cerebral artery", "Facial artery"], "correct": 1, "explanation": "The ophthalmic artery is the first intracranial branch of the internal carotid artery; it enters the orbit through the optic canal infero-lateral to the optic nerve."}'),
  ('0c1fec6c-1p','{"options": ["Lacrimal artery", "Central retinal artery", "Short posterior ciliary artery", "Supraorbital artery"], "correct": 1, "explanation": "The central retinal artery is the first intraorbital branch; it enters the optic nerve about 10–12 mm behind the globe and supplies the inner sensory retina (about 20–30% of retinal blood flow)."}'),
  ('9b7eb616-21','{"options": ["20 mm", "24 mm", "28 mm", "16 mm"], "correct": 1, "explanation": "The average axial length is about 24 mm (range 22–27 mm). The eyeball weighs about 10 g with a volume near 6.5 mL."}'),
  ('3a790c27-3n','{"options": ["Microphthalmos", "Nanophthalmos", "Anophthalmos", "Buphthalmos"], "correct": 1, "explanation": "Nanophthalmos is a small eye with NORMAL internal structures, thickened sclera/choroid, and high hyperopia. Microphthalmos is a small MALFORMED eye associated with colobomas and cysts."}'),
  ('6cf96efa-1l','{"options": ["Is a genuinely enlarged eyeball, and is associated with congenital glaucoma", "Is the eyeball pushed forward", "Is always unilateral and endocrine", "Is degenerative shrinkage of the globe"], "correct": 0, "explanation": "Buphthalmos (''bull eye'') is true enlargement of the globe in congenital glaucoma. Exophthalmos is anterior displacement (protrusion), classically bilateral in Grave''s disease."}'),
  ('2e214e19-2c','{"options": ["Phthisis bulbi", "Proptosis", "Macrophthalmia", "Nanophthalmos"], "correct": 0, "explanation": "Phthisis bulbi is the degenerative shrinkage/disorganisation of the globe after injury. Macrophthalmia is enlargement; proptosis is protrusion."}'),
  ('690179e7-1t','{"options": ["Carotid-cavernous fistula", "Orbital floor fracture", "Orbital cellulitis", "Grave''s disease (thyrotoxic ophthalmopathy)"], "correct": 3, "explanation": "Bilateral exophthalmos points to an endocrine cause, classically Grave''s disease. Orbital cellulitis and floor fracture are unilateral; a carotid-cavernous fistula gives pulsating proptosis."}'),
  ('428727f2-z','{"options": ["Thyroid eye disease", "Mucocele", "Orbital cellulitis", "Carotid-cavernous sinus fistula"], "correct": 3, "explanation": "Pulsating proptosis is classic for a carotid-cavernous sinus fistula (also a vascular tumour, aneurysm, or transmitted cerebral pulsation)."}'),
  ('c8bc55e3-1c','{"options": ["Glioma of the optic nerve", "Hemangioma", "Meningioma", "Rhabdomyosarcoma"], "correct": 1, "explanation": "Hemangioma is the most common benign orbital tumour. Rhabdomyosarcoma is the most common malignant orbital tumour of childhood."}'),
  ('2ec2ada4-2q','{"options": ["Rhabdomyosarcoma", "Carcinoma of the orbit", "Hemangioma", "Neurofibroma"], "correct": 0, "explanation": "Rhabdomyosarcoma is the most common primary orbital malignancy of childhood, arising from skeletal muscle tissue."}'),
  ('76c720f8-1d','{"options": ["Ethmoiditis", "Dacryoadenitis", "Frontal sinusitis", "Maxillary sinusitis"], "correct": 0, "explanation": "Ethmoiditis is the most common source of orbital cellulitis because the thin lamina papyracea separates the ethmoid sinus from the orbit."}'),
  ('3ce4112b-25','{"options": ["An orbital floor (blow-out) fracture", "Grave''s disease", "A vascular tumour", "Congenital glaucoma"], "correct": 0, "explanation": "Enophthalmos follows an orbital floor fracture (also fat atrophy or surgical decompression), as orbital contents prolapse and the globe sinks back."}'),
  ('06d95e17-35','{"options": ["Blepharophimosis", "Coloboma", "Distichiasis", "Epicanthus"], "correct": 3, "explanation": "Epicanthus is the most common congenital lid anomaly, a bilateral vertical skin fold at the inner canthus producing pseudostrabismus (pseudo-esotropia)."}'),
  ('d485d15f-2a','{"options": ["Trichiasis", "Madarosis", "Distichiasis", "Poliosis"], "correct": 2, "explanation": "Distichiasis is an extra row of lashes from the Meibomian orifices; the misdirected second row often causes trichiasis (corneal rubbing)."}'),
  ('9d06ea16-1j','{"options": ["Mydriasis, anhidrosis, ptosis", "Ptosis, mydriasis, exophthalmos", "Ptosis, miosis, proptosis", "Ptosis, miosis, anhidrosis"], "correct": 3, "explanation": "Horner''s (sympathetic paralysis of Mueller''s muscle and the dilator pupillae) gives the triad of partial ptosis, miosis, and facial anhidrosis."}'),
  ('0668bb88-2k','{"options": ["Xanthelasma", "Chalazion", "Hordeolum", "Meibomitis"], "correct": 2, "explanation": "A hordeolum (stye) is an acute, painful, movable staphylococcal infection of the glands of Zeis/Moll. A chalazion is chronic, painless, and fixed to the tarsus."}'),
  ('1c0b701a-2d','{"options": ["Keratoacanthoma", "Milia", "Chalazion", "Hordeolum"], "correct": 2, "explanation": "A chalazion is a chronic lipogranuloma of an obstructed Meibomian gland: painless, fixed to the tarsus, and able to press on the cornea to cause astigmatism."}'),
  ('e3697ebf-1b','{"options": ["Staphylococcus aureus", "Meibomian gland dysfunction", "Chlamydia trachomatis", "Demodex only"], "correct": 0, "explanation": "Anterior blepharitis (crusting and collarettes at the lash line) is most commonly staphylococcal or seborrheic. Posterior blepharitis is Meibomian gland dysfunction."}'),
  ('4f43abfb-26','{"options": ["Gland of Krause", "Meibomian gland", "Gland of Zeis", "Lacrimal gland"], "correct": 2, "explanation": "The external hordeolum (stye), the most common type, is an acute infection of the gland of Zeis at the outer lid margin. The internal hordeolum involves a Meibomian gland."}'),
  ('67b50c64-1e','{"options": ["Atrophy/laxity of the lower eyelid retractors", "Seventh nerve palsy", "Scarring of the conjunctiva", "Orbicularis spasm"], "correct": 0, "explanation": "Involutional (atonic) entropion, the most common form, results from age-related atrophy and laxity of the lower lid retractors, letting the lid roll inward."}'),
  ('33d3e6fd-2n','{"options": ["CN VII", "CN IV", "CN V", "CN III"], "correct": 0, "explanation": "CN VII (facial nerve) innervates the orbicularis oculi; its weakness causes lagophthalmos and risks corneal exposure."}'),
  ('05657482-25','{"options": ["Melanoma", "Squamous cell carcinoma", "Basal cell carcinoma", "Sebaceous carcinoma"], "correct": 2, "explanation": "Basal cell carcinoma is the most common eyelid malignancy; it is locally invasive but does not metastasise."}'),
  ('577ee07b-2s','{"options": ["Xanthelasma", "Keratoacanthoma", "Syringomas", "Milia"], "correct": 0, "explanation": "Xanthelasma are cutaneous lipid deposits at the medial lids, common in older women, sometimes signalling hyperlipidemia."}'),
  ('a04fd245-1v','{"options": ["Meibomian and Zeis glands", "Eyelids and conjunctiva", "Lacrimal and salivary glands", "Lacrimal sac and nasolacrimal duct"], "correct": 2, "explanation": "Mikulicz''s syndrome is chronic bilateral enlargement of the lacrimal AND salivary glands, seen with reticuloendothelial diseases."}'),
  ('ab46e040-2v','{"options": ["Adenoid cystic carcinoma", "Malignant mixed tumour", "Pleomorphic adenoma (benign mixed tumour)", "Lymphoma"], "correct": 2, "explanation": "Pleomorphic adenoma (benign mixed tumour) is the most common benign lacrimal gland tumour, presenting as painless upper-orbital fullness in younger patients."}'),
  ('38e02072-30','{"options": ["Adenoid cystic carcinoma (cylindroma)", "Dermoid cyst", "Pleomorphic adenoma", "Hemangioma"], "correct": 0, "explanation": "Adenoid cystic carcinoma (cylindroma) classically produces painful proptosis (it invades nerve/bone), unlike the painless pleomorphic adenoma. Pain is the differentiator."}'),
  ('5334d92f-1b','{"options": ["Reflex secretion", "Overproduction of tears", "Obstruction of the drainage system", "Corneal irritation"], "correct": 2, "explanation": "Epiphora is tear overflow from OBSTRUCTION of drainage (e.g., punctal scarring, NLD block), not from overproduction (which is lacrimation)."}'),
  ('0eb112d9-1s','{"options": ["Dacryoadenitis", "Chronic dacryocystitis", "Acute dacryocystitis", "Canaliculitis"], "correct": 2, "explanation": "Acute dacryocystitis regurgitates PUS on pressure over the sac; chronic dacryocystitis regurgitates BLOOD. This pus-vs-blood contrast is a classic trap."}'),
  ('937fc045-1f','{"options": ["Bilateral, caused by Pneumococcus", "Unilateral, caused by Staphylococcus", "Unilateral, caused by tuberculosis", "Bilateral, caused by Chlamydia"], "correct": 0, "explanation": "Neonatal dacryocystitis is typically bilateral, caused by Pneumococcus, from debris or failure of the epithelial tube (valve of Hasner) to open."}'),
  ('6c15c5b6-23','{"options": ["Vessels marked at the fornix", "Bright brick-red vessels that move with the conjunctiva", "Mucopurulent discharge", "A pink-lilac flush at the limbus that does NOT move and does NOT blanch with epinephrine"], "correct": 3, "explanation": "Ciliary injection is a pink/lilac flush maximal at the limbus, does not move with the conjunctiva, and does not blanch with 1:1000 epinephrine, signalling keratitis, uveitis, or glaucoma."}'),
  ('6982320f-3a','{"options": ["Phlycten", "Pinguecula", "Pannus", "Pterygium"], "correct": 1, "explanation": "A pinguecula is a benign yellowish nasal bulbar lesion that stops at the limbus. A pterygium invades the cornea and destroys Bowman''s membrane."}'),
  ('df779afb-1t','{"options": ["Invades the cornea and destroys Bowman''s membrane", "Occurs only temporally", "Is always painful", "Never relates to UV exposure"], "correct": 0, "explanation": "The pterygium is a fibrovascular growth that crosses the limbus onto the cornea and destroys Bowman''s membrane; UV/sunlight exposure is the main risk."}'),
  ('195effcf-1t','{"options": ["Lymphocytes", "Neutrophils (PMN)", "Eosinophils", "Plasma cells"], "correct": 2, "explanation": "Allergic conjunctivitis shows eosinophils. Bacterial shows neutrophils (PMN); viral shows lymphocytes."}'),
  ('33091d21-2n','{"options": ["Bacterial", "Allergic", "Chemical", "Viral"], "correct": 3, "explanation": "Follicles plus periauricular lymphadenopathy are hallmarks of viral conjunctivitis. Allergic shows papillae and itching without lymphadenopathy."}'),
  ('3a1ecb14-31','{"options": ["Adenovirus", "Haemophilus influenzae", "Neisseria gonorrhoeae", "Staphylococcus aureus"], "correct": 2, "explanation": "Neisseria gonorrhoeae causes hyperacute conjunctivitis with profuse purulent discharge and is one of few organisms that penetrate intact corneal epithelium, threatening perforation."}'),
  ('2f07745a-2h','{"options": ["Limbus only", "Caruncle", "Inferior palpebral conjunctiva", "Upper tarsal conjunctiva"], "correct": 3, "explanation": "Trachoma shows follicles at the UPPER tarsal conjunctiva, whereas adult inclusion (chlamydial) conjunctivitis shows follicles at the INFERIOR palpebral conjunctiva."}'),
  ('501835c8-1e','{"options": ["1-2% silver nitrate", "Tetracycline drops", "Erythromycin ointment", "Povidone-iodine"], "correct": 0, "explanation": "Crede''s prophylaxis is 1-2% silver nitrate, which itself can cause a mild chemical conjunctivitis at 12-24 hours. It historically prevented gonococcal ophthalmia neonatorum."}'),
  ('c38436f1-3b','{"options": ["Trachoma", "Giant papillary conjunctivitis", "Seasonal allergic conjunctivitis", "Vernal keratoconjunctivitis"], "correct": 3, "explanation": "Vernal keratoconjunctivitis (VKC) affects young males, is IgE-mediated, shows cobblestone papillae, and can cause shield ulcers. GPC is anchored to contact-lens/prosthesis wear."}'),
  ('b2493f7b-1v','{"options": ["Atopic dermatitis (eczema)", "Tuberculosis", "Cat-scratch disease", "Contact lens wear"], "correct": 0, "explanation": "AKC is chronic and about 95% associated with atopic dermatitis, frequently with corneal involvement (punctate erosions, filaments, defects)."}'),
  ('2a57f17d-3c','{"options": ["Chlamydia", "Adenovirus", "Cat-scratch disease (Bartonella henselae)", "Gonorrhea"], "correct": 2, "explanation": "Parinaud oculoglandular syndrome is a unilateral granulomatous conjunctivitis with ipsilateral preauricular lymphadenopathy, classically from cat-scratch disease (Bartonella henselae)."}'),
  ('f272114b-39','{"options": ["Pinguecula", "Pterygium", "Phlyctenular conjunctivitis", "Episcleritis"], "correct": 2, "explanation": "Phlyctenular conjunctivitis is a delayed hypersensitivity to bacterial antigens (TB, Staph) producing a limbal phlycten that may migrate onto the cornea, with photophobia and lacrimation."}'),
  ('4c8a4378-29','{"options": ["Fleischer ring", "Hudson-Stahli line", "Vogt''s striae", "Munson''s sign"], "correct": 0, "explanation": "The Fleischer ring, iron (hemosiderin) at the base of the cone, is the earliest sign of keratoconus, best seen with cobalt blue light. Munson''s sign is a later external finding."}'),
  ('aafb74af-2o','{"options": ["Ferry line", "Kayser-Fleischer ring", "Stocker line", "Krukenberg spindle"], "correct": 3, "explanation": "The Krukenberg spindle is a vertical melanin deposit on the endothelium in pigment dispersion syndrome (the vertical shape follows the aqueous convection current)."}'),
  ('c58934da-2y','{"options": ["Krukenberg spindle", "Kayser-Fleischer ring", "Hudson-Stahli line", "Fleischer ring"], "correct": 1, "explanation": "The Kayser-Fleischer ring is copper deposited at Descemet''s membrane in Wilson''s disease; about 95% of those with it have neurologic signs."}'),
  ('0b2a1d71-2v','{"options": ["Ferry line", "Stocker line", "Fleischer ring", "Hudson-Stahli line"], "correct": 3, "explanation": "The Hudson-Stahli line is a horizontal epithelial iron line of normal aging. Ferry (filtering bleb), Stocker (pterygium head), and Fleischer (keratoconus) are the other epithelial iron lines."}'),
  ('0fb4477a-1v','{"options": ["Ferry line", "Kayser-Fleischer ring", "Hudson-Stahli line", "Stocker line"], "correct": 3, "explanation": "The Stocker line is a vertical iron line at the advancing head of a pterygium. Ferry line sits at a filtering bleb."}'),
  ('aa1456ee-2d','{"options": ["Nebula", "Macula", "Staphyloma", "Leukoma"], "correct": 0, "explanation": "A nebula is the faintest, cloud-like corneal opacity, seen only with oblique illumination. Macula is a grayish daytime opacity; leukoma is the densest, white opacity."}'),
  ('737373c9-28','{"options": ["13.5 mm", "10 mm", "16 mm", "11.5 mm"], "correct": 0, "explanation": "Megalocornea has a corneal diameter greater than 13.5 mm with normal refraction and no glaucoma (deeper AC, enlarged lens). Microcornea is under 10 mm and hyperopic with glaucoma risk."}'),
  ('7ff78306-11','{"options": ["Copper", "Calcium salts", "Iron", "Extracellular lipid"], "correct": 3, "explanation": "Arcus senilis (gerontoxon) is a peripheral corneal ring of extracellular lipid (neutral fats, triglycerides, phospholipids, sterols) separated from the sclera by a clear zone; common with hypercholesterolemia."}'),
  ('d62f7ebf-17','{"options": ["Melanin", "Lipid", "Iron", "Calcium salts at the epithelium/Bowman''s membrane"], "correct": 3, "explanation": "Band keratopathy is a horizontal band of calcium salts at the epithelium/Bowman''s membrane, seen with hypercalcemia, hyperparathyroidism, or excess vitamin D."}'),
  ('53124c64-2k','{"options": ["Lacrimal gland extirpation", "Sjogren syndrome", "Stevens-Johnson syndrome / ocular pemphigoid", "Facial nerve palsy"], "correct": 2, "explanation": "Mucin-deficiency dry eye follows loss of conjunctival goblet cells in cicatrising disease such as Stevens-Johnson syndrome, ocular pemphigoid, and erythema multiforme. Sjogren causes aqueous deficiency."}'),
  ('fdc54993-1d','{"options": ["Deeper and bilateral, associated with tuberculosis, and can cause secondary open-angle glaucoma", "Painless and self-limiting", "Superficial and unilateral, associated with RA", "Confined to the cornea"], "correct": 0, "explanation": "Scleritis is deeper (scleral stroma), often bilateral, associated with PTB, and can cause secondary open-angle glaucoma. Episcleritis is superficial, unilateral, and often tied to RA/CTD."}'),
  ('b9b442bb-1o','{"options": ["Hyperopia", "High myopia with myopic chorioretinal degeneration", "Keratoconus", "Congenital glaucoma"], "correct": 1, "explanation": "Posterior staphyloma, a bulging of thinned posterior sclera, is associated with high (pathologic) myopia and myopic degeneration of the retina and choroid."}'),
  ('f7c63c44-1c','{"options": ["5-9 mmHg", "30-40 mmHg", "22-30 mmHg", "10-21 mmHg"], "correct": 3, "explanation": "Normal IOP is about 10-21 mmHg, with a daily fluctuation of 2-5 mmHg. IOP is typically highest in the morning."}'),
  ('05411866-1i','{"options": ["Gradual painless peripheral field loss", "Bilateral slow blurring", "Sudden painful red eye with a mid-dilated non-reactive pupil, cloudy cornea, and halos", "Optic disc cupping without symptoms"], "correct": 2, "explanation": "PACG is an emergency: sudden severe pain, a mid-dilated fixed pupil, corneal edema, halos, and often nausea/vomiting. POAG is the gradual, painless ''silent thief.''"}'),
  ('6433eb48-2w','{"options": ["50%", "25%", "95%", "75%"], "correct": 3, "explanation": "The trabecular meshwork accounts for about 75% of outflow resistance into the canal of Schlemm, so trabecular dysfunction underlies raised IOP in POAG."}'),
  ('978afdc1-2b','{"options": ["Betaxolol", "Levobunolol", "Carteolol", "Timolol"], "correct": 0, "explanation": "Betaxolol is cardio-selective (beta-1), safer in asthma/COPD than the non-selective timolol, which is contraindicated in asthma and heart block."}'),
  ('945fb11a-1g','{"options": ["Paresthesia (tingling of mouth and extremities)", "Bradycardia", "Bronchospasm", "Miosis"], "correct": 0, "explanation": "Acetazolamide (a carbonic anhydrase inhibitor) most commonly causes paresthesia; other effects include kidney stones, potassium loss, and transient myopia from ciliary swelling."}'),
  ('6127bb55-2q','{"options": ["Glycerol", "Acetazolamide", "Isosorbide", "Mannitol"], "correct": 0, "explanation": "Oral glycerol is metabolised and transiently raises blood glucose, so it is contraindicated in diabetes. Isosorbide is the diabetes-safe oral osmotic."}'),
  ('9e829eec-3d','{"options": ["Glycerol", "Mannitol", "Isosorbide", "Urea"], "correct": 1, "explanation": "Mannitol is IV-only, stays intravascular due to its large molecular weight, and is safe in renal disease. Urea (IV) is contraindicated in renal disease."}'),
  ('7f5af38b-w','{"options": ["Causing miosis", "Reducing aqueous production", "Increasing uveoscleral outflow", "Blocking beta receptors"], "correct": 2, "explanation": "Latanoprost, a prostaglandin analogue, increases uveoscleral outflow. It can also cause iris and lash pigmentation."}'),
  ('b9f2f223-2j','{"options": ["Closed angle WITHOUT pupillary block", "Closed angle WITH pupillary block", "Congenital", "Open angle"], "correct": 0, "explanation": "Neovascularisation on the iris (rubeosis) drags a fibrovascular membrane across the angle, closing it WITHOUT pupillary block (neovascular glaucoma)."}'),
  ('7679a49b-1t','{"options": ["Pigment on the endothelium", "A swollen intumescent lens pushing the iris forward", "Protein leaking from a hypermature cataract with macrophages blocking the trabeculum", "Posterior synechiae"], "correct": 2, "explanation": "Phacolytic glaucoma is open-angle: lens protein leaks from a hypermature cataract and macrophages clog the trabecular meshwork. Phacomorphic glaucoma (swollen lens) is closed-angle."}'),
  ('3369052b-42','{"options": ["Horner''s syndrome", "Marcus Gunn pupil", "Argyll-Robertson pupil", "Adie''s tonic pupil"], "correct": 2, "explanation": "The Argyll-Robertson pupil is bilateral, light-near dissociated, and highly specific for neurosyphilis (tabes dorsalis)."}'),
  ('4dd9388c-3d','{"options": ["Marcus Gunn pupil", "Argyll-Robertson pupil", "Adie''s tonic pupil", "Amaurotic pupil"], "correct": 2, "explanation": "Adie''s tonic pupil results from ciliary ganglion / postganglionic parasympathetic damage; denervation supersensitivity makes it constrict to 0.1% pilocarpine that would not affect a normal pupil."}'),
  ('d55d05d7-2o','{"options": ["Horner''s syndrome", "A relative afferent pupillary defect (Marcus Gunn)", "Hippus", "Argyll-Robertson pupil"], "correct": 1, "explanation": "A relative afferent pupillary defect (Marcus Gunn pupil) reflects an afferent (optic nerve or severe retinal) lesion; the affected pupil dilates on direct light because its afferent signal is weaker."}'),
  ('3803506e-2m','{"options": ["Anisocoria", "Hippus", "Polycoria", "Corectopia"], "correct": 1, "explanation": "Hippus is rhythmic, involuntary pupillary oscillation unrelated to light or accommodation. Anisocoria is unequal pupils; corectopia is a displaced pupil."}'),
  ('7c4643f6-1q','{"options": ["Upward (superior)", "Nasally", "Temporally", "Downward (inferior)"], "correct": 0, "explanation": "In Marfan syndrome the lens dislocates UP (superiorly). In homocystinuria it dislocates DOWN. ''Marfan = up, Homocystinuria = down'' is the classic trap."}'),
  ('ed2e78bc-1h','{"options": ["Anteriorly into the AC", "Down", "Up", "It does not dislocate"], "correct": 1, "explanation": "Homocystinuria (cystathionine beta-synthase deficiency) dislocates the lens DOWN (inferiorly). Marfan dislocates it up."}'),
  ('ee1b5a6d-2l','{"options": ["Nuclear sclerosis", "Galactosemic cataract", "Cortical cataract", "Posterior subcapsular cataract"], "correct": 0, "explanation": "Nuclear sclerosis increases lens index and induces a myopic shift, giving transient ''second sight'' (senopia) that lets a presbyope read without glasses."}'),
  ('ea16d864-2j','{"options": ["Anterior polar", "Posterior subcapsular", "Cortical", "Nuclear"], "correct": 1, "explanation": "Posterior subcapsular cataract (PSC) is the most common age-related type and the classic steroid-induced cataract; steroids also cause open-angle glaucoma."}'),
  ('bb7532e3-26','{"options": ["1 week", "1 year", "1 month", "72 hours"], "correct": 3, "explanation": "The true diabetic (snowflake) cataract is bilateral and can mature within 72 hours, driven by osmotic sorbitol accumulation."}'),
  ('3f373015-2d','{"options": ["Sunflower", "Rosette", "Oil droplet", "Christmas tree"], "correct": 2, "explanation": "Galactosemia produces an oil-droplet cataract as dulcitol (galactitol) accumulates in the lens."}'),
  ('dd517b7b-3e','{"options": ["Topical steroids", "YAG laser capsulotomy", "Repeat ECCE", "Trabeculectomy"], "correct": 1, "explanation": "Posterior capsule opacification after ECCE is treated with Nd:YAG laser capsulotomy, opening the cloudy capsule behind the IOL."}'),
  ('bc26af02-2w','{"options": ["Phacolytic uveitis", "Posterior vitreous detachment", "Sympathetic ophthalmia", "Endophthalmitis"], "correct": 2, "explanation": "Sympathetic ophthalmia is bilateral granulomatous uveitis affecting the sympathizing (uninjured) eye weeks to years after a penetrating injury to the other eye."}'),
  ('8306e727-2p','{"options": ["Retinal detachment", "Central retinal vein occlusion", "Central retinal artery occlusion", "Vitreous hemorrhage"], "correct": 2, "explanation": "CRAO gives sudden painless vision loss, a pale ischemic retina, and a cherry-red spot at the macula (the thin fovea reveals the intact choroidal circulation). Treat within ~90 minutes."}'),
  ('61c63a6b-2i','{"options": ["CRVO", "ARMD", "Retinitis pigmentosa", "CRAO"], "correct": 0, "explanation": "Central retinal vein occlusion (CRVO) produces the classic ''blood and thunder'' fundus: diffuse flame hemorrhages, dilated tortuous veins, and disc edema."}'),
  ('96fbf519-19','{"options": ["Serous", "Rhegmatogenous", "Exudative", "Tractional"], "correct": 1, "explanation": "Rhegmatogenous retinal detachment, from a retinal break allowing fluid under the neurosensory retina, is the most common type. Symptoms include flashes, floaters, and a curtain over vision."}'),
  ('970f8233-2n','{"options": ["ARMD", "Choroideremia", "Retinitis pigmentosa", "Diabetic retinopathy"], "correct": 2, "explanation": "Retinitis pigmentosa is a hereditary rod-cone dystrophy: bone-spicule pigment, night blindness early, and progressive peripheral (tunnel) field loss."}'),
  ('53b045c5-2j','{"options": ["MRI", "CT scan", "Plain radiograph", "Ultrasound"], "correct": 0, "explanation": "MRI is contraindicated with a ferrous (iron) intraocular foreign body because the magnetic field can move it; CT is used instead. Siderosis attenuates the ERG b-wave and causes heterochromia."}'),
  ('076918b0-2g','{"options": ["Purely allergic", "Traumatic only", "Granulomatous (e.g., sarcoidosis, TB)", "Non-granulomatous"], "correct": 2, "explanation": "Large greasy ''mutton-fat'' KPs indicate granulomatous uveitis, seen in sarcoidosis and tuberculosis, versus the fine KPs of non-granulomatous uveitis."}'),
  ('5be70df6-2v','{"options": ["Infraorbital nerve", "Optic nerve", "Supraorbital nerve", "Frontal nerve"], "correct": 0, "explanation": "The orbital floor fracture involves the infraorbital canal, so infraorbital nerve anesthesia (lower lid, cheek, upper lip, upper teeth) is characteristic, along with diplopia and enophthalmos."}'),
  ('19921171-26','{"options": ["Sleep upright", "Take antibiotics", "Blow the nose", "Apply ice packs"], "correct": 2, "explanation": "Patients must not blow the nose, which can force infected sinus contents (and air) through the fracture into the orbit, causing orbital emphysema or infection."}'),
  ('a274836a-2z','{"options": ["Weiss ring", "Vossius ring", "Fleischer ring", "Kayser-Fleischer ring"], "correct": 1, "explanation": "The Vossius ring is pigment transferred from the iris to the anterior lens capsule during blunt trauma, marking transient forceful miosis at the moment of impact."}'),
  ('8f29a18e-2w','{"options": ["Shaken baby syndrome", "Persistent fetal vasculature", "Retinopathy of prematurity", "Coats disease"], "correct": 0, "explanation": "Shaken baby syndrome causes bilateral, multilayered retinal hemorrhages extending to the periphery from rotational acceleration-deceleration, with mortality over 25%."}'),
  ('37db5384-1w','{"options": ["4.5 mm to 4.0 mm", "2.5 mm to 2.0 mm", "3.0 mm to 3.6 mm", "3.6 mm (age 15-20) to 3.0 mm (age 70)"], "correct": 3, "explanation": "AC depth decreases from about 3.6 mm in youth to about 3.0 mm by age 70 as the lens enlarges and bows the iris forward, narrowing the angle and raising PACG risk."}'),
  ('f6e3431a-1h','{"options": ["Staying constant lifelong", "Decreasing 25% per decade after age 30", "Increasing 25% per decade after 30", "Doubling by age 70"], "correct": 1, "explanation": "Aqueous production falls about 25% per decade after age 30 as the ciliary body thickens and shortens."}'),
  ('ecea4e1c-3d','{"options": ["Papillitis", "Papilledema", "Retrobulbar neuritis", "Optic atrophy"], "correct": 1, "explanation": "Papilledema is bilateral disc swelling from raised ICP; central vision is spared early and the blind spot enlarges, with headache, vomiting, and possible sixth nerve palsy."}'),
  ('660be9ad-2v','{"options": ["Papilledema", "Optic atrophy", "Retrobulbar neuritis", "Papillitis"], "correct": 2, "explanation": "Retrobulbar neuritis is optic neuritis behind the globe, so the disc looks normal initially despite marked vision loss; it is strongly associated with multiple sclerosis, with later disc pallor."}'),
  ('2e6a6f51-1d','{"options": ["Homonymous hemianopia", "Central scotoma", "Monocular blindness", "Bitemporal hemianopia"], "correct": 3, "explanation": "A central chiasmal lesion (e.g., pituitary tumour) compresses crossing nasal fibres, producing bitemporal hemianopia."}'),
  ('9ff0bb93-1m','{"options": ["Inferior homonymous quadrantanopia (pie on the floor)", "Monocular blindness", "Bitemporal hemianopia", "Superior homonymous quadrantanopia (pie in the sky)"], "correct": 3, "explanation": "Meyer''s loop carries inferior retinal fibres (superior field); its lesion gives a superior homonymous quadrantanopia, ''pie in the sky.''"}'),
  ('9ba3e027-28','{"options": ["Bitemporal loss", "RAPD", "Macular sparing", "Central scotoma"], "correct": 2, "explanation": "Occipital lesions produce homonymous hemianopia with macular sparing, attributed to the dual (middle cerebral) blood supply to the macular cortex."}'),
  ('20e3b16b-1g','{"options": ["Vertical diplopia with head tilt", "Esotropia with horizontal diplopia", "Ptosis, an eye ''down and out'', and a fixed dilated pupil", "Inability to close the eye"], "correct": 2, "explanation": "Complete third-nerve palsy gives ptosis, a ''down and out'' eye (unopposed LR and SO), and a fixed dilated pupil (parasympathetic involvement)."}'),
  ('159f7489-2m','{"options": ["CN VI", "CN VII", "CN IV", "CN III"], "correct": 0, "explanation": "CN VI (abducens) has the longest intracranial course and is the first to fail with raised ICP, producing esotropia and horizontal diplopia as a false localising sign."}'),
  ('08ac50af-1t','{"options": ["Maxillary sinusitis", "Sphenoid sinusitis", "Frontal sinusitis", "Ethmoiditis"], "correct": 0, "explanation": "Maxillary sinusitis has no ocular manifestations. Ethmoiditis causes orbital cellulitis, frontal sinusitis causes upper-inner orbital swelling, and sphenoid sinusitis can cause optic neuritis and atrophy."}'),
  ('17a05011-21','{"options": ["Newborns", "Working-age adults", "Children under 5", "People over 75"], "correct": 1, "explanation": "Diabetic retinopathy is the leading cause of blindness in working-age adults; proliferative disease brings neovascularisation, vitreous hemorrhage, and tractional detachment."}'),
  ('de80f4eb-26','{"options": ["Peripheral vision", "Central vision", "Superior field only", "Color vision only"], "correct": 1, "explanation": "ARMD damages the macula and causes central vision loss (blurred, distorted), in contrast to glaucoma which takes peripheral vision first."}'),
  ('32b58c5a-2t','{"options": ["Ankyloblepharon", "Symblepharon", "Distichiasis", "Blepharophimosis"], "correct": 1, "explanation": "Symblepharon is adhesion between the inner eyelid (palpebral conjunctiva) and the globe (bulbar conjunctiva), often from chemical/alkali burns or trachoma. Ankyloblepharon is adhesion of the lid margins to each other."}'),
  ('25328a41-1m','{"options": ["Inward misdirection of normally sited lashes rubbing the cornea", "White lashes", "An extra row of lashes from Meibomian orifices", "Absence of lashes"], "correct": 0, "explanation": "Trichiasis is inward misdirection of normally positioned lashes (from entropion, trachoma, scarring). Distichiasis is an extra (supernumerary) row of lashes arising from the Meibomian orifices."}'),
  ('2672d163-2v','{"options": ["Lamellar (non-penetrating) keratoplasty", "Penetrating keratoplasty", "Keratomileusis", "Trabeculectomy"], "correct": 0, "explanation": "Lamellar (non-penetrating) keratoplasty replaces only superficial corneal layers and does not enter the AC. Penetrating keratoplasty replaces the full corneal thickness."}'),
  ('e472aa72-2q','{"options": ["Schwalbe''s line", "Sampaolesi''s line", "Ferry line", "Hudson-Stahli line"], "correct": 1, "explanation": "Sampaolesi''s line is trabecular pigment deposition in pigment dispersion syndrome, which can raise IOP (pigmentary glaucoma). The triad also includes the Krukenberg spindle and iris transillumination defects."}'),
  ('4073edd3-2o','{"options": ["Small, round, and highly curved with high refractive power", "Large and flat", "Dislocated superiorly", "Absent"], "correct": 0, "explanation": "In Weill-Marchesani the microspherophakic lens is small, round, and highly curved (high plus power, myopia), and can block the pupil to cause angle-closure with pupillary block."}'),
  ('9f2db7de-1p','{"options": ["Neovascular membrane over the angle", "A swollen lens", "Trabecular pigment", "360° posterior synechiae blocking aqueous at the pupil, bowing the iris forward"], "correct": 3, "explanation": "Iris bombe is angle closure WITH pupillary block: the pupil margin is bound to the lens by posterior synechiae, aqueous collects behind the iris, and the peripheral iris bows forward onto the meshwork."}'),
  ('09840804-2g','{"options": ["Chronic dacryocystitis", "Cataract", "Facial nerve palsy", "Ocular involvement (nasociliary nerve)"], "correct": 3, "explanation": "Hutchinson''s sign reflects nasociliary nerve involvement and predicts ocular involvement in herpes zoster ophthalmicus (V1 distribution)."}'),
  ('4a567874-1r','{"options": ["Complete healing with no residua", "Scar (fibrous) tissue as follicles disappear", "Minute early follicles", "Intense acute inflammation with purulent discharge"], "correct": 1, "explanation": "Trachoma stage III (cicatricial) shows scar tissue forming as follicles disappear; sequelae include trichiasis, entropion, symblepharon, and corneal opacity. Tetracycline is the topical drug of choice."}'),
  ('01d1687f-10','{"options": ["Corneal arcus", "A benign vitreous floater", "A severe intraocular infection, often after surgery or trauma, needing urgent treatment", "A superficial lid infection"], "correct": 2, "explanation": "Endophthalmitis is a severe infection of the intraocular cavities, a complication of surgery, penetrating trauma, or hematogenous spread, and is an emergency."}'),
  ('aa1c8120-13','{"options": ["Severe hyperopia", "Simple astigmatism", "High myopia", "Emmetropia"], "correct": 0, "explanation": "Loss of the lens (aphakia) removes about +15 to +20 D of power, leaving severe hyperopia that must be corrected with a strong plus lens, contact lens, or IOL."}'),
  ('1f491bf5-1f','{"options": ["Closed angle with pupillary block", "Neovascular", "Congenital", "Open angle (trabecular outflow reduced)"], "correct": 3, "explanation": "Chronic corticosteroids raise IOP by an open-angle mechanism (reduced trabecular outflow). Steroids also cause posterior subcapsular cataracts."}'),
  ('c41cb343-2m','{"options": ["Closing both eyes", "Tilting the head toward the affected side", "Turning the face down", "Tilting the head to the opposite (contralateral) side"], "correct": 3, "explanation": "In superior oblique (CN IV) palsy the patient tilts the head to the opposite shoulder to reduce vertical diplopia (a positive Bielschowsky head-tilt test on the affected side)."}'),
  ('aa2e8739-2e','{"options": ["The blood-aqueous barrier blocks it", "It is too lipophilic", "It is destroyed by tears", "The cornea is avascular"], "correct": 0, "explanation": "The blood-aqueous barrier (between the ciliary body capillary and the iris/ciliary epithelium) prevents most systemic drugs from reaching the anterior segment, so topical dosing gives higher anterior-segment concentration."}'),
  ('f353b152-2o','{"options": ["Subconjunctival", "Sub-Tenon", "Retrobulbar", "Intracameral"], "correct": 3, "explanation": "Intracameral injection places drug directly into the anterior chamber (e.g., intracameral antibiotics for endophthalmitis prophylaxis). Intravitreal targets the vitreous."}'),
  ('26d16341-2n','{"options": ["Cationic surfactant/wetting agent that also acts as a bactericidal preservative", "Viscosity agent", "Chelating antioxidant", "Bacteriostatic mercurial"], "correct": 0, "explanation": "BAK is a cationic surfactant and wetting agent that disrupts the epithelium to enhance penetration of lipid-insoluble drugs such as carbachol, and is also a bactericidal preservative."}'),
  ('b156b9fb-1t','{"options": ["5.0 and 6.0", "3.0 and 5.0", "6.6 and 7.8", "8.5 and 9.5"], "correct": 2, "explanation": "Solutions with pH below 6.6 or above 7.8 cause discomfort; buffering agents (commonly boric acid salts) keep the pH tolerable."}'),
  ('b5b41e73-1m','{"options": ["Citric acid salts", "Acetic acid salts", "Phosphoric acid salts", "Boric acid salts"], "correct": 3, "explanation": "Boric acid salts are the most common ophthalmic buffering agents."}'),
  ('bfb61a0a-1i','{"options": ["Bacteriostatic", "A wetting agent", "An antioxidant", "Bactericidal"], "correct": 0, "explanation": "Thimerosal is a bacteriostatic mercurial preservative; side effects include allergy and band keratopathy. BAK, by contrast, is bactericidal."}'),
  ('228f58be-1o','{"options": ["Needs maximal wetting", "Is very water soluble", "Is rapidly destroyed by water", "Requires shaking before use"], "correct": 2, "explanation": "Oily solutions are used for drugs rapidly hydrolysed in water, such as diisopropyl fluorophosphate (DFP)."}'),
  ('83e97cfd-19','{"options": ["Is a corneal collagen shield", "Is a single-use paper strip", "Releases pilocarpine slowly (20 mcg/hr for 7 days) from a hydrophilic plastic reservoir", "Is an ointment base"], "correct": 2, "explanation": "The Ocusert is an ovoid hydrophilic device placed in the fornix that releases pilocarpine at 20 mcg/hr for about 7 days."}'),
  ('c9841afa-34','{"options": ["Chondroitin sulfate alone", "Trypan blue", "Hydroxypropyl methylcellulose", "Sodium hyaluronate"], "correct": 3, "explanation": "Sodium hyaluronate is a high-MW, high-viscosity, non-allergenic viscoelastic (a natural component of vitreous/aqueous) used to protect the endothelium during ECCE/IOL surgery."}'),
  ('ebff0ee7-1k','{"options": ["It stains contact lenses", "It has a longer shelf life", "It is more expensive", "Anesthetic used with fluorescein can devitalise cells and cause false-positive staining"], "correct": 3, "explanation": "Rose Bengal is used before fluorescein/anesthetic to avoid false-positive dry-eye staining from anesthetic-devitalised cells. Rose Bengal stains devitalised cells and mucus and has antiviral property."}'),
  ('2f6dfccd-23','{"options": ["Dissolves the lens", "Permanently stains the soft lens", "Causes miosis", "Is toxic to the cornea"], "correct": 1, "explanation": "Sodium fluorescein permanently stains soft contact lenses; fluorexon (high MW) is the alternative that does not stain most soft lenses."}'),
  ('5f19c6c0-2f','{"options": ["Fluorescein", "Indocyanine green (ICG)", "Lissamine green", "Rose Bengal"], "correct": 1, "explanation": "Indocyanine green (ICG), with peak fluorescence in the infrared (~835 nm), penetrates the RPE better than fluorescein and is best for choroidal neovascular membranes."}'),
  ('000373be-1r','{"options": ["Calcium in band keratopathy", "Arsenic", "Corneal iron (ferric) rust stains", "Copper deposits"], "correct": 2, "explanation": "Deferoxamine binds ferric ions (Fe3+) and is used to remove corneal metallic rust stains (siderosis). EDTA removes calcium in band keratopathy; penicillamine binds copper."}'),
  ('7a79c4f0-1m','{"options": ["Iron", "Copper", "Calcium", "Arsenic"], "correct": 2, "explanation": "EDTA chelates calcium (and other divalent cations), removing calcium from Bowman''s membrane in band keratopathy; it also inhibits collagenase and preserves solutions."}'),
  ('c3954e9f-2k','{"options": ["Homatropine", "Atropine", "Cyclopentolate", "Tropicamide"], "correct": 1, "explanation": "Atropine is the strongest, longest-acting cycloplegic (up to 14 days), the prototype anticholinergic, and the DOC for uveitis and cycloplegic refraction in young children."}'),
  ('b8d7fbd2-17','{"options": ["Tropicamide", "Atropine", "Cyclopentolate", "Scopolamine"], "correct": 0, "explanation": "Tropicamide is the DOC (and most commonly used) for routine mydriasis: fast onset, short duration (4-6 hrs), weak cycloplegia, and safe in cardiovascular patients."}'),
  ('6cc2cef5-19','{"options": ["Homatropine", "Cyclopentolate", "Tropicamide", "Atropine"], "correct": 1, "explanation": "Cyclopentolate is the DOC for routine cycloplegia. In children, 2% can cause CNS effects (drowsiness, hallucination, seizures), so 0.5-1% with punctal occlusion is used."}'),
  ('adddf536-1i','{"options": ["Bradycardia and salivation", "Mad as a hatter, red as a beet, dry as a bone, blind as a bat, hot as a hare", "Cold, wet, and constricted pupils", "Miosis and diarrhea"], "correct": 1, "explanation": "Antimuscarinic (atropine) toxicity gives the anticholinergic toxidrome: delirium, flushing, dry skin/mucosa, blurred vision (cycloplegia/mydriasis), and hyperthermia. Physostigmine 1-4 mg IV is the treatment."}'),
  ('6b744b9a-1e','{"options": ["Atropine", "2% pilocarpine or 0.5% dapiprazole", "Phenylephrine 10%", "Timolol"], "correct": 1, "explanation": "Mydriasis from tropicamide is reversed within about 90 minutes by 2% pilocarpine (a miotic) or 0.5% dapiprazole (an alpha-1 blocker, REV-EYES)."}'),
  ('a200d29e-22','{"options": ["Glycopeptide", "Amino-amide type", "Ester type", "Amide type"], "correct": 2, "explanation": "The approved topical ophthalmic anesthetics (proparacaine, benoxinate, tetracaine, cocaine) are all ester-type local anesthetics."}'),
  ('1a5d389a-1d','{"options": ["Lidocaine", "Tetracaine", "Cocaine 4%", "Proparacaine 0.5%"], "correct": 3, "explanation": "Proparacaine 0.5% is the most common topical ophthalmic anesthetic and the DOC for tonometry. Benoxinate is combined with fluorescein in Fluress."}'),
  ('246200ae-17','{"options": ["Blocking norepinephrine reuptake", "Inhibiting acetylcholinesterase", "Blocking acetylcholine release at the neuromuscular junction", "Antagonising muscarinic receptors"], "correct": 2, "explanation": "Botulinum toxin A blocks ACh release at the neuromuscular junction (inhibiting calcium-dependent exocytosis), producing temporary paralysis (~3 months) used for strabismus and blepharospasm."}'),
  ('0e0637c8-1k','{"options": ["Osmotic dehydration", "Increasing uveoscleral outflow", "Increasing trabecular outflow via miosis", "Decreasing aqueous secretion"], "correct": 1, "explanation": "Prostaglandin analogues (latanoprost, travoprost, bimatoprost) increase uveoscleral outflow and are first-line for open-angle glaucoma (once-daily, few systemic effects). Cap colour is turquoise."}'),
  ('54c4d9e1-1d','{"options": ["Corneal edema", "Miosis", "Cataract", "Increased iris pigmentation and eyelash growth"], "correct": 3, "explanation": "Latanoprost causes increased iris brown pigmentation (heterochromia) and longer, darker lashes, plus redness and photosensitivity."}'),
  ('8be29b09-22','{"options": ["Diabetes insipidus", "Migraine", "Bronchial asthma and COPD", "Hypertension"], "correct": 2, "explanation": "Non-selective beta-blockers (timolol) block bronchial beta-2 receptors, risking bronchoconstriction, so they are contraindicated in asthma/COPD (and can mask hypoglycemia in diabetes)."}'),
  ('7a623150-16','{"options": ["Inhibiting adenylate cyclase to decrease aqueous secretion", "Osmotic gradient", "Increasing uveoscleral outflow", "Opening the trabeculum by miosis"], "correct": 0, "explanation": "Beta-blockers inhibit adenylate cyclase at the ciliary process, decreasing aqueous humour secretion."}'),
  ('0931f3e8-1b','{"options": ["Bronchospasm", "Bradycardia", "Paresthesia (tingling of mouth and extremities)", "Hypertension"], "correct": 2, "explanation": "Acetazolamide (a systemic CAI) most commonly causes paresthesia; other effects include kidney stones, potassium loss, transient myopia, metabolic acidosis, and rarely aplastic anemia."}'),
  ('cecadcbe-1m','{"options": ["Acetazolamide", "Methazolamide", "Brinzolamide", "Dorzolamide"], "correct": 3, "explanation": "Dorzolamide 2% is a topical CAI combined with timolol (Cosopt) for enhanced IOP lowering. Brinzolamide is another topical CAI."}'),
  ('7f95e0ed-3s','{"options": ["Naphazoline", "Clonidine", "Phenylephrine", "Apraclonidine"], "correct": 3, "explanation": "Apraclonidine (an alpha-1/alpha-2 agonist with no MSA) lowers IOP without systemic BP/PR effects and is used after argon laser trabeculoplasty, iridotomy, or YAG capsulotomy."}'),
  ('60bbb9fd-1c','{"options": ["Contracting the ciliary (Brucke''s) muscle to open the trabecular meshwork", "Decreasing aqueous secretion", "Increasing uveoscleral outflow", "Osmotic dehydration"], "correct": 0, "explanation": "Pilocarpine, a direct cholinergic agonist, contracts the ciliary muscle, pulling on the scleral spur to open the trabecular meshwork and increase conventional outflow."}'),
  ('1d64dee7-2x','{"options": ["Physostigmine", "Carbachol", "Pilocarpine", "Echothiophate"], "correct": 3, "explanation": "Echothiophate is a long-acting irreversible organophosphate anticholinesterase used for accommodative esotropia; it can cause iris cysts (reversed by 2.5% phenylephrine)."}'),
  ('013390e5-1m','{"options": ["Retinal detachment", "Open-angle glaucoma", "Cataract", "Neovascular/uveitic glaucoma"], "correct": 1, "explanation": "Miotics are used in open-angle (and angle-closure) glaucoma. They are contraindicated in cataract, patients under 40, neovascular/uveitic glaucoma, retinal detachment, and asthma."}'),
  ('08a6ab2a-25','{"options": ["Muscarinic M3", "Beta-2", "Alpha-2", "Alpha-1"], "correct": 3, "explanation": "Alpha-1 receptors on the iris dilator pupillae mediate mydriasis. Phenylephrine (alpha-1 agonist) dilates without cycloplegia."}'),
  ('20053a90-2l','{"options": ["Decreases aqueous secretion", "Opens the trabeculum", "Causes miosis", "Increases aqueous secretion"], "correct": 3, "explanation": "Beta-2 stimulation at the ciliary process INCREASES aqueous secretion, while alpha-2 stimulation DECREASES it. Timolol blocks beta-2 there, lowering aqueous production."}'),
  ('c302b11d-i','{"options": ["Indirect sympathomimetic", "Muscarinic antagonist", "Direct alpha-1 agonist", "Beta-2 agonist"], "correct": 2, "explanation": "Phenylephrine is a selective direct alpha-1 agonist: 2.5-10% for mydriasis, 0.12% as a decongestant; it produces mydriasis without cycloplegia."}'),
  ('957fa186-1u','{"options": ["Cholinesterase inhibitor", "Muscarinic agonist", "Beta-blocker", "Selective alpha-1 blocker"], "correct": 3, "explanation": "Dapiprazole 0.5% is a selective alpha-1 blocker that reverses the mydriasis of phenylephrine and tropicamide."}'),
  ('3bb0b33c-1k','{"options": ["Shows hippus", "Fails to dilate at all lesion levels", "Dilates widely", "Constricts"], "correct": 1, "explanation": "Cocaine 4% blocks NE reuptake; a Horner''s (sympathetically denervated) pupil fails to dilate at any lesion level, confirming the diagnosis."}'),
  ('16fbd43b-1g','{"options": ["Reverse the mydriasis", "Measure IOP", "Confirm the diagnosis at any level", "Localise the lesion: it dilates central/preganglionic lesions but FAILS to dilate a postganglionic lesion"], "correct": 3, "explanation": "Hydroxyamphetamine releases NE from intact postganglionic terminals, so it dilates central/preganglionic Horner''s but fails to dilate a postganglionic (3rd-order) lesion, localising it."}'),
  ('815a8f3c-1x','{"options": ["Cataract", "Cystoid macular edema", "Corneal ulcer", "Miosis"], "correct": 1, "explanation": "Epinephrine can cause cystoid macular edema in aphakic eyes; it is also contraindicated in angle-closure glaucoma, cardiovascular disease, and hyperthyroidism, and causes adrenochrome deposits."}'),
  ('d1c7b394-23','{"options": ["Glaucoma", "Uveitis", "Dry eye", "Myasthenia gravis"], "correct": 3, "explanation": "Neostigmine (Prostigmin) is the DOC for myasthenia gravis treatment; edrophonium (Tensilon test) is used for its diagnosis."}'),
  ('841ba314-1f','{"options": ["DNA gyrase (topoisomerase II)", "Phospholipase A2", "Cell wall transpeptidase", "The 30S ribosomal subunit"], "correct": 0, "explanation": "Fluoroquinolones inhibit bacterial DNA gyrase (topoisomerase II), blocking DNA replication; they have broad spectrum and excellent corneal penetration."}'),
  ('70deb085-2y','{"options": ["Macrolides", "Glycopeptides", "Aminoglycosides", "Sulfonamides"], "correct": 2, "explanation": "Aminoglycosides (gentamicin, tobramycin) cover gram-negatives including Pseudomonas; they bind the 30S ribosome. Prolonged use can cause superficial keratitis."}'),
  ('bad05190-1e','{"options": ["Aplastic anemia", "Nephrotoxicity", "Photosensitivity", "Ototoxicity"], "correct": 0, "explanation": "Chloramphenicol (a 50S protein-synthesis inhibitor) can cause aplastic anemia (bone marrow toxicity) and gray baby syndrome in neonates."}'),
  ('1778bcb1-1r','{"options": ["PABA, blocking dihydropteroate synthetase (folate synthesis)", "Ergosterol", "Folic acid end-product", "D-Ala-D-Ala"], "correct": 0, "explanation": "Sulfonamides are PABA analogues that inhibit dihydropteroate synthetase, blocking bacterial folic acid synthesis (bacteriostatic)."}'),
  ('b39956ed-2b','{"options": ["Penicillin-binding proteins", "The 50S ribosome", "DNA gyrase", "D-Ala-D-Ala terminus of peptidoglycan"], "correct": 3, "explanation": "Vancomycin, a glycopeptide, binds the D-Ala-D-Ala terminus of peptidoglycan precursors (a different site than beta-lactams), and is reserved for gram-positive endophthalmitis including MRSA."}'),
  ('fe23074d-1p','{"options": ["Natamycin", "Ganciclovir", "Idoxuridine", "Trifluridine (TFT) 1%"], "correct": 3, "explanation": "Trifluridine (TFT) 1% is the DOC for HSV epithelial keratitis; idoxuridine is the historical, more toxic first agent. Ganciclovir treats CMV retinitis."}'),
  ('651628cc-23','{"options": ["Natamycin 5%", "Amphotericin B", "Trifluridine", "Fluconazole"], "correct": 0, "explanation": "Natamycin 5%, a polyene, is the DOC for filamentous fungal keratitis, despite having the poorest corneal penetration. Amphotericin B is the DOC for Candida keratitis/endophthalmitis."}'),
  ('77feeda9-1n','{"options": ["HSV epithelial keratitis", "Bacterial conjunctivitis", "Fungal keratitis", "CMV retinitis"], "correct": 3, "explanation": "Ganciclovir, a guanosine analogue, treats CMV retinitis (e.g., AIDS-related), available as an intravitreal implant, oral, or IV."}'),
  ('c06105a7-2x','{"options": ["Fluorometholone 0.1%", "Prednisolone acetate 1%", "Medrysone 1%", "Loteprednol 0.2%"], "correct": 1, "explanation": "Prednisolone acetate 1% (a suspension, must be shaken) has the best corneal penetration and is the DOC for intraocular inflammation."}'),
  ('4c991f83-38','{"options": ["Fluorometholone (FML)", "Dexamethasone", "Betamethasone", "Prednisolone acetate"], "correct": 0, "explanation": "Fluorometholone (FML) penetrates the AC poorly and causes less IOP rise, so it is used for anterior/surface inflammation with lower glaucoma risk."}'),
  ('035dce4f-20','{"options": ["Reversing mydriasis", "Lowering IOP", "Treating fungal keratitis", "Preventing intraoperative miosis"], "correct": 3, "explanation": "NSAIDs inhibit COX and prostaglandin-mediated miosis, so they are added to irrigation or given pre-op to prevent intraoperative miosis. Ketorolac is the most-used ophthalmic NSAID."}'),
  ('f627090d-20','{"options": ["Miosis and myopia", "Nyctalopia and xerosis", "Corneal arcus and pterygium", "Posterior subcapsular cataract and open-angle glaucoma"], "correct": 3, "explanation": "Prolonged corticosteroids cause posterior subcapsular cataract and open-angle glaucoma (reduced trabecular outflow), plus corneal thinning and infection risk."}'),
  ('6870e00b-1a','{"options": ["Blocking beta receptors", "Reducing T-cell-mediated inflammation to increase tear production", "Adding a lipid layer", "Osmotic dehydration"], "correct": 1, "explanation": "Topical cyclosporine A is an immunomodulator that reduces T-cell-mediated ocular surface inflammation, increasing tear production over 3-6 months of BID use."}'),
  ('991ef9f7-1y','{"options": ["Prostaglandins", "Pilocarpine", "Antihistamines (e.g., diphenhydramine)", "Beta-agonists"], "correct": 2, "explanation": "Antihistamines (anticholinergic effect) reduce tear production and cause dry eye, as do oral retinoids, anticholinergics, and diuretics."}'),
  ('1fa123ad-2a','{"options": ["Roth spots", "Cherry-red spot", "Bull''s-eye maculopathy", "Bone-spicule pigment"], "correct": 2, "explanation": "Chloroquine/hydroxychloroquine cause a bull''s-eye maculopathy, plus whorl-like corneal (cornea verticillata) deposits and tritan color defects."}'),
  ('9d222d57-1m','{"options": ["Angle-closure glaucoma", "Cherry-red spot", "Cataract", "Optic neuritis with red-green color defect"], "correct": 3, "explanation": "Ethambutol causes a dose-related optic neuritis/neuropathy with a red-green color defect; INH can cause similar optic nerve toxicity."}'),
  ('7d976748-1j','{"options": ["Band keratopathy", "Whorl-like epithelial deposits (cornea verticillata)", "A Kayser-Fleischer ring", "Krukenberg spindle"], "correct": 1, "explanation": "Amiodarone produces whorl-like corneal epithelial deposits (cornea verticillata) and can cause colored halos and optic neuropathy."}'),
  ('9d9a3541-1x','{"options": ["Posterior subcapsular cataract", "Oil-droplet cataract", "Anterior subcapsular stellate cataract", "Rosette cataract"], "correct": 2, "explanation": "Phenothiazines cause anterior subcapsular (stellate) cataract, corneal endothelial dusting, and pigmentary retinopathy at high doses."}'),
  ('523046f8-1p','{"options": ["Red-green defect", "Blue-yellow defect", "Xanthopsia (yellow vision), ''snowy vision''", "Total color loss"], "correct": 2, "explanation": "Digitalis produces xanthopsia (objects appear yellow) and ''snowy vision.''"}'),
  ('6bc732fb-22','{"options": ["Corneal arcus", "Posterior subcapsular cataract", "Anterior subcapsular cataract", "Bull''s-eye maculopathy"], "correct": 2, "explanation": "Echothiophate and DFP (indirect miotics) and phenothiazines all cause anterior subcapsular cataract; corticosteroids cause posterior subcapsular cataract."}'),
  ('cdc4b190-36','{"options": ["Intracameral", "Retrobulbar", "Subconjunctival", "Topical"], "correct": 1, "explanation": "Retrobulbar injection places anesthetic behind the globe within the muscle cone, used for akinesia and anesthesia in intraocular surgery."}'),
  ('3dc2b527-1s','{"options": ["The corneal surface", "The eyelid skin only, not the cul-de-sac", "The conjunctival fornix", "The lacrimal punctum"], "correct": 1, "explanation": "Creams are water-miscible and meant for eyelid SKIN only; they are not placed in the cul-de-sac. Ointments are the semisolid used inside the fornix."}'),
  ('bf738362-2f','{"options": ["Methylcellulose (a viscosity agent)", "Benzalkonium chloride", "Thimerosal", "EDTA"], "correct": 0, "explanation": "Viscosity agents such as methylcellulose and polyvinyl alcohol prolong contact time in the cul-de-sac, improving drug absorption."}'),
  ('7c241aac-1f','{"options": ["5% NaCl", "0.9% NaCl", "0.45% NaCl", "10% NaCl"], "correct": 1, "explanation": "Isotonic solutions are ~0.9% NaCl; the eye tolerates 0.6-1.8% NaCl. 5% NaCl reduces corneal edema; over 10% NaCl causes permanent damage."}'),
  ('e353d65b-31','{"options": ["1% Tropicamide", "0.5% Cyclopentolate", "1% Atropine", "2.5% Phenylephrine"], "correct": 3, "explanation": "2.5% phenylephrine is the approved DPA mydriatic without cycloplegia. Tropicamide and cyclopentolate are the approved mydriatics with cycloplegia."}'),
  ('e6be6cf7-23','{"options": ["4 hours", "24 hours", "6 hours", "14 days"], "correct": 1, "explanation": "Scopolamine (second strongest) has a cycloplegic duration of about 24 hours, versus atropine''s 14 days. It can cause somnolence and hallucination."}'),
  ('ec79b0bb-x','{"options": ["Endothelium only", "Basement membrane only", "Devitalised cells and mucus", "Healthy epithelium"], "correct": 2, "explanation": "Rose Bengal stains devitalised (dead/degenerated) cells and mucus and has antiviral property; it helps diagnose KCS, herpes, and Sjogren''s."}'),
  ('0717b628-1h','{"options": ["Lower IOP", "Stain the anterior lens capsule for capsulorhexis", "Reverse mydriasis", "Anesthetise the cornea"], "correct": 1, "explanation": "Trypan blue stains the anterior capsule to improve visualisation during capsulorhexis in mature/white cataracts, and marks corneal endothelial integrity."}'),
  ('20ca026a-1f','{"options": ["Copper deposits (Wilson''s disease/chalcosis)", "Calcium", "Arsenic", "Iron rust stains"], "correct": 0, "explanation": "Penicillamine binds copper (and lead, zinc, mercury) and is used for copper deposits in Wilson''s disease/chalcosis and gold deposits (chrysiasis)."}'),
  ('4793cf82-28','{"options": ["Mannitol only via glucose", "Glycerol", "Isosorbide", "Glycerin"], "correct": 2, "explanation": "Isosorbide is the oral osmotic that is safe in diabetes (not metabolised to glucose). Oral glycerin/glycerol raises blood glucose and is contraindicated in diabetes."}'),
  ('f26114cd-r','{"options": ["Increasing uveoscleral outflow", "Creating an osmotic gradient that draws fluid from the eye and reduces aqueous", "Blocking aqueous secretion enzymes", "Opening the trabeculum"], "correct": 1, "explanation": "Osmotic agents raise plasma osmolality, drawing water from the vitreous/aqueous and lowering IOP; they are used for acute angle-closure and pre-op IOP reduction."}'),
  ('edb0f544-3m','{"options": ["Timolol", "Apraclonidine", "Phenylephrine", "Brimonidine"], "correct": 3, "explanation": "Brimonidine is a highly selective alpha-2 agonist with a dual mechanism: decreased aqueous secretion plus increased uveoscleral outflow."}'),
  ('32f81cd0-1i','{"options": ["Excessive lipid solubility", "No miotic effect", "A short shelf life", "Poor corneal penetration"], "correct": 3, "explanation": "Carbachol penetrates the cornea poorly, so it is combined with benzalkonium chloride (a wetting agent) to improve penetration; it is used for pilocarpine-resistant cases and post-cataract miosis."}'),
  ('81671e0b-27','{"options": ["Pilocarpine", "Neostigmine", "Physostigmine", "Edrophonium"], "correct": 2, "explanation": "Physostigmine, a reversible carbamate anticholinesterase that crosses into the CNS, is the antidote for atropine (anticholinergic) overdose."}'),
  ('d159f94e-1d','{"options": ["Glaucoma", "Adie''s pupil", "Horner''s syndrome", "Myasthenia gravis"], "correct": 3, "explanation": "Edrophonium (Tensilon), a short-acting reversible anticholinesterase, briefly improves ptosis/diplopia in the diagnosis of myasthenia gravis."}'),
  ('ae6f609e-17','{"options": ["Marcus Gunn pupil", "Horner''s syndrome", "Argyll-Robertson pupil", "Adie''s tonic pupil"], "correct": 3, "explanation": "Methacholine (and dilute 0.1% pilocarpine) constricts the denervation-supersensitive Adie''s tonic pupil, aiding its diagnosis."}'),
  ('b4d61204-29','{"options": ["30S ribosomal subunit", "DNA gyrase", "Cell wall", "50S ribosomal subunit"], "correct": 3, "explanation": "Macrolides bind the 23S rRNA of the 50S ribosomal subunit; they cover gram-positives and Chlamydia. Azithromycin has an extended tissue half-life."}'),
  ('2c890847-3f','{"options": ["Aplastic anemia", "Brown tooth staining", "Optic neuritis", "Xanthopsia"], "correct": 1, "explanation": "Tetracyclines chelate calcium and stain developing teeth brown in children; they can also induce transient myopia. They bind the 30S ribosome."}'),
  ('45ab4a82-t','{"options": ["Cell wall synthesis (lipid carrier dephosphorylation)", "DNA gyrase", "Folic acid synthesis", "30S ribosome"], "correct": 0, "explanation": "Bacitracin blocks the lipid carrier that transports peptidoglycan precursors, inhibiting cell wall synthesis; it covers gram-positives and is too toxic for systemic use."}'),
  ('326ae4d3-2g','{"options": ["Is toxic to normal corneal epithelium and less effective", "Causes cataract", "Is far more expensive", "Cannot be made topically"], "correct": 0, "explanation": "Idoxuridine is toxic to normal corneal epithelium and less effective than trifluridine, which replaced it as the DOC for HSV keratitis."}'),
  ('ea2367f7-1y','{"options": ["Candida keratitis and endophthalmitis", "Herpes keratitis", "Fusarium keratitis", "Aspergillus keratitis"], "correct": 0, "explanation": "Amphotericin B (a polyene binding ergosterol) is the DOC for Candida keratitis and endophthalmitis. Natamycin is preferred for filamentous fungi (Fusarium/Aspergillus)."}'),
  ('5150a7e5-2s','{"options": ["No anti-inflammatory action", "Antifungal activity", "Maximal corneal thinning", "Minimal IOP elevation with good efficacy"], "correct": 3, "explanation": "Loteprednol is metabolised to an inactive form soon after acting, giving good anti-inflammatory effect with minimal IOP elevation, making it well suited to allergic conjunctivitis."}'),
  ('e3ac24a6-35','{"options": ["Corticosteroid-induced IOP elevation", "Cataract formation", "Corneal edema", "Miosis"], "correct": 0, "explanation": "Steroid responders develop elevated IOP with 0.1% dexamethasone/betamethasone TID over 4-6 weeks, used as a provocative test for POAG susceptibility."}'),
  ('621359d4-1c','{"options": ["Lower IOP", "Manage pain and prevent cystoid macular edema", "Treat fungal infection", "Reverse mydriasis"], "correct": 1, "explanation": "Ketorolac, the most-used ophthalmic NSAID, controls post-op pain and helps prevent cystoid macular edema; its cap colour is gray."}'),
  ('b40475c7-2a','{"options": ["Bull''s-eye maculopathy", "Anterior cataract", "Cornea verticillata", "Retinal vascular occlusion (CRAO/CRVO)"], "correct": 3, "explanation": "Oral contraceptives increase thrombotic risk and are associated with retinal vascular occlusive disease (CRAO, CRVO), optic neuritis, and papilledema."}'),
  ('50309703-21','{"options": ["Papilledema (pseudotumor cerebri)", "Cherry-red spot", "Bone-spicule pigment", "Kayser-Fleischer ring"], "correct": 0, "explanation": "Vitamin A excess can raise intracranial pressure (pseudotumor cerebri) with papilledema, plus dry eyes and blepharoconjunctivitis."}'),
  ('ad3419b7-1w','{"options": ["Argyrosis", "Chalcosis", "Chrysiasis", "Siderosis"], "correct": 2, "explanation": "Gold deposition is chrysiasis; silver deposition is argyrosis; iron is siderosis; copper is chalcosis."}'),
  ('8191628e-2b','{"options": ["Carbonic anhydrase inhibitors", "Prostaglandin analogues", "Anticholinergics/tricyclic antidepressants", "Beta-blockers"], "correct": 2, "explanation": "Anticholinergics, tricyclic antidepressants, scopolamine, antihistamines, and related agents dilate the pupil and can precipitate angle-closure in predisposed eyes. Beta-blockers, CAIs, and prostaglandins lower IOP."}'),
  ('ed0c0c3f-2r','{"options": ["2nd generation", "1st generation", "4th generation", "3rd generation"], "correct": 0, "explanation": "Second-generation fluoroquinolones (ciprofloxacin, ofloxacin, norfloxacin) were the first with ophthalmic preparations. Moxifloxacin and gatifloxacin are later-generation ophthalmic agents with expanded gram-positive cover."}'),
  ('d535adb8-2i','{"options": ["Lens capsule", "Ciliary muscle", "Corneal endothelium", "Retinal pigment epithelium (RPE)"], "correct": 3, "explanation": "The blood-retinal barrier lies between the choriocapillaris/retinal capillary and the RPE (outer barrier) with tight junctions, controlling drug access to the retina."}'),
  ('2bd20224-2g','{"options": ["IOP-lowering effect", "Miotic effect", "Nasal vasoconstriction and local anesthesia", "Antifungal effect"], "correct": 2, "explanation": "Cocaine blocks NE reuptake (indirect sympathomimetic) causing vasoconstriction, and is a local anesthetic, useful for nasal mucosa preparation in DCR."}'),
  ('a5336523-2n','{"options": ["Brimonidine", "Phenylephrine", "Apraclonidine", "Dipivefrin"], "correct": 3, "explanation": "Dipivefrin (dipivalyl epinephrine) is a lipophilic prodrug converted to epinephrine intraocularly, giving better penetration and fewer systemic effects than epinephrine."}'),
  ('5dd4bbc8-2i','{"options": ["Optic neuritis", "Cataract", "Rebound congestion (rhinitis medicamentosa)", "Corneal ulcer"], "correct": 2, "explanation": "Overuse of alpha-1 decongestants (naphazoline, oxymetazoline, tetrahydrozoline) beyond a few days causes rebound congestion (rhinitis medicamentosa)."}'),
  ('fa27c2f4-1k','{"options": ["Cocaine + fluorescein", "Benoxinate 0.4% + fluorescein 0.25%", "Proparacaine + fluorescein", "Tetracaine + rose bengal"], "correct": 1, "explanation": "Fluress combines benoxinate 0.4% with fluorescein 0.25% (plus chlorobutanol, EDTA, boric acid), used for applanation tonometry."}'),
  ('d31c0a4a-28','{"options": ["Stains epithelial defects", "Fluoresces in the infrared and penetrates the RPE better", "Is applied topically", "Has a shorter wavelength"], "correct": 1, "explanation": "ICG fluoresces in the infrared (peak ~835 nm), penetrating the RPE and blood better than fluorescein, so it images the choroidal circulation and neovascular membranes."}'),
  ('a9ea8d5f-18','{"options": ["23S", "30S", "50S", "70S whole ribosome only"], "correct": 1, "explanation": "Aminoglycosides bind the 30S ribosomal subunit (as do tetracyclines and glycylcyclines), inhibiting bacterial protein synthesis."}'),
  ('74aaf043-2d','{"options": ["Dexamethasone solution", "Prednisolone acetate 1%", "Betamethasone cream", "Fluorometholone solution"], "correct": 1, "explanation": "Prednisolone acetate 1% is a suspension and must be shaken to resuspend the drug for consistent dosing and its excellent penetration."}'),
  ('f96f232c-16','{"options": ["Provide anesthesia", "Prevent the IOP spike after laser procedures", "Reverse mydriasis", "Treat fungal keratitis"], "correct": 1, "explanation": "Apraclonidine is used to blunt the IOP spike after argon laser trabeculoplasty, iridotomy, or YAG capsulotomy, without affecting BP or pulse."}'),
  ('e5d299c0-2n','{"options": ["Natamycin", "Tobramycin", "Trifluridine", "Vancomycin"], "correct": 3, "explanation": "Vancomycin is reserved for gram-positive endophthalmitis, including MRSA and resistant cocci, given intravitreally."}'),
  ('79262bf3-1p','{"options": ["Orange", "Turquoise", "Green", "Pink"], "correct": 1, "explanation": "Prostaglandin analogues carry a turquoise cap. Miotics are green, CAIs orange, corticosteroids pink."}'),
  ('22fd153c-2h','{"options": ["An alpha agonist", "A prostaglandin", "Beta-1 (cardio) selective, sparing bronchial beta-2 receptors", "Non-selective"], "correct": 2, "explanation": "Betaxolol is beta-1 (cardio) selective, so it largely spares bronchial beta-2 receptors, making it safer than the non-selective timolol in asthma/COPD."}'),
  ('8e7b95d4-1o','{"options": ["Acetylcholinesterase, so ACh accumulates and stimulates the ciliary muscle", "Phospholipase A2", "Adenylate cyclase", "Carbonic anhydrase"], "correct": 0, "explanation": "Both are anticholinesterases (physostigmine reversible, echothiophate irreversible); accumulated ACh stimulates the ciliary muscle to open the trabeculum (indirect miotics)."}'),
  ('a6a10437-2p','{"options": ["Rose Bengal", "Trypan blue", "Lissamine green", "Argyrol"], "correct": 2, "explanation": "Lissamine green stains devitalised cells and mucus, screens for xerophthalmia, and has antiviral property at 0.06% with little stinging."}'),
  ('55a99873-2t','{"options": ["Yes, depth is directly proportional to concentration", "No, beyond the effective concentration depth does not keep increasing", "Yes, but only for amide anesthetics", "No, concentration has no effect at all"], "correct": 1, "explanation": "Once an effective concentration is reached, raising it further does not deepen surface anesthesia; it mainly increases toxicity and stinging. Onset, potency, and duration are set by the drug and tissue pH, not by piling on concentration."}'),
  ('a2592a8c-3e','{"options": ["Amides", "Esters", "A mix of amides and esters", "Neither"], "correct": 1, "explanation": "The topical ophthalmic anesthetics in routine use are all ESTERS (metabolized by plasma pseudo-cholinesterase). Contrast with injectable amides such as lidocaine and bupivacaine (liver-metabolized). The ''all anesthetics are esters'' claim is only true when scoped to topical ophthalmics."}'),
  ('eaf72cf9-29','{"options": ["Anesthetic first, then culture", "Culture first, then anesthetic", "Order does not matter", "Never culture an anesthetized eye"], "correct": 1, "explanation": "Take the CULTURE BEFORE instilling the anesthetic. Anesthetic drops (and their preservatives) are bacteriostatic and can suppress organism growth, giving a false-negative culture."}'),
  ('2673842a-2i','{"options": ["Proparacaine", "Benoxinate", "Tetracaine", "They are equally toxic"], "correct": 2, "explanation": "Tetracaine is the most potent and most epithelial-toxic (and most stinging) of the topical ophthalmic anesthetics, which is why proparacaine is preferred for routine tonometry."}'),
  ('0059c92d-25','{"options": ["Tetracaine", "Benoxinate", "Proparacaine", "Cocaine"], "correct": 2, "explanation": "Proparacaine stings the least and acts fast (onset 5-15 sec, duration ~20 min), making it the everyday drop for tonometry and gonioscopy. Tetracaine stings the most."}'),
  ('6c6c2100-43','{"options": ["Proparacaine", "Benoxinate", "Tetracaine", "None can cause CNS effects"], "correct": 2, "explanation": "Systemic local-anesthetic toxicity is CNS excitation then seizures. Tetracaine is the most potent of these agents, so it carries the greatest convulsion risk if it enters the circulation. Any local anesthetic can do this at high systemic levels; tetracaine is simply the most potent of the three."}'),
  ('c2e8bd44-1p','{"options": ["Benoxinate", "Proparacaine", "Tetracaine", "All are equally bactericidal"], "correct": 1, "explanation": "Proparacaine has the least intrinsic antibacterial effect. Benoxinate carries an antibacterial property (combined with fluorescein in Fluress). Low bactericidal activity is actually preferred just before culturing, though the culture is still taken before any drop."}'),
  ('92038fc8-40','{"options": ["Green dye; fluoresces orange-red", "Orange-red dye; fluoresces green-yellow", "Blue dye; fluoresces red", "Yellow dye; fluoresces blue"], "correct": 1, "explanation": "The dye itself is orange-red. Where the epithelium is broken it floods the defect and fluoresces bright green-yellow under cobalt blue light. Intact epithelium is a lipid barrier the water-soluble dye cannot cross, so it does not stain."}'),
  ('f4d810de-1c','{"options": ["Depressed pockets or pits in the epithelium", "An elevated/raised area of epithelium where dye is displaced", "A full-thickness epithelial defect", "Normal endothelium"], "correct": 1, "explanation": "Negative staining marks an ELEVATED area: dye pools around a raised bump and is displaced from its surface, so the elevation reads dark against the surrounding green (seen in epithelial basement membrane dystrophy). It does not indicate pockets/pits; that is a common trap."}'),
  ('d2a86449-2r','{"options": ["Rose bengal", "Lissamine green", "Sodium fluorescein", "Indocyanine green"], "correct": 2, "explanation": "Sodium fluorescein is the workhorse for epithelial integrity: it pools in any break in the epithelium and glows under cobalt blue. Rose bengal and lissamine green instead stain devitalized cells and mucus."}'),
  ('d190a473-2i','{"options": ["Sodium fluorescein only", "Rose bengal and lissamine green", "Indocyanine green only", "Trypan blue only"], "correct": 1, "explanation": "Rose bengal and lissamine green stain DEVITALIZED (dead/dying) cells and mucus, making them the dry-eye and surface-damage dyes. Fluorescein stains where cells are missing (defects), not the dead cells themselves. Sort every dye by: living defect (fluorescein) vs dead tissue (rose bengal/lissamine)."}'),
  ('392197de-2l','{"options": ["Less than 3 seconds", "Less than 10 seconds", "Less than 15 seconds", "Less than 20 seconds"], "correct": 1, "explanation": "A TBUT under about 10 seconds indicates an unstable tear film (evaporative/dry-eye pattern); a healthy film is typically 10 seconds or more. Some drills quote a single ''normal'' figure like 12 seconds, but the tested threshold is the <10-second cutoff for abnormal."}'),
  ('5eef396b-2k','{"options": ["A true herpetic dendrite", "A pseudodendrite", "A healed scar", "Normal epithelium"], "correct": 1, "explanation": "A true HSV dendrite stains at its margins/ulcer bed; when rose bengal fills the CENTER of the lesion the picture favors a PSEUDODENDRITE (herpes zoster, healing epithelium, toxicity), which is raised heaped epithelium rather than a true ulcer."}'),
  ('118fbc88-2z','{"options": ["Sodium fluorescein", "Lissamine green", "Rose bengal", "Indocyanine green"], "correct": 2, "explanation": "Rose bengal is the classic conjunctival stain for devitalized cells and mucus and has a notable antiviral (anti-HSV) property. Lissamine green stains the same devitalized cells but is far gentler/less stinging; fluorescein is for corneal epithelial defects."}'),
  ('3720393d-3b','{"options": ["Cataract and glaucoma", "Myopia and hyperopia", "Conjunctivitis and blepharitis", "Amblyopia and strabismus"], "correct": 3, "explanation": "Amblyopia and strabismus are the core pediatric concerns; early detection matters because the visual cortex has a critical period of plasticity."}'),
  ('90918734-1s','{"options": ["Birth to age 3", "Age 3 to 7", "Age 12 to 18", "Age 7 to 12"], "correct": 0, "explanation": "Peak plasticity is birth to age 3; the functional window extends to about age 7-8, with diminishing response afterward."}'),
  ('f06f59bb-20','{"options": ["Rewires the visual pathway through repetitive stimulation", "Uses only surgery", "Is identical to orthoptics", "Only strengthens the eye muscles"], "correct": 0, "explanation": "Vision therapy is drug-free treatment that rewires the visual pathway (tracking, focusing, teaming). Orthoptics focuses on strengthening eye muscles."}'),
  ('807dd005-1j','{"options": ["1 year", "6 months", "5 years", "3 years"], "correct": 3, "explanation": "Acuity reaches adult 20/20 (6/6) at about age 3, when letter-matching tests such as Sheridan Gardiner become usable."}'),
  ('fe968f9e-1o','{"options": ["Develop astigmatism", "Become amblyopic", "Become progressively more hyperopic", "Reduce refractive error toward emmetropia as the eye grows"], "correct": 3, "explanation": "Neonates are typically hyperopic (+2.00 to +3.00 D); the eye grows to match its optics, reducing error toward emmetropia, with most hyperopia gone by age 4."}'),
  ('9a6b640e-24','{"options": ["Congenital cataract", "Maternal rubella only", "Vitamin A deficiency", "Prematurity combined with supplemental oxygen"], "correct": 3, "explanation": "ROP/RLF arises from prematurity plus supplemental oxygen, producing abnormal retinal vessels that can leak, scar, and detach the retina."}'),
  ('a61e9145-1g','{"options": ["6 months postnatal", "2 months postnatal", "20 weeks gestation", "30 weeks gestation"], "correct": 3, "explanation": "The pupillary light reaction develops at about 30 weeks gestation. Foveal maturation occurs around 4 months and optic nerve myelination from 7 months to 2 years."}'),
  ('2f6a988e-1q','{"options": ["1 month", "6 months", "3 years", "1 year"], "correct": 1, "explanation": "By 6 months the infant reaches accurately for toys and has convergence and depth perception; acuity is about 20/200 at that age."}'),
  ('1a5383fc-24','{"options": ["A refractive error", "Incomplete CNS maturation (linked to learning/attention/visual problems)", "Normal maturation", "Amblyopia"], "correct": 1, "explanation": "Persistence of a primitive reflex indicates incomplete CNS maturation and can contribute to ADHD, learning disability, and visual problems. Absence when it should be present signals a neurological problem."}'),
  ('93a94f7e-1g','{"options": ["5-6 months", "2 years", "3 months", "1 year"], "correct": 0, "explanation": "The Moro reflex integrates by 5-6 months. It is triggered by a sudden sound or movement and tests hearing; persistence is linked to ADHD and sensory processing difficulties."}'),
  ('e56ca7f6-1c','{"options": ["Absent in premature babies", "Never present at birth", "Stronger in premature babies; its absence signals a neurological problem", "Pathological in infants"], "correct": 2, "explanation": "The palmar grasp reflex is stronger in premature babies and integrates by about 5-6 months; its absence indicates a neurological problem."}'),
  ('7fbd9c0f-1h','{"options": ["Stepping reflex", "Startle reflex", "Rooting reflex", "Fencing reflex"], "correct": 3, "explanation": "The ATNR is the ''fencing reflex'': turning the head extends the face-side limbs. Persistence disrupts reading/tracking and can mimic convergence insufficiency."}'),
  ('0a9d8bef-w','{"options": ["Amblyopia", "A refractive error", "A motor development issue such as cerebral palsy", "Normal development"], "correct": 2, "explanation": "Absence of the Landau reflex indicates a motor development problem such as cerebral palsy or generalised intellectual impairment. It normally integrates by 1-3 years."}'),
  ('19dedef6-2k','{"options": ["Babinski", "Moro", "Galant", "STNR (symmetric tonic neck reflex)"], "correct": 3, "explanation": "Persistence of the STNR causes near-vision problems, poor eye-hand coordination, and difficulty copying tasks. It normally integrates by 9-11 months."}'),
  ('05e5c2a1-2t','{"options": ["Crying", "Asleep", "Drowsy after feeding", "Awake and attentive"], "correct": 3, "explanation": "Acuity and motility are assessed when the infant is alert and attentive. Direct ophthalmoscopy is easier when the infant is drowsy, ideally while being fed."}'),
  ('4b959a80-1y','{"options": ["It dilates the pupils", "Infants become drowsy after feeding, reducing cooperation for acuity/motility", "It raises IOP", "It causes vomiting"], "correct": 1, "explanation": "Infants become drowsy after feeding, which impairs cooperation for the alert-state tests of acuity and motility (though drowsiness helps ophthalmoscopy)."}'),
  ('f72fcd66-1u','{"options": ["Blocked tear duct", "Retinoblastoma", "Conjunctivitis", "Refractive error"], "correct": 1, "explanation": "Leukocoria (a white pupil) can indicate retinoblastoma and requires urgent referral; other causes include congenital cataract."}'),
  ('34e07e63-1p','{"options": ["6 months of age", "1st grade", "Birth", "3 years of age"], "correct": 0, "explanation": "The AOA recommends a first examination at 6 months for both at-risk and low-risk infants; then at 3 years, and before first grade for low-risk school-age children."}'),
  ('6e20859d-1e','{"options": ["Use cartoons for decoration", "Use a bright room", "Wear a white coat", "Keep the room child-friendly"], "correct": 2, "explanation": "The examiner should avoid a white coat, which can frighten the child; the room should be bright, pleasant, and child-friendly but not over-decorated."}'),
  ('10f3474a-1v','{"options": ["Letter charts", "Vernier displacement tasks", "Catford drum", "Preferential looking gratings / Lea gratings"], "correct": 3, "explanation": "Resolution acuity is the minimum separable, tested with gratings (preferential looking cards, Lea gratings). Detection uses the Catford drum/Stycar balls; recognition uses letter/picture charts."}'),
  ('15220c5f-2i','{"options": ["2-3 years", "0-3 months", "5 years and up", "3-6 years"], "correct": 1, "explanation": "The OKN drum elicits involuntary nystagmus to moving stripes in infants 0-3 months; a present response confirms the infant can see."}'),
  ('239ac145-1d','{"options": ["Follow a moving light", "Match H, O, T, or V to a keycard", "Name colors", "Report the gap in a circle"], "correct": 1, "explanation": "The Sheridan Gardiner HOTV test is a matching task (H, O, T, V) using a keycard, suitable for ages 2-5, tested at 6 meters."}'),
  ('9e8d0e5e-2u','{"options": ["Polarization", "The crowding phenomenon", "Stereopsis", "Chromatic aberration"], "correct": 1, "explanation": "The Lea symbol chart uses the crowding phenomenon, in which closely spaced optotypes are harder to resolve, revealing amblyopia that single optotypes might miss."}'),
  ('acdbafb8-1o','{"options": ["40 cm", "6 meters", "3 meters", "1 meter"], "correct": 2, "explanation": "Allen figures (familiar object pictures) are named or pointed at, tested at 3 meters, for children about 2-3 years old."}'),
  ('c18984f3-2k','{"options": ["Tumbling E", "Lea symbols", "Snellen chart", "Teller Acuity Cards"], "correct": 2, "explanation": "The Snellen chart requires letter knowledge, so it is used from about age 5. Younger children use matching or orientation tests (Lea, HOTV, Tumbling E)."}'),
  ('6005d304-1x','{"options": ["-2.00 D", "+3.00 D", "+1.00 D", "Plano"], "correct": 1, "explanation": "Infant refraction is predominantly hyperopic; the average at 3 months is about +3.00 D, decreasing toward +0.50 D by ages 4-6 (emmetropization)."}'),
  ('8550ab0a-1q','{"options": ["Requires a dark room", "Measures only astigmatism", "Evaluates the accommodative system while the child actively accommodates on a near target", "Uses cycloplegia"], "correct": 2, "explanation": "Dynamic retinoscopy has the child accommodate on a near target attached to the retinoscope, assessing the accommodative response rather than measuring refractive error."}'),
  ('7c60476e-2q','{"options": ["3.50 D", "1.50 D", "0.50 D", "5.00 D"], "correct": 1, "explanation": "Persistent astigmatism greater than 1.50 D is a prescribing threshold. Hyperopia over +3.50 D and anisometropia over 1.00 D are the other key thresholds; any amount of myopia is corrected."}'),
  ('d2ea81e5-23','{"options": ["Under-correct with minus lenses", "Give the full plus at once", "Prescribe bifocals", "Give partial correction of the hyperopia"], "correct": 3, "explanation": "First prescriptions for hyperopia use PARTIAL correction (to allow emmetropization and comfort), while anisometropia is corrected FULLY in both eyes."}'),
  ('b675d598-y','{"options": ["Left uncorrected", "Corrected only in the better eye", "Corrected fully in both eyes", "Partially corrected only"], "correct": 2, "explanation": "Anisometropia should be corrected fully in both eyes to give each eye a clear, equal image and prevent anisometropic amblyopia."}'),
  ('71227f20-2h','{"options": ["30 prism diopters", "7 prism diopters", "15 prism diopters", "45 prism diopters"], "correct": 2, "explanation": "A reflex at the pupil edge (~2 mm) is about 15 prism diopters. 1 mm ~7 pd, mid pupil-to-limbus ~30 pd, and the limbus ~45 pd."}'),
  ('fb8b810e-14','{"options": ["Assess stereopsis", "Measure IOP", "Confirm color vision", "Measure the angle of deviation with prisms when cover testing is not possible"], "correct": 3, "explanation": "The Krimsky test neutralises the corneal reflex with prism over the deviating eye to quantify a strabismic deviation when the child cannot cooperate with a cover test."}'),
  ('33150774-1h','{"options": ["+1.50 to +2.00 D", "-0.50 D", "Plano", "+0.50 to +0.75 D"], "correct": 3, "explanation": "The normal accommodative lag on MEM retinoscopy is +0.50 to +0.75 D. A high lag suggests esophoria at near or accommodative insufficiency."}'),
  ('1f416ade-29','{"options": ["Exophoria at near", "Spasm of accommodation", "Esophoria at near / accommodative insufficiency", "Emmetropia"], "correct": 2, "explanation": "A high lag suggests esophoria at near, accommodative insufficiency/infacility, an over-minused patient, or an uncorrected hyperope. A low lag or lead suggests exophoria or accommodative spasm."}'),
  ('e799b771-1s','{"options": ["Needs no special glasses", "Uses cycloplegia", "Measures refractive error", "Requires red-green glasses"], "correct": 0, "explanation": "The Lang stereotest uses a random-dot stereogram on a card that needs no special glasses, so it conveniently confirms stereopsis and fusion in young children."}'),
  ('962d6613-22','{"options": ["A shadow-free but less vivid image", "A stronger stimulus to fusion, more natural viewing, and no anisometropia risk", "No depth perception", "Weaker fusion stimulus and risk of anisometropia"], "correct": 1, "explanation": "Polaroid (vectographic) targets give more natural viewing, a stronger fusion stimulus, more vivid depth, and no anisometropia risk, though head tilt influences the result. Red/green filters are less natural and may induce anisometropia."}'),
  ('5e91c969-25','{"options": ["Is blurred", "Moves away (base-out demand)", "Comes closer (base-in demand)", "Is occluded"], "correct": 2, "explanation": "SILO (''Small In, Large Out''): with a base-in (convergence-relaxing) demand the target appears smaller and closer; with a base-out demand it appears larger and farther."}'),
  ('c673bf80-2i','{"options": ["Visual acuity", "Visual information processing", "Color vision", "Visual field"], "correct": 1, "explanation": "The visual system comprises visual integrity (eye health/refraction), visual efficiency (oculomotor, accommodation, vergence, fusion), and visual information processing (perceptual and visual-motor skills)."}'),
  ('c80bfc50-31','{"options": ["Figure-ground", "Visual closure", "Visual sequential memory", "Form constancy"], "correct": 0, "explanation": "Figure-ground is selecting an object from a busy background; a deficit causes losing place, skipping words, and distraction by surroundings."}'),
  ('0c6fd027-2p','{"options": ["Visual discrimination", "Visual closure", "Figure-ground", "Visual sequential memory"], "correct": 3, "explanation": "Visual sequential memory is remembering a series of forms in order; a deficit impairs spelling and sequencing letters within words."}'),
  ('0d6eda4d-1p','{"options": ["Identification", "Centering", "Speech-Language", "Antigravity"], "correct": 1, "explanation": "In Skeffington''s four circles, Centering answers ''Where is it?'' Antigravity is ''Where am I?'', Identification is ''What is it?'', and Speech-Language is ''What about it?''"}'),
  ('17ea7d4b-1y','{"options": ["Fuse the two images", "Project left/right/up/down into external space so letters are oriented correctly", "See fine detail", "Accommodate at near"], "correct": 1, "explanation": "Directionality projects directional concepts into external space, which is essential for correct letter orientation; poor directionality produces letter reversals (b/d, p/q)."}'),
  ('2ab1d777-3d','{"options": ["Only in adults", "With an obvious structural lesion", "Without structural pathology that accounts for the loss", "Only from cataract"], "correct": 2, "explanation": "Amblyopia is reduced best-corrected acuity from abnormal early visual experience, with no structural pathology to explain the loss; the cortex never received adequate stimulation."}'),
  ('72348681-1q','{"options": ["Strabismic", "Anisometropic", "Meridional", "Deprivation"], "correct": 0, "explanation": "Strabismic amblyopia (from constant unilateral strabismus with cortical suppression of the deviating eye) is the most common in clinical practice."}'),
  ('a092fbeb-x','{"options": ["Uncorrected astigmatism blurring one meridian", "A large anisometropia in sphere", "A media opacity", "Constant strabismus"], "correct": 0, "explanation": "Meridional amblyopia comes from uncorrected astigmatism, in which one meridian is consistently blurred during development."}'),
  ('71297f00-22','{"options": ["No treatment", "Direct occlusion", "Inverse occlusion", "Atropine to the amblyopic eye"], "correct": 2, "explanation": "Eccentric fixation (using a parafoveal locus instead of the fovea) is managed with inverse occlusion to encourage foveal fixation. Direct occlusion suits foveal and unsteady eccentric fixators."}'),
  ('f41cc5b7-2m','{"options": ["1 year", "4-6 weeks", "1-2 weeks", "12-16 weeks"], "correct": 3, "explanation": "Full spectacle correction is worn for 12-16 weeks before adding patching, because some (especially anisometropic) amblyopes improve with glasses alone. Reassess acuity every 4 weeks."}'),
  ('6b1ad18d-1h','{"options": ["20/80 to 20/200", "Better than 20/25", "Worse than 20/200", "20/30 to 20/60"], "correct": 2, "explanation": "Amblyopia depth: shallow 20/30 to 20/60, moderate 20/80 to 20/200, deep worse than 20/200."}'),
  ('97c4a4bc-3l','{"options": ["Never occur", "Not be permanent", "Cause strabismus", "Be permanent"], "correct": 1, "explanation": "Unless the underlying strabismus or anisometropia is resolved, acuity gains during monocular therapy tend not to be permanent; the binocular cause must be treated."}'),
  ('8c304b6c-1e','{"options": ["In adulthood", "Before 6 months of age", "At puberty", "After age 3"], "correct": 1, "explanation": "Infantile esotropia begins before 6 months, with a large angle (over 30 pd), often alternating fixation, and associated DVD and inferior oblique overaction."}'),
  ('0cf62c0d-1k','{"options": ["6 years", "Birth", "10 years", "2-3 years"], "correct": 3, "explanation": "Accommodative esotropia usually appears at 2-3 years as accommodative demand increases; it is associated with moderate-to-high hyperopia."}'),
  ('9d743caa-1t','{"options": ["Emmetropia", "High myopia", "Moderate-to-high hyperopia", "Simple astigmatism"], "correct": 2, "explanation": "In accommodative esotropia the hyperope accommodates excessively, driving accommodative convergence and inward deviation. Full plus correction relieves it."}'),
  ('66b697b6-1o','{"options": ["Patching only", "Prism only", "Full cycloplegic (full plus) spectacle correction", "Surgery"], "correct": 2, "explanation": "Full cycloplegic (full plus) correction is the first and often definitive treatment; surgery is reserved for a residual non-accommodative deviation."}'),
  ('007016f3-1j','{"options": ["Brighter in one eye", "Displaced nasally", "Absent", "Symmetric and centered (no true deviation)"], "correct": 3, "explanation": "Pseudostrabismus shows symmetric, centered corneal reflexes because there is no true deviation; the crossed appearance is from epicanthal folds or a flat nasal bridge and resolves with growth."}'),
  ('223d8764-2s','{"options": ["Phoria", "Vergence", "Tropia", "Fixation disparity"], "correct": 2, "explanation": "A tropia is a manifest deviation demonstrated by the unilateral cover test. A phoria is a latent deviation revealed only by the cover-uncover test."}'),
  ('80a61fa5-25','{"options": ["5", "7", "1 (to establish a binocularity window)", "2"], "correct": 3, "explanation": "Surgical alignment of infantile esotropia is aimed for before about age 2 to establish a window for developing binocularity."}'),
  ('69c81845-1f','{"options": ["Distal to proximal", "Top-down (cephalocaudal): head control first, then trunk, then legs", "Bottom-up (caudocephalic)", "Randomly"], "correct": 1, "explanation": "Gross motor development is cephalocaudal (top-down): head control develops first, then shoulders/arms, trunk, hips, and legs."}'),
  ('30688ea5-1t','{"options": ["Grade-schoolers", "Toddlers", "Pre-schoolers", "Infants"], "correct": 2, "explanation": "0-2 years are infants/toddlers, 3-5 years are pre-schoolers, and 6-10 years are grade-schoolers."}'),
  ('7763f9b9-28','{"options": ["Move in response to sensory input", "Express emotions", "Take turns in conversation", "Grasp that a sound or picture can represent something"], "correct": 3, "explanation": "The representational (symbolic) area is understanding that a symbol (a picture or sound) can stand for something, converting short-term to long-term memory."}'),
  ('3a244eac-y','{"options": ["Turning the head to one side", "Stroking the corner of the baby''s mouth", "Stroking the sole of the foot", "A loud sound"], "correct": 1, "explanation": "Stroking the corner of the mouth makes the head turn toward the stimulus with the mouth opening, helping the baby find the breast/bottle. It integrates by 3-4 months."}'),
  ('f2c7f08d-2i','{"options": ["Bedwetting and difficulty sitting still", "Photophobia", "Feeding problems", "Toe fanning"], "correct": 0, "explanation": "Persistence of the Galant reflex is linked to bedwetting, fatigue, attention difficulties, and difficulty sitting still. It integrates by about 9 months."}'),
  ('e2f11ccb-1r','{"options": ["Lea gratings", "Catford drum / Stycar balls", "Snellen chart", "Landolt C"], "correct": 1, "explanation": "Detection acuity is the minimum size that can be seen; it is tested with the Catford drum or Stycar balls. Resolution uses gratings; recognition uses letter/picture charts."}'),
  ('8ae4df51-1n','{"options": ["Grating orientation", "The smallest visible dot", "Lateral displacement of lines placed end to end", "Letter identity"], "correct": 2, "explanation": "Vernier (localization) acuity is the ability to detect a small lateral misalignment of line segments placed end to end, a hyperacuity."}'),
  ('842a1740-1l','{"options": ["5 years and up", "Newborns only", "1-3 years", "Adults"], "correct": 2, "explanation": "Cardiff Acuity Cards use vanishing-optotype pictures and preferential looking for children about 1-3 years old."}'),
  ('6757b81f-1x','{"options": ["Measuring IOP", "Using red-green glasses", "Recording an ERG", "Observing whether the child objects when the better eye is covered"], "correct": 3, "explanation": "The fixation preference test covers each eye in turn; a child with reduced vision in one eye objects when the better eye is occluded, indicating a preference and possible amblyopia."}'),
  ('63a2e926-o','{"options": ["Suppression", "Movement of the eyes to align images", "Accommodation at near", "Simultaneous stimulation of corresponding retinal areas producing a single percept"], "correct": 3, "explanation": "Sensory fusion is the simultaneous stimulation of corresponding retinal areas that yields a single combined image; motor fusion is the vergence movement that maintains it."}'),
  ('9f7beece-17','{"options": ["The amplitude of accommodation", "The flexibility of changing focus between distances", "Stereopsis", "Convergence only"], "correct": 1, "explanation": "Accommodative infacility is difficulty changing focus flexibly (near-to-far and far-to-near). Accommodative insufficiency is a reduced amplitude; accommodative spasm/excess is difficulty relaxing accommodation."}'),
  ('c9905aae-12','{"options": ["Presbyopia", "Astigmatism", "Hyperopia", "Pseudomyopia"], "correct": 3, "explanation": "An accommodative spasm/excess is difficulty releasing accommodation and can produce pseudomyopia (a false myopic refraction that relaxes under cycloplegia)."}'),
  ('88edc373-u','{"options": ["Vergence movements", "Slow smooth tracking of a moving target", "Rapid eye movements jumping from one fixation point to another", "Fixation stability"], "correct": 2, "explanation": "Saccades are rapid movements that jump between fixation points, driven by a shift in attention. Pursuits are slow smooth movements following a moving object."}'),
  ('beeba0eb-2i','{"options": ["Ocular motility (pursuits/saccades)", "Stereopsis", "Color vision", "Accommodation amplitude"], "correct": 0, "explanation": "Ocular motility dysfunction produces line-skipping, losing place, needing a marker, and confusion on the return sweep during reading."}'),
  ('46cc6562-19','{"options": ["Directionality", "Accommodation", "Laterality", "Stereopsis"], "correct": 2, "explanation": "The Piaget test (and the Stickman test) assesses laterality, the internal awareness of the two body sides. Gardner Reversals and Jordan tests assess directionality."}'),
  ('5694a5f8-25','{"options": ["Directionality / visual spatial relations", "Color vision", "Convergence", "Accommodation"], "correct": 0, "explanation": "Persistent letter reversals (b/d, p/q) reflect poor directionality and visual spatial relations, projecting directional concepts incorrectly into space."}'),
  ('09486418-1y','{"options": ["No refractive error", "The higher refractive error", "Perfect acuity", "The lower refractive error"], "correct": 1, "explanation": "When strabismus and anisometropia coexist, the strabismic eye generally carries the higher refractive error, compounding the amblyopia."}'),
  ('5a20d128-1b','{"options": ["Reducing IOP", "Elimination of the epicanthal folds", "Improvement of visual acuity", "Cosmetic alignment"], "correct": 2, "explanation": "The primary objective is improving visual acuity, followed by eliminating eccentric fixation/abnormal localization and resolving the binocular anomaly causing the amblyopia."}'),
  ('1bfc41af-1m','{"options": ["No patching ever", "Full-time (all waking hours)", "About 2 hours per day", "10 minutes per week"], "correct": 2, "explanation": "Mild amblyopia is often treated with about 2 hours/day of patching; moderate-to-severe amblyopia uses full-time (all waking hours) patching, with VA monitored every 4-8 weeks."}'),
  ('423c4782-16','{"options": ["Surgery", "Fully occluding the good eye", "Using atropine in both eyes", "Stimulating both eyes simultaneously at different contrast levels (e.g., games/apps)"], "correct": 3, "explanation": "Dichoptic (emerging) treatment presents images to both eyes at different contrast levels, combining suppression treatment with active binocular stimulation."}'),
  ('2a96c2ed-1p','{"options": ["-1.00 D", "+2.00 D", "+3.50 D", "Plano"], "correct": 1, "explanation": "Average refraction at 1 year is about +2.00 D, decreasing from +3.00 D at 3 months toward +0.50 D by ages 4-6."}'),
  ('78ffbc82-27','{"options": ["Any trace", "-0.75 D or greater", "-3.00 D or greater", "-5.00 D or greater"], "correct": 1, "explanation": "In children over 2 years, myopia of -0.75 D or greater is a prescribing threshold; hyperopia at +3.00 D or greater and isolated astigmatism at 2.50 D or greater are the others."}'),
  ('6b481df7-1o','{"options": ["Birth to 1 month", "3 to 5 years", "Only after age 7", "7 months to 2 years"], "correct": 3, "explanation": "Optic nerve myelination proceeds from about 7 months to 2 years of age. Foveal maturation is around 4 months."}'),
  ('dba238cf-1e','{"options": ["2 years", "1 year", "6-8 weeks", "6 months"], "correct": 2, "explanation": "Smooth pursuit develops at about 6-8 weeks; saccades at 1-3 months; optokinetic nystagmus at 2-4 months."}'),
  ('a9059aa7-1j','{"options": ["Measure stereopsis", "Screen general developmental milestones in pre-schoolers", "Measure IOP", "Measure visual acuity"], "correct": 1, "explanation": "The Denver DDST screens developmental milestones (motor, language, social) in pre-schoolers as supplemental pediatric testing."}'),
  ('0731f802-3r','{"options": ["Cover test", "Snellen", "VEP/ERG (electronic diagnostic testing)", "Allen figures"], "correct": 2, "explanation": "Electronic diagnostic tests (VEP, ERG) objectively assess the visual pathway/retina without cooperation, useful in infants."}'),
  ('75bba9bb-1i','{"options": ["In old age", "At school vision screening", "Never", "At birth"], "correct": 1, "explanation": "Anisometropic amblyopia usually has normal alignment and is picked up at school vision screening, since there is no obvious strabismus to prompt earlier referral."}'),
  ('bc05e38e-1p','{"options": ["Cannot yet read letters but can indicate orientation/direction", "Know the full alphabet", "Have no vision", "Are under 1 year"], "correct": 0, "explanation": "The Tumbling E and Landolt C require only indicating the orientation/gap direction, so they suit ages 3-6 who cannot yet name letters."}'),
  ('9bca376d-1w','{"options": ["Excellent posture", "Toe fanning", "Slouched posture, low muscle tone, and balance/visual-perceptual difficulties", "Photophobia"], "correct": 2, "explanation": "Persistence of the TLR causes slouched posture, low muscle tone, poor balance, and visual-perceptual difficulties. It integrates at about 4 months postnatally."}'),
  ('e9961f21-x','{"options": ["Simultaneous stimulation of corresponding retinal points", "The vergence movement of the eyes that maintains single binocular vision", "A suppression scotoma", "Accommodation"], "correct": 1, "explanation": "Motor fusion is the physical vergence movement that aligns the eyes so sensory fusion can be maintained."}'),
  ('13b9f4fa-2a','{"options": ["Candy beads test", "Dot test", "Catford drum", "Kay picture test"], "correct": 0, "explanation": "The candy beads test estimates near acuity at 40 cm using progressively smaller candy beads; the dot test similarly uses shrinking isolated dots at 40 cm."}'),
  ('75526428-2c','{"options": ["Tumbling E", "Snellen", "Amsler grid", "Ishihara"], "correct": 0, "explanation": "The Sjogren hand test replaces the Tumbling E''s letter with an isolated hand figure whose orientation the child indicates."}'),
  ('3a7ee62b-13','{"options": ["Use both sides of the body separately and simultaneously (e.g., typing, cycling)", "Accommodate at near", "Fuse two images into one", "See fine detail"], "correct": 0, "explanation": "Bilateral integration is awareness and coordinated use of both body sides separately and together; tests include chalkboard circles and body knowledge/control."}'),
  ('09021d3a-2r','{"options": ["Hirschberg", "Bruckner", "Cover-uncover", "Krimsky"], "correct": 1, "explanation": "The Bruckner test shines a direct ophthalmoscope into both pupils at 1 m; a brighter, whiter reflex marks the deviating or amblyopic eye."}'),
  ('a68e16c3-1b','{"options": ["Deprivation", "Presbyopic", "Strabismic", "Anisometropic"], "correct": 1, "explanation": "The four types are strabismic, anisometropic, meridional, and deprivation. Presbyopia is an age-related accommodative loss, not a form of amblyopia."}'),
  ('b1a8b611-23','{"options": ["Matching to a keycard", "Naming colors", "Reporting motion", "Reading aloud"], "correct": 0, "explanation": "Both are matching tasks: the child points to the matching symbol/letter on a keycard, which works before a child can name optotypes."}'),
  ('ca95ddbd-1v','{"options": ["Conjunctivitis", "An eye muscle control problem (possible strabismus)", "A blocked tear duct", "Refractive error"], "correct": 1, "explanation": "Eyes not moving together indicates an eye-muscle control problem such as strabismus, which after 3-4 months of age is pathological."}'),
  ('48315281-17','{"options": ["Photophobia", "Improved handwriting", "Swallowing problems and delayed speech", "Better balance"], "correct": 2, "explanation": "A persistent palmar grasp reflex can be associated with swallowing problems and delayed speech; its complete absence signals a neurological problem."}'),
  ('febdbb9c-24','{"options": ["Eye health and refraction", "Color vision only", "The oculomotor system, accommodation, vergence, and sensory fusion", "Perceptual and visual-motor skills"], "correct": 2, "explanation": "Visual efficiency is the input channel: oculomotor control, accommodation, vergence, and sensory fusion. Visual integrity is eye health/refraction; visual information processing is perceptual/visual-motor."}'),
  ('c6385a1a-27','{"options": ["Bruckner", "NPC (near point of convergence)", "MEM retinoscopy", "Hirschberg"], "correct": 1, "explanation": "The near point of convergence (NPC) measures the closest point to which the eyes can converge, part of binocular vision/motility assessment."}'),
  ('531829ac-20','{"options": ["Both targets", "Nothing", "The red target", "The green target"], "correct": 3, "explanation": "With red/green (anaglyph) filters, the red-filter eye sees the green target and the green-filter eye sees the red target, because each filter absorbs its own color."}'),
  ('d8ad141f-13','{"options": ["1 year", "4 months of age", "30 weeks gestation", "3 years"], "correct": 1, "explanation": "Foveal maturation completes at about 4 months of age, contributing to the rapid acuity gains over the first year."}'),
  ('0c07216e-2r','{"options": ["Infantile esotropia", "Pseudostrabismus", "Accommodative esotropia", "Deprivation amblyopia"], "correct": 1, "explanation": "Pseudostrabismus needs no treatment: the corneal reflexes are symmetric and the crossed appearance resolves as the nasal bridge develops. Reassure the parents."}'),
  ('065207ae-36','{"options": ["Switch to inverse occlusion", "Proceed straight to surgery", "Stop all treatment", "Double the glasses power"], "correct": 0, "explanation": "If direct occlusion with unsteady/eccentric fixation fails to improve after 4 weeks, switching to inverse occlusion is recommended to develop foveal fixation."}'),
  ('1bfe07ad-1q','{"options": ["Visual acuity and colour vision", "The power of accommodation and convergence", "Intraocular pressure and tear film", "Retinal sensitivity and dark adaptation"], "correct": 1, "explanation": "The phorometric test deals specifically with the determination of the power of accommodation and convergence, particularly their relationship with each other."}'),
  ('8bb8e6fc-2a','{"options": ["Prisms", "Lenses", "Mirrors", "Occluders"], "correct": 1, "explanation": "Lenses are used for a specific effect upon the accommodative pattern, while prisms are used for a specific effect upon the convergence pattern."}'),
  ('26acabbf-z','{"options": ["Stimulates accommodation and makes the target appear smaller", "Inhibits accommodation and makes the target appear bigger", "Stimulates convergence and makes the target appear smaller", "Inhibits convergence and makes the target appear bigger"], "correct": 1, "explanation": "A convex lens inhibits accommodation. The induced change is as if the object moved away, so the target appears bigger."}'),
  ('9bde76e2-2e','{"options": ["Inhibits accommodation; target appears bigger", "Stimulates accommodation; target appears bigger", "Inhibits accommodation; target appears smaller", "Stimulates accommodation; target appears smaller"], "correct": 3, "explanation": "A concave lens stimulates accommodation. The induced change is as if the object moved closer, so the target appears smaller. Board trap: many confuse bigger/smaller with plus/minus."}'),
  ('f396a579-2d','{"options": ["Target appears smaller", "Target appears the same size", "Target appears bigger", "Target appears distorted"], "correct": 2, "explanation": "Base-In prism inhibits convergence. The induced change is as if the object moved away, so the target appears bigger."}'),
  ('31234086-26','{"options": ["Moved away from the plane of regard", "Remained at the same distance", "Moved closer to the observer", "Disappeared from view"], "correct": 2, "explanation": "Base-Out prism stimulates convergence. The induced change is as if the object moved closer to the observer. Target appears smaller as a result."}'),
  ('3b1b5b79-23','{"options": ["Convex lens and Base-Out prism", "Concave lens and Base-In prism", "Convex lens and Base-In prism", "Concave lens and Base-Out prism"], "correct": 2, "explanation": "Convex lens (inhibits accommodation) and Base-In prism (inhibits convergence) both make the target appear BIGGER. Concave and Base-Out both make it appear smaller. Board trap: knowing which inhibit and which stimulate."}'),
  ('4d98a13c-1a','{"options": ["Esophoria", "Hyperopia", "Exophoria", "Myopia"], "correct": 2, "explanation": "Exophoria is the buffer area for the convergence pattern. Hyperopia is the buffer area for the accommodative pattern."}'),
  ('5d6a3acf-1c','{"options": ["Exophoria", "Esophoria", "Myopia", "Hyperopia"], "correct": 3, "explanation": "Hyperopia is the buffer area for the accommodative pattern. Exophoria is the buffer for convergence. These two are commonly reversed in board questions."}'),
  ('7b1939d5-1l','{"options": ["Lenses and mirrors", "Lenses and prisms", "Prisms and mirrors", "Filters and lenses"], "correct": 1, "explanation": "Probe bodies are composed of lenses and prisms. Lenses affect accommodation; prisms affect convergence."}'),
  ('fdbb3c9f-2f','{"options": ["Object appears to move away; target appears bigger", "Object appears to move closer; target appears bigger", "Object appears to move away; target appears smaller", "Object appears to move closer; target appears smaller"], "correct": 3, "explanation": "Base-Out prism stimulates convergence. The induced change is as if the object moved closer; the target appears smaller."}'),
  ('541dce7b-1e','{"options": ["1.50D", "2.00D", "2.50D", "3.00D"], "correct": 2, "explanation": "At 16 inches (40cm), the stimulus to accommodation is 2.50D and the stimulus to convergence is 15 prisms (if PD is approximately 64mm)."}'),
  ('9e76be19-23','{"options": ["10 prism dioptres", "12 prism dioptres", "15 prism dioptres", "18 prism dioptres"], "correct": 2, "explanation": "At 16 inches the stimulus to convergence is 15 prism dioptres when PD is approximately 64mm."}'),
  ('5dcd323c-1c','{"options": ["A horizontal dissociating prism before both eyes", "A vertical dissociating prism before one eye and a measuring prism before the other", "Two measuring prisms before both eyes", "A polaroid dissociator and prism bar"], "correct": 1, "explanation": "The Von Graefe method places a dissociating prism before one eye and a measuring prism before the other eye."}'),
  ('8e1b406f-1j','{"options": ["Horizontal dissociating prism", "Vertical dissociating prism", "Base-Out prism", "Base-In prism"], "correct": 1, "explanation": "A vertical dissociating prism is used for the measurement of a lateral phoria. A horizontal dissociating prism is used for vertical phoria."}'),
  ('208d9a92-1k','{"options": ["Vertical dissociating prism", "Horizontal dissociating prism", "Base-Up prism only", "Base-Down prism only"], "correct": 1, "explanation": "A horizontal dissociating prism is used for the measurement of vertical phoria. Board trap: vertical phoria requires a horizontal prism (not a vertical one)."}'),
  ('a3b0e0d1-1z','{"options": ["10 ft and 16 inches", "20 ft and 33 cm", "20 ft (6M) and 16 inches (40cm)", "6M and 50cm"], "correct": 2, "explanation": "Phorias are measured at distances of 20 ft (6M) and 16 inches (40cm)."}'),
  ('ac49e474-1e','{"options": ["Measure the amplitude of accommodation", "Indicate the position of rest of the eyes when fusional convergence is relaxed", "Determine intraocular pressure", "Assess retinal sensitivity"], "correct": 1, "explanation": "The phoria test is designated primarily to indicate the position of rest of the eyes when fusional convergence is relaxed."}'),
  ('d3c80c6f-2v','{"options": ["Miosis only", "Convergence and miosis but not accommodation", "Accommodation and convergence but not miosis", "Convergence only"], "correct": 1, "explanation": "If plus lenses are placed before each eye, pupillary constriction (miosis) and convergence occur without accommodation. Each near reaction can occur without the others."}'),
  ('b0fee0a9-1u','{"options": ["Accommodation and miosis but not convergence", "Convergence and accommodation but not miosis", "Miosis only", "Convergence only"], "correct": 0, "explanation": "If a base-in prism is placed before each eye, pupillary constriction and accommodation occur without convergence. Convergence is inhibited by BI prism."}'),
  ('6193ca6d-11','{"options": ["Lateral muscular imbalance at far using test #7 lenses", "Lateral muscular imbalance at near using habitual correction", "Lateral muscular imbalance at far using habitual correction", "Vertical muscular imbalance at far"], "correct": 2, "explanation": "Test #3 determines the lateral muscular imbalance at far using the patient''s habitual correction. It is called the habitual lateral phoria at far."}'),
  ('734011ce-1b','{"options": ["Test distance — #3 is at far, #8 is at near", "Lenses in place — #3 uses habitual correction, #8 uses Test #7 results", "Prism setup — #3 uses BI prisms, #8 uses BO prisms", "Endpoint — #3 uses blur, #8 uses vertical alignment"], "correct": 1, "explanation": "Both tests are at 20ft with the same prism setup and endpoint (vertical alignment). The difference is the lenses: #3 uses habitual correction, #8 uses Test #7 (the subjective refraction result)."}'),
  ('5e77389f-1s','{"options": ["OD: 6△BU / OS: 12-15△BI", "OD: 12-15△BI / OS: 6△BU", "OU: 3△BD", "OU: ready to turn BO"], "correct": 1, "explanation": "The prism setup for Test #3 is OD: 12-15△BI and OS: 6△BU. This same setup is used for all lateral phoria tests (#3, #8, #13A, #13B, #15A, #15B)."}'),
  ('8b17caa9-q','{"options": ["Blur out", "Break and recovery", "Vertical alignment", "Horizontal alignment"], "correct": 2, "explanation": "The endpoint for Test #3 (and all lateral phoria tests) is vertical alignment. The measuring prism brings the two displaced images into vertical alignment to quantify the phoria."}'),
  ('9f4d2c1f-1b','{"options": ["Lateral muscular imbalance at far influenced by Test #7", "Vertical muscular imbalance at far", "Lateral phoria at near influenced by Test #7", "Amplitude of accommodation"], "correct": 0, "explanation": "Test #8 determines the lateral muscular imbalance at far as influenced by Test #7 (the subjective refraction result). It shows how the prescription affects the phoria at far."}'),
  ('7476004d-1z','{"options": ["Test #8", "Test #13B", "Test #13A", "Test #15A"], "correct": 2, "explanation": "Test #13A is the habitual lateral phoria at near. It uses habitual correction at near, the same as Test #3 uses habitual correction at far. #13B is the induced version at near."}'),
  ('ffbafe85-19','{"options": ["Near PD", "Far PD", "Any PD", "Monocular PD"], "correct": 1, "explanation": "Test #3 is at far (20ft), so the phoropter is adjusted to Far PD. Near tests use Near PD."}'),
  ('0e4f9664-q','{"options": ["Habitual correction at near", "Test No. 7 lenses", "Gross No. 14A lenses", "Test No. 7 (H/E)"], "correct": 1, "explanation": "Test #13B uses Test No. 7 lenses (subjective refraction), not Gross No. 14A. #13A uses habitual correction, while #15A/#15B use 14A/14B lenses."}'),
  ('bf92e32a-1j','{"options": ["OU: ready to turn BI", "OU: ready to turn BO", "OD: 12-15△BI / OS: 6△BU", "OD: 3△BD / OS: 3△BU"], "correct": 1, "explanation": "Test #9 uses OU ready to turn BO (Base-Out). Despite being called ''adduction'' (inward movement), the BO prism forces the eyes to converge more — this is the true adduction test at far."}'),
  ('3152353a-15','{"options": ["Break and recovery", "Vertical alignment", "Blur (same as adding +0.25D)", "Horizontal alignment"], "correct": 2, "explanation": "The endpoint for Test #9 is blur — specifically blur equivalent to what +0.25D auxiliary lens produces. This is different from #10 whose endpoint is Break/Recovery."}'),
  ('944ad1de-z','{"options": ["The limit of available fusional convergence in reserve at blur", "The reserve of the total positive convergence at far; break represents total positive convergence", "The negative fusional convergence in reserve at far", "The amplitude of accommodation at far"], "correct": 1, "explanation": "Test #10: Breakpoint represents the reserve of the total positive convergence at far. Recovery represents the limit of the fusional field in that direction."}'),
  ('7da49f58-27','{"options": ["BO prisms; positive fusional reserve", "BI prisms; negative fusional convergence or divergence in reserve", "BO prisms; negative fusional convergence", "BI prisms; positive fusional reserve"], "correct": 1, "explanation": "Test #11 uses BI (Base-In) prisms and the breakpoint indicates the negative fusional convergence or divergence in reserve at far."}'),
  ('44fe183d-1c','{"options": ["Test #10", "Test #9", "Test #11", "Test #12"], "correct": 1, "explanation": "Test #9 (True Adduction at Far) uses an auxiliary +0.25D lens. The endpoint is blur equivalent to the effect of this +0.25D lens."}'),
  ('9ace6ede-12','{"options": ["Habitual correction", "Test No. 7", "Gross No. 14A", "Test No. 7 plus auxiliary"], "correct": 1, "explanation": "Tests #9, #10, and #11 all use Test No. 7 lenses (the result of subjective refraction). They are all conducted at 20ft with far PD."}'),
  ('1379295b-15','{"options": ["The amount of lateral imbalance at far", "The amount of vertical imbalance at far", "The amplitude of accommodation at near", "The positive relative convergence at near"], "correct": 1, "explanation": "Test #12 phoria component determines the amount of vertical imbalance at far. The duction component determines the reserve used at far to compensate vertical imbalance."}'),
  ('4bc9750e-1p','{"options": ["Vertical alignment", "Horizontal alignment", "Break and recovery", "Blur out"], "correct": 2, "explanation": "The vertical duction component of Test #12 has a Break/Recovery endpoint. The phoria component uses horizontal alignment as its endpoint."}'),
  ('07ca02e2-1p','{"options": ["Test distance — #12 is at far, #18 is at near", "Prism direction — #12 uses BU/BD, #18 uses BI/BU", "Lenses — #12 uses habitual, #18 uses Test #7", "Endpoint — #12 uses blur, #18 uses break"], "correct": 0, "explanation": "Tests #12 and #18 are identical except for test distance. #12 is at 20ft (Far PD), #18 is at 16 inches (Near PD). Both use Test #7, BU/BD prisms, and Break/Recovery endpoints."}'),
  ('f1f26817-28','{"options": ["OD: 12-15△BI / OS: 6△BU", "OU: ready to turn BO", "OD: 12-15△BI / OS: 6△BU for phoria; BU and BD for duction", "OU: 3△BD and 3△BU"], "correct": 2, "explanation": "For phoria in #12 and #18: OD 12-15△BI / OS 6△BU with endpoint horizontal alignment. For duction: prisms ready to turn BU and BD with endpoint Break/Recovery."}'),
  ('913e373d-13','{"options": ["Far PD", "Near PD", "Monocular PD", "Interpupillary distance at 33cm"], "correct": 1, "explanation": "Test #18 is at 16 inches (40cm), so it uses Near PD. Test #12 is at 20ft and uses Far PD."}'),
  ('5eec02d8-1m','{"options": ["OD: 12-15△BI / OS: 6△BU", "OD: 3△BD / OS: 3△BU", "OU: ready to turn BO", "No prisms"], "correct": 1, "explanation": "Test #14A uses OD: 3△BD and OS: 3△BU to dissociate the images. This is different from the 12-15△BI / 6△BU used in phoria tests."}'),
  ('937947d4-1r','{"options": ["Test distance — #14A is at far, #14B is at near", "Prisms — #14B uses no prisms; images are fused", "Endpoint — #14A uses blur, #14B uses alignment", "Lenses — #14A uses Test #7, #14B uses habitual correction"], "correct": 1, "explanation": "The key difference: #14A uses dissociating prisms (OD 3△BD / OS 3△BU) making it dissociated. #14B uses NO prisms, keeping the images fused (binocular condition). Both have the same endpoint: equality (highest plus)."}'),
  ('7b54d2db-1c','{"options": ["Maddox rod", "Cross-cylinder (-0.50D) with red dot at 90", "Polaroid filter", "+0.50D cross-cylinder"], "correct": 1, "explanation": "Both #14A and #14B use a cross-cylinder of -0.50D with the red dot at 90 degrees as the auxiliary device."}'),
  ('855a442a-s','{"options": ["Blur out", "Break and recovery", "Equality — highest plus", "Vertical alignment"], "correct": 2, "explanation": "The endpoint for Test #14A is equality at the highest plus level. This is also the endpoint for Test #14B."}'),
  ('305ba6f7-19','{"options": ["The lag of accommodation under fused condition", "The lag of accommodation under dissociated condition", "The positive fusional reserve at near", "The amplitude of accommodation"], "correct": 1, "explanation": "Test #14A indicates the lag of accommodation under dissociated condition. Test #14B indicates the lag under fused (binocular) condition."}'),
  ('55bf5563-q','{"options": ["Test No. 7", "Habitual near correction", "Gross No. 14A", "Test No. 7 plus cross-cylinder"], "correct": 2, "explanation": "Test #14B uses Gross No. 14A as the lenses in place. This is a common board trap — #14A uses Test #7, but #14B builds on #14A''s gross finding."}'),
  ('06a6edc8-17','{"options": ["Smallest readable Snellen", "Reduced Snellen", "Cross grid", "0.62 Em type"], "correct": 2, "explanation": "Both #14A and #14B use a cross grid as the test target. This is different from other near tests which use the smallest readable target."}'),
  ('3b4ce22e-1a','{"options": ["20 ft. candle only", "Dim illumination only", "20 ft. candle or dim illumination", "Bright overhead lighting"], "correct": 2, "explanation": "Tests #14A and #14B are conducted under 20 ft. candle or dim illumination, unlike most other tests which use 20 ft. candle only."}'),
  ('38ce2f4e-j','{"options": ["Lag of accommodation under dissociated condition", "Influence of #14A lenses on lateral muscular imbalance at near", "Positive relative convergence at near", "Amplitude of accommodation"], "correct": 1, "explanation": "Test #15A determines the influence of #14A lenses on lateral muscular imbalance at near. It uses the same prism setup as lateral phoria tests (OD 12-15△BI / OS 6△BU)."}'),
  ('a189feae-v','{"options": ["Cross grid", "0.62 Em type", "Smallest readable", "Reduced Snellen"], "correct": 3, "explanation": "Test #15B uses a Reduced Snellen as the test target. Test #15A uses a Cross grid. Board trap: #15A and #15B share the same prism setup but differ in lenses and target."}'),
  ('2ad0f40a-q','{"options": ["Test No. 7", "Gross No. 14A", "Gross No. 14B", "Habitual near correction"], "correct": 2, "explanation": "Test #15B uses Gross No. 14B as the lenses in place. Test #15A uses Gross No. 14A. Both have the same endpoint: vertical alignment."}'),
  ('8d524168-1t','{"options": ["Test #7", "Test #13A", "Test #14A", "Test #14B"], "correct": 2, "explanation": "Test #15A determines the influence of #14A lenses on lateral muscular imbalance at near. #15B determines the influence of #14B lenses."}'),
  ('f889fbfc-16','{"options": ["Blur out", "Break and recovery", "Equality — highest plus", "Vertical alignment"], "correct": 3, "explanation": "Both #15A and #15B have vertical alignment as their endpoint. They function like phoria tests but with the cross-cylinder lenses in place."}'),
  ('b3fe1f40-1t','{"options": ["OU: ready to turn BI", "OU: ready to turn BO", "OD: 12-15△BI / OS: 6△BU", "OD: 3△BD / OS: 3△BU"], "correct": 1, "explanation": "Test #16A uses OU ready to turn Base-Out (BO). BO prisms stimulate convergence. Tests #16A and #16B are the positive convergence tests."}'),
  ('e4381ae9-w','{"options": ["Break and recovery", "Vertical alignment", "Blur out", "Horizontal alignment"], "correct": 2, "explanation": "Test #16A (Positive Relative Convergence) endpoint is blur out only. Test #16B (Positive Fusional Reserve) goes further to break and recovery. Board trap: #16A stops at blur; #16B continues to break."}'),
  ('84adeaf4-1m','{"options": ["It indicates the limit of total convergence at near", "It indicates the amount of positive fusional innervation in reserve at the fixation distance", "It indicates the break point of the vergence system", "It indicates the amplitude of accommodation"], "correct": 1, "explanation": "In Test #16A, the blur point indicates the amount of positive fusional innervation in reserve available at that fixation distance."}'),
  ('92cf8a07-1u','{"options": ["The total positive convergence at near", "The limit of the fusion field in that direction", "The accommodative convergence in reserve", "The blur point of accommodation"], "correct": 1, "explanation": "In Test #16B, the break point indicates accommodative convergence in reserve. The recovery point indicates the limit of the fusion field in that direction."}'),
  ('10d39bbc-17','{"options": ["OU: ready to turn BO", "OU: ready to turn BI", "OD: 3△BD / OS: 3△BU", "OD: 12-15△BI / OS: 6△BU"], "correct": 1, "explanation": "Tests #17A and #17B use OU ready to turn Base-In (BI). BI prisms inhibit convergence. Board trap: #16A/16B = BO (positive), #17A/17B = BI (negative)."}'),
  ('725e087b-1m','{"options": ["Break and recovery", "Blur out", "Vertical alignment", "Horizontal alignment"], "correct": 1, "explanation": "Test #17A (NRC) endpoint is blur out. Test #17B (NFR) endpoint is break and recovery. Same A/B rule: A = blur, B = break/recovery."}'),
  ('93315985-1n','{"options": ["The positive fusional innervation in reserve", "The amount of convergence that can be stimulated", "The amount of negative fusional convergence or convergence relaxable at that fixation distance", "The accommodative convergence in reserve"], "correct": 2, "explanation": "Test #17A blur point indicates the amount of negative fusional convergence or measures the amount of convergence relaxable at that fixation distance."}'),
  ('7de4aad9-1q','{"options": ["Habitual near correction", "Test #7 (H/E)", "Gross No. 14A", "Gross No. 14B"], "correct": 1, "explanation": "For a non-presbyope, Tests #16A and #16B use Test #7 (H/E). For presbyopes they use 14B Net. For myopes they use habitual minus at near."}'),
  ('dc7d97ce-1m','{"options": ["Test #7", "Habitual near correction", "Gross No. 14A", "14B Net"], "correct": 3, "explanation": "For presbyopes, Tests #16A, #16B, #17A, and #17B use 14B Net. Non-presbyopes use Test #7 (H/E). Myopes use habitual minus at near. Board trap: the lens varies by patient type."}'),
  ('dcf5698e-1k','{"options": ["The limit of the fusion field", "The amount of negative fusional convergence relaxable", "The amount of accommodative convergence which relaxation of accommodation can inhibit", "The total negative convergence at near"], "correct": 2, "explanation": "Test #17B break point indicates the amount of accommodative convergence which the relaxation of accommodation can inhibit. Recovery indicates the limit of the fusion field."}'),
  ('bcc9b94f-1l','{"options": ["Smallest readable Snellen", "Cross grid", "Reduced Snellen (20/20)", "0.62 Em type"], "correct": 3, "explanation": "Test #19 uses 0.62 Em type as the test target, which is different from most other near tests that use smallest readable."}'),
  ('a2b5178c-26','{"options": ["Plus lenses; 1st readable", "Minus lenses; print difficult to read", "Plus lenses; blur out", "Minus lenses; 1st readable"], "correct": 1, "explanation": "For a non-presbyope: minus lenses are added until print becomes difficult to read. For a presbyope: plus lenses are added until 1st readable. Board trap: direction of lens change is opposite."}'),
  ('9f3f37f9-1n','{"options": ["To determine the positive relative accommodation", "To determine the maximum amplitude of accommodation", "To determine the lag of accommodation", "To determine the positive fusional reserve"], "correct": 1, "explanation": "Test #19 determines the amount (maximum) of amplitude of accommodation available to the patient."}'),
  ('7cf2b60d-1m','{"options": ["Plus lenses added until 20/20 cannot be read", "Minus lenses added until 20/20 cannot be read", "BO prisms added until blur", "BI prisms added until break"], "correct": 1, "explanation": "Test #20 (PRA): minus lenses are added until the patient cannot read the 20/20 reduced Snellen. This measures the maximum amount of accommodation that can be stimulated."}'),
  ('e1afdff0-1m','{"options": ["Minus lenses added; endpoint blur out", "Plus lenses added; endpoint blur out", "BI prisms; endpoint blur out", "BO prisms; endpoint break/recovery"], "correct": 1, "explanation": "Test #21 (NRA): plus lenses are added until blur. This inhibits accommodation. Board trap: PRA (#20) = minus lenses (stimulate). NRA (#21) = plus lenses (inhibit)."}'),
  ('afdb6ebc-l','{"options": ["The extent to which accommodation can be inhibited at 16 inches", "The extent to which accommodation can be stimulated at 16 inches", "The amplitude of accommodation", "The lag of accommodation"], "correct": 1, "explanation": "Test #20 indicates the extent at which accommodation would be STIMULATED while fixation is maintained at 16 inches."}'),
  ('71b0e3a9-l','{"options": ["The extent to which accommodation can be stimulated at 16 inches", "The amplitude of accommodation available", "The extent to which accommodation can be inhibited at 16 inches", "The positive fusional convergence in reserve"], "correct": 2, "explanation": "Test #21 indicates the extent at which accommodation could be INHIBITED while fixation is maintained at 16 inches."}'),
  ('22555703-1j','{"options": ["Break and recovery", "Vertical alignment", "1st readable", "Blur out"], "correct": 3, "explanation": "Both #20 (PRA) and #21 (NRA) have blur out as their endpoint. The difference is the direction of lens change: #20 adds minus, #21 adds plus."}'),
  ('8080a06c-25','{"options": ["Test #7", "Habitual near correction", "14B Net", "Gross No. 14A"], "correct": 2, "explanation": "For presbyopes in Tests #20 and #21, the starting lenses are 14B Net. Non-presbyopes use Test #7 (H/E). Myopes use habitual minus at near."}'),
  ('fd47d1c0-1g','{"options": ["Blur out", "Print becomes difficult to read", "1st readable", "Break"], "correct": 2, "explanation": "For presbyopes in Test #19: plus lenses are added until 1st readable (the point where they can just read the target). For non-presbyopes: minus lenses until print becomes difficult."}'),
  ('85973040-17','{"options": ["Gross #4 minus lag", "Gross #4 minus working distance", "Gross #5 minus lag", "Gross #4 plus working distance"], "correct": 1, "explanation": "Net #4 = Gross #4 minus Working Distance. The working distance is subtracted because it represents the dioptric equivalent of the examiner''s distance."}'),
  ('6ee43dcc-1a','{"options": ["+2.00", "+0.00", "+4.00", "+1.00"], "correct": 1, "explanation": "WD at 50cm = 100/50 = 2.00D. Net #4 = Gross #4 - WD = +2.00 - 2.00 = +0.00. The patient has no net hyperopia at this distance."}'),
  ('d4b47f89-1a','{"options": ["+1.00", "+3.00", "+5.00", "+2.00"], "correct": 0, "explanation": "WD at 50cm = 2.00D. Net #4 = +3.00 - 2.00 = +1.00."}'),
  ('8332c0b7-1g','{"options": ["Net #5 minus Net #6", "Net #6 minus Net #4", "Net #5 minus Net #4", "Net #4 minus Net #5"], "correct": 2, "explanation": "Reading Add = Net #5 minus Net #4. This is the fundamental OEP reading add formula."}'),
  ('9b750efa-13','{"options": ["+0.00", "+2.75", "+5.50", "+1.375"], "correct": 1, "explanation": "Reading Add = Net #5 - Net #4 = +2.75 - 0.00 = +2.75 sph."}'),
  ('4a9f94af-13','{"options": ["+4.25", "+2.25", "+3.25", "+1.00"], "correct": 1, "explanation": "Reading Add = Net #5 - Net #4 = +3.25 - +1.00 = +2.25 sph."}'),
  ('84f9396e-1q','{"options": ["0.12", "0.25", "0.50", "0.75"], "correct": 1, "explanation": "From the OEP lag table: 2 XOP = 0.25 lag. 1 XOP = 0.12, 4 XOP = 0.50, 6 XOP = 0.75."}'),
  ('92660c28-1q','{"options": ["0.75", "0.87", "1.00", "1.25"], "correct": 2, "explanation": "From the OEP lag table: 8 XOP = 1.00 lag."}'),
  ('16d5874e-1i','{"options": ["When AA is 5.00D and above", "When AA is less than 5.00D", "Always in every calculation", "Only when phoria is esophoric"], "correct": 1, "explanation": "The modified lag formula ML = Lag x AA/5 is applied only when AA is LESS than 5.00D. If AA is 5.00D and above, the lag from the table is used directly without modification."}'),
  ('3df67ca6-21','{"options": ["0.25", "0.125", "0.50", "0.375"], "correct": 1, "explanation": "Lag from table for 2 XOP = 0.25. Since AA < 5.00D: ML = Lag x AA/5 = 0.25 x (2.50/5) = 0.25 x 0.5 = 0.125."}'),
  ('7874ce50-j','{"options": ["Working distance", "Net #4", "Lag (0.25D when AA ≥ 5.00D)", "Modified lag"], "correct": 2, "explanation": "Net #6 = Gross #6 minus lag. When AA is 5.00D and above, the lag is 0.25D (from the table for the measured XOP). The formula is straightforward subtraction."}'),
  ('869e184a-18','{"options": ["+3.00", "+2.75", "+2.50", "+2.25"], "correct": 2, "explanation": "Net #6 = Gross #6 - lag = +2.75 - 0.25 = +2.50 sph."}'),
  ('a2a39a68-1p','{"options": ["TC minus AC", "En minus Ed", "Ed minus En", "TC minus En"], "correct": 1, "explanation": "PEX = En - Ed, where En = phoria at near and Ed = phoria at far (distance). Positive values are XOP, negative values are ESO."}'),
  ('e3820a13-1f','{"options": ["10 XOP", "6 XOP", "4 XOP", "2 XOP"], "correct": 1, "explanation": "PEX = En - Ed = 8 - 2 = 6 XOP."}'),
  ('d03b3726-27','{"options": ["24△", "12△", "6△", "18△"], "correct": 1, "explanation": "AC = TC - PEX = 18 - 6 = 12△. TC at 13 inches is 18 prism dioptres. TC at 16 inches is 15 prism dioptres."}'),
  ('8e0a4e88-2h','{"options": ["Binocular Cross-Cylinder (#14A) and Dissociated Cross-Cylinder (#14B)", "Amplitude of Accommodation (#19) and PRA (#20)", "Phoria tests at far and near (#3, #8, #13A, #13B)", "NRA (#21) only"], "correct": 2, "explanation": "Tests altering stimulus to convergence include phoria tests (#3, #8, #12, #13A, #13B, #15A, #15B, #18) and duction/vergence tests (#9, #10, #11, #16A, #16B, #17A, #17B). CC tests (#14A, #14B) and accommodation tests (#19, #20, #21) alter accommodation stimulus."}'),
  ('5b7860a3-20','{"options": ["They do not have a defined endpoint", "The patient''s response is subjective and variable", "They measure accommodation indirectly through a cross-cylinder, not directly", "They are not part of the standard 21-step sequence"], "correct": 2, "explanation": "Tests #14A (Binocular CC) and #14B (Dissociated CC) are tests of indefinite response. Tests of definite response include AA (#19), PRA (#20), and NRA (#21)."}'),
  ('02f65b81-2e','{"options": ["#14A and #14B", "#19, #20, and #21", "#16A, #16B, #17A, and #17B", "#3 and #8"], "correct": 1, "explanation": "Tests of definite response under accommodation include Amplitude of Accommodation (#19), Positive Relative Accommodation (#20), and Negative Relative Accommodation (#21)."}'),
  ('fc3ca62e-1i','{"options": ["10 ft. candle", "20 ft. candle", "30 ft. candle", "Dim illumination only"], "correct": 1, "explanation": "Most tests in the 21-step sequence use 20 ft. candle illumination. Tests #14A and #14B may use dim illumination alternatively."}'),
  ('f650b7cf-1u','{"options": ["#3 and #13A", "#9 and #11", "#12 and #18", "#16A and #17A"], "correct": 2, "explanation": "Tests #12 and #18 measure vertical phoria and vertical duction, at far and near respectively. #3 and #13A measure lateral phoria."}'),
  ('4739ac28-2e','{"options": ["Ophthalmoscope and slit lamp", "Lenses and prisms as probe bodies", "Retinoscope and keratometer", "Tonometer and perimeter"], "correct": 1, "explanation": "The phorometric test uses probe bodies composed of lenses (for accommodation) and prisms (for convergence) to investigate the relationship between these two visual patterns."}'),
  ('d34ce110-1y','{"options": ["#4 is done binocularly; #5 and #6 are monocular", "#4 allows for working distance; #5 and #6 do not", "#4 is at near; #5 and #6 are at far", "#4 uses prisms; #5 and #6 use lenses"], "correct": 1, "explanation": "Static retinoscopy (Test #4) gives allowance for working distance. Dynamic retinoscopy (#5, #6) gives no allowance for working distance because the patient fixates at the plane of the retinoscope."}'),
  ('8830f359-25','{"options": ["The lowest neutral point (LNP)", "The first neutral point", "The highest neutral point (HNP) — highest plus or least minus", "The reversal point"], "correct": 2, "explanation": "The amount of plus with the highest plus or least minus represents the gross finding in Test #5 — this is the HNP (Highest Neutral Point)."}'),
  ('87033f23-2e','{"options": ["Against motion — add plus", "With motion — add plus", "Neutral — add plus", "Against motion — add minus"], "correct": 1, "explanation": "In MEM: With motion means the eye is under-accommodating, so plus lenses are added. Against motion means over-accommodating, so minus lenses are added."}'),
  ('448b4999-1y','{"options": ["Moves closer to the patient until neutral", "Moves away from the patient until neutral while keeping the target fixed", "Adds plus lenses until neutral", "Adds minus lenses until neutral"], "correct": 1, "explanation": "In the Nott method, if the movement is with, the examiner moves AWAY from the patient (keeping the target fixed) until the neutral point is reached. This measures the lag of accommodation."}'),
  ('4a105244-21','{"options": ["0.25D or slightly more", "0.50D or slightly more", "0.75D or slightly more", "1.00D or slightly more"], "correct": 1, "explanation": "Sheard believed the normal lag of accommodation was 0.50D or slightly more, and routinely subtracted 0.50D from the dynamic finding."}'),
  ('9922a2c9-2r','{"options": ["20-30cm", "35-42cm (14-17 inches)", "50-60cm", "10-15cm"], "correct": 1, "explanation": "In Bell retinoscopy, a change from ''with'' to ''against'' is typically between 35-42cm (14-17 inches), and the change back from ''against'' to ''with'' at 37.5-45cm (15-18 inches)."}'),
  ('3ef4aa68-1q','{"options": ["Tests #14A, #14B, and #15A", "Tests #16A and #16B", "Tests #3 and #8", "Tests #19, #20, and #21"], "correct": 0, "explanation": "Tests #14A, #14B, and #15A use the cross grid as the test target. Test #15B uses a Reduced Snellen. Most other near tests use the smallest readable target."}'),
  ('1832d656-1b','{"options": ["Test #19 (Amplitude of Accommodation)", "Test #20 (PRA)", "Test #21 (NRA)", "Test #16A (PRC)"], "correct": 0, "explanation": "Test #19 (Amplitude of Accommodation) uses 0.62 Em type. Tests #20, #21, #16A, #16B, #17A, and #17B use the smallest readable (20/20 reduced Snellen)."}'),
  ('7312f0d4-1q','{"options": ["Test #7", "14B Net", "Habitual minus at near", "Habitual correction at far"], "correct": 2, "explanation": "For myopes in Tests #16A, #16B, #17A, and #17B: habitual minus at near. Non-presbyopes use Test #7 (H/E). Presbyopes use 14B Net."}'),
  ('4176c7fd-2c','{"options": ["Test #10", "Test #9", "Test #11", "Test #16A"], "correct": 1, "explanation": "Test #9 (True Adduction at Far) has a unique endpoint: blur equivalent to adding +0.25D auxiliary lens. This differentiates it from #10 and #11 which use break/recovery."}'),
  ('01ae7469-2c','{"options": ["Prism direction — #9 uses BI, #10 uses BO", "Endpoint — #9 endpoint is blur; #10 endpoint is break/recovery; also #9 uses +0.25 auxiliary", "Lenses — #9 uses habitual, #10 uses Test #7", "Test distance — #9 is at near, #10 is at far"], "correct": 1, "explanation": "Both use BO prisms and Test #7 lenses at far. The differences are: #9 uses a +0.25D auxiliary lens and has blur as its endpoint, while #10 has break/recovery and no auxiliary lens."}'),
  ('4f3660a9-16','{"options": ["20 inches (50cm)", "16 inches (40cm)", "13 inches (33cm)", "10 inches (25cm)"], "correct": 2, "explanation": "Tait''s method uses a working distance of 33cm (13 inches), where total convergence (TC) = 18 prism dioptres."}'),
  ('2e2cfe20-2t','{"options": ["No symptoms — exophoria is the buffer for convergence", "Symptoms of convergence insufficiency: eyestrain and intermittent diplopia during near work", "Difficulty seeing at distance", "Reduced amplitude of accommodation"], "correct": 1, "explanation": "Large exophoria = high convergence demand. Small PFR = low reserve. The patient uses most of their convergence just to align the eyes, leaving little in reserve. This produces symptoms of convergence insufficiency during near work."}'),
  ('ec735f2b-2i','{"options": ["Test #14A", "Test #14B", "Test #15A", "Test #15B"], "correct": 1, "explanation": "Test #14B (Binocular Cross-Cylinder) measures the lag of accommodation under fused (binocular) conditions. Test #14A measures it under dissociated conditions."}'),
  ('4dd017b7-28','{"options": ["Test #13A", "Test #9", "Test #14A", "Test #16B"], "correct": 1, "explanation": "Test #9 (True Adduction at Far) is conducted at 20ft (6M), NOT at near. All other listed tests are near tests at 16 inches."}'),
  ('4de73698-3i','{"options": ["Accommodation has been maximally inhibited", "Accommodation has been maximally stimulated and reached its limit", "Convergence reserve is depleted", "The lag of accommodation is excessive"], "correct": 1, "explanation": "In Test #20 (PRA), minus lenses stimulate accommodation. When the patient can no longer read the target, accommodation has been maximally STIMULATED and reached its limit. The blur indicates the PRA endpoint."}'),
  ('22e27b5f-1z','{"options": ["Test #3", "Test #8", "Test #12", "Test #13A"], "correct": 2, "explanation": "Test #12 is a VERTICAL phoria and vertical duction test, not a lateral phoria test. Tests #3, #8, #13A, #13B, #15A, and #15B are all lateral phoria tests."}'),
  ('9f8ff8a9-1i','{"options": ["The maximum convergence available", "The limit of the fusion field in that direction", "The accommodative convergence in reserve", "The point where accommodation is maximally stimulated"], "correct": 1, "explanation": "In all vergence tests with a break/recovery endpoint, the recovery point indicates the limit of the fusion field in that direction."}'),
  ('50c224ac-2p','{"options": ["Test #17A (NRC) — BI prisms", "Test #11 (Abduction at Far) — BI prisms", "Test #16A (PRC) — BO prisms", "Test #12 (Vertical Duction) — BU/BD prisms"], "correct": 2, "explanation": "In Test #16A (PRC), BO prisms force more convergence, which drags accommodation along (due to the AC/A link). Accommodation reaches its limit first, causing blur before the convergence system itself breaks down. This is why PRC endpoint is blur, not break."}'),
  ('0b5079a7-2a','{"options": ["OU: ready to turn BO", "OD: 3△BD / OS: 3△BU", "OD: 12-15△BI / OS: 6△BU", "OU: 6△BU"], "correct": 2, "explanation": "All lateral phoria tests use OD: 12-15△BI and OS: 6△BU. The BI prism dissociates the images laterally, and the BU prism separates them vertically so the measuring prism can quantify the lateral deviation."}'),
  ('98206b1b-1a','{"options": ["Near target", "Blur", "Light intensity", "Convergence"], "correct": 1, "explanation": "Blur is the primary stimulus for accommodation. When an image is out of focus on the retina, the blur signals the ciliary muscle to contract and change the lens power. Near target is another stimulus but secondary to blur."}'),
  ('645be818-1p','{"options": ["Crystalline lens", "Vitreous humour", "Cornea", "Aqueous humour"], "correct": 2, "explanation": "The cornea contributes approximately 2/3 (about 43 D out of 58.64 D total) of the eye''s refractive power, while the crystalline lens contributes 1/3 (about 19 D). The cornea is the primary refracting surface."}'),
  ('d4587350-1j','{"options": ["On the retina", "Behind the retina", "In front of the retina", "Multiple locations"], "correct": 2, "explanation": "In myopia, parallel rays focus in front of the retina with accommodation relaxed. This is because the eye is either too long or the refractive power is too strong for its axial length, causing nearsightedness."}'),
  ('f5c1c55c-23','{"options": ["1.336", "1.376", "1.386", "1.406"], "correct": 1, "explanation": "The cornea has an index of refraction of 1.376. This is higher than aqueous and vitreous (both 1.336) but lower than the lens cortex (1.386) and nucleus (1.406)."}'),
  ('9d99fdfc-1k','{"options": ["Absolute", "Facultative", "Latent", "Total"], "correct": 1, "explanation": "Facultative hyperopia is the amount that can be overcome by accommodation."}'),
  ('8578212e-13','{"options": ["38.00 D", "43.00 D", "50.00 D", "58.64 D"], "correct": 1, "explanation": "The average power of the cornea is 43.00 D."}'),
  ('c6143909-20','{"options": ["Muscles", "Glands", "Neurons (physiological connectors)", "Optic nerve"], "correct": 2, "explanation": "Neurons (physiological connectors) are strands of protoplasm that connect receptors to effectors, transmitting nerve impulses. Receptors receive stimuli, effectors respond (muscles contract, glands secrete), and neurons connect them."}'),
  ('74884bb8-1u','{"options": ["Low degree", "Medium degree", "High degree", "Component type"], "correct": 1, "explanation": "Medium degree myopia ranges from 3.00 to 6.00 D. Low degree is 0.25-3.00 D, and high degree is 6.00 D and above. This classification helps in clinical management."}'),
  ('d724950f-2j','{"options": ["8.00 D", "10.00 D", "12.50 D", "17.00 D"], "correct": 1, "explanation": "Using Hofstetter''s formula: Min AOA = 15 - 0.25(age) = 15 - 0.25(20) = 15 - 5 = 10.00 D. This represents the minimum expected amplitude of accommodation for a 20-year-old."}'),
  ('35d8bcf2-21','{"options": ["On the retina", "In front of the retina", "Behind the retina", "One on, one behind the retina"], "correct": 2, "explanation": "In compound hyperopic astigmatism, both principal meridians focus behind the retina with accommodation relaxed. The correction requires a convex sphere combined with a convex cylinder (+sphere +cylinder)."}'),
  ('c6bb0709-y','{"options": ["Study of sight and behaviour of light", "Science dealing with normal functions of living organisms", "Visual science studying eye structures and their functions as affected by light behaviour", "Study of electromagnetic light generation"], "correct": 2, "explanation": "Combines both physiology (structures/functions) and optics (light behaviour)"}'),
  ('58e6cb25-1d','{"options": ["Presence of organs", "Stimulus-response phenomenon", "Size and complexity", "Chemical composition"], "correct": 1, "explanation": "Living things can respond to environmental changes"}'),
  ('88c38992-14','{"options": ["Secrete", "Contract", "Dilate", "Absorb"], "correct": 1, "explanation": "Muscles are effectors that create movement"}'),
  ('a2526189-1x','{"options": ["Efferent limb", "Afferent limb", "Both limbs", "Neither limb"], "correct": 1, "explanation": "Afferent = sensory = incoming signals"}'),
  ('4389a596-14','{"options": ["Bipolar cells and ganglion cells", "Rods and cones", "Neurons and synapses", "Receptors and effectors"], "correct": 1, "explanation": "These are the light-sensitive cells"}'),
  ('9459a7ea-1n','{"options": ["2", "3", "4", "5"], "correct": 2, "explanation": "Length, corneal power, lens power, and anterior chamber depth"}'),
  ('18d59171-1f','{"options": ["1.336", "1.376", "1.386", "1.406"], "correct": 3, "explanation": "The lens nucleus has an index of refraction of 1.406."}'),
  ('102ad1c2-1o','{"options": ["6.0 mm", "6.8 mm", "7.7 mm", "10.0 mm"], "correct": 2, "explanation": "The front corneal surface has a radius of curvature of 7.7 mm."}'),
  ('f78823c8-1s','{"options": ["43.00 D", "19.11 D", "58.64 D", "62.00 D"], "correct": 2, "explanation": "Sum of cornea (43 D) and lens (19 D) powers, roughly"}'),
  ('b415d8c7-11','{"options": ["7.08 mm", "7.33 mm", "15.70 mm", "24.38 mm"], "correct": 0, "explanation": "The primary is slightly before the secondary nodal point"}'),
  ('b9b58984-25','{"options": ["Thomas Young", "Christopher Scheiner", "Helmholtz", "Donders"], "correct": 1, "explanation": "The name matches the device"}'),
  ('a0a09f6c-2b','{"options": ["Extraocular muscle", "Iris muscle", "Ciliary muscle", "Pupillary muscle"], "correct": 2, "explanation": "This muscle surrounds the lens and controls zonular fibres"}'),
  ('dd500816-1r','{"options": ["Zonular fibres become taut", "Lens becomes flatter", "Tension on zonular fibres is released", "Lens cannot change shape"], "correct": 2, "explanation": "Contraction releases tension, allowing lens to become more curved"}'),
  ('a7d2a189-2j','{"options": ["7.50 D", "9.50 D", "12.50 D", "15.00 D"], "correct": 1, "explanation": "Ave AOA = 18.5 - 0.30(age)"}'),
  ('9d65ba69-1s','{"options": ["Low degree", "Medium degree", "High degree", "Component type"], "correct": 0, "explanation": "The smallest range is low degree"}'),
  ('00c6d0c1-1a','{"options": ["30-40%", "50-60%", "70-80%", "80-90%"], "correct": 3, "explanation": "Most babies are born farsighted"}'),
  ('364f1e65-2b','{"options": ["In front of the retina", "Behind the retina", "At multiple points", "Cannot be determined"], "correct": 1, "explanation": "It''s hyperopic astigmatism"}'),
  ('1809101b-13','{"options": ["35 years", "40 years", "45 years", "50 years"], "correct": 2, "explanation": "Though it can vary from 40-50, this is the commonly acceptable age"}'),
  ('0ec7d4be-19','{"options": ["Corneal sclerosis", "Retinal degeneration", "Sclerosis of lens fibres and capsule", "Muscle weakness"], "correct": 2, "explanation": "It''s related to the lens losing flexibility"}'),
  ('ad1b17e0-1c','{"options": ["Aristotle", "Johannes Kepler", "Donders", "Scheiner"], "correct": 1, "explanation": "A famous astronomer and mathematician"}'),
  ('89f2270b-1o','{"options": ["3.00 D", "4.00 D", "5.00 D", "6.00 D"], "correct": 3, "explanation": "Component myopia is above this value"}'),
  ('e9cb4ec9-1g','{"options": ["Kastner", "Donders", "Helmholtz", "Kepler"], "correct": 0, "explanation": "Kastner first identified and described hyperopia in 1855."}'),
  ('99cbdebc-1p','{"options": ["Thomas Young", "George Biddle Airy", "John Green", "Donders"], "correct": 1, "explanation": "Also the British Astronomer Royal"}'),
  ('f36d355f-1p','{"options": ["Axis meridian", "Power meridian", "Primary meridian", "Refractive meridian"], "correct": 1, "explanation": "The axis has the least power, so this must be opposite"}'),
  ('430b5565-1o','{"options": ["2", "3", "4", "5"], "correct": 1, "explanation": "Longitudinal, radial, and circular"}'),
  ('eb209d7f-1a','{"options": ["Dilates", "Constricts", "Remains unchanged", "Fluctuates"], "correct": 1, "explanation": "Part of the near triad response"}'),
  ('100e2f7a-1j','{"options": ["0.5 mm", "3.6 mm", "7.2 mm", "10.0 mm"], "correct": 1, "explanation": "Roughly doubles from corneal thickness (0.5 mm)"}'),
  ('87eb302a-t','{"options": ["Early stage presbyopia", "Presbyopia before age 40", "Terminal status with minimal accommodation", "Reversible presbyopia"], "correct": 2, "explanation": "When accommodation is practically absent"}'),
  ('429d9bc7-o','{"options": ["Distance the eye can see clearly", "Extent image may be in front/behind retina and still appear sharp", "Range of accommodation", "Field of vision"], "correct": 1, "explanation": "Related to where the image can be positioned"}'),
  ('e11a061f-18','{"options": ["19.11 D", "43.00 D", "58.64 D", "62.00 D"], "correct": 0, "explanation": "The lens contributes 1/3 of total eye power"}'),
  ('293c5f25-15','{"options": ["0.5 mm", "3.6 mm", "6.8 mm", "7.2 mm"], "correct": 0, "explanation": "The thinnest measurement in the axial distances"}'),
  ('2909af62-49','{"options": ["Barium crown (1.701)", "Dense flint (1.616)", "Light barium crown (1.573)", "Ophthalmic crown (1.523)"], "correct": 0, "explanation": "Barium crown glass has an index of about 1.701, the highest among the standard ophthalmic glasses listed, and barium raises index without adding as much chromatic dispersion as lead. Crown is 1.523, dense flint about 1.616, light barium crown 1.573."}'),
  ('306bf083-4r','{"options": ["Extra dense flint", "Ophthalmic crown", "Dense flint", "Barium crown"], "correct": 1, "explanation": "Ophthalmic crown glass is about 70% silica (sand), 14 to 16% sodium oxide, 11 to 13% calcium oxide, with traces of potassium, borax, and antimony. It is the standard material for single-vision glass lenses and the distance portion of glass multifocals. Flint glasses are lead-based; barium crown is barium-based."}'),
  ('7aaee199-18','{"options": ["It is used mainly for the segment of certain fused bifocals because of its higher index", "It is a plastic, not a glass", "It has the highest Abbe value of all ophthalmic glasses", "It is the standard material for single-vision distance lenses"], "correct": 0, "explanation": "Flint glass (45 to 65% lead oxide) has a high index but low Abbe value (more dispersion), so it is used for the higher-index segment fused into some bifocals, not for the main single-vision lens. Its high dispersion is exactly why fused flint segments add chromatic aberration."}'),
  ('f9761d11-3b','{"options": ["Polycarbonate", "PMMA", "CR-39", "Trivex"], "correct": 1, "explanation": "PMMA (also called Perspex, Transpex, or Plexiglas) was the original plastic lens material, about half the weight of crown glass. CR-39 (allyl diglycol carbonate) is the later hard-resin plastic that is harder and more scratch-resistant. The two are frequently confused."}'),
  ('f7f95700-1v','{"options": ["Polycarbonate > high-index plastic > CR-39 > ordinary glass", "CR-39 > polycarbonate > glass > high-index plastic", "High-index plastic > polycarbonate > glass > CR-39", "Ordinary glass > CR-39 > high-index plastic > polycarbonate"], "correct": 0, "explanation": "Impact resistance runs polycarbonate > high-index plastic > CR-39 > toughened glass > ordinary glass. Polycarbonate is roughly ten times more impact resistant than glass, which is why it is preferred for children and sports."}'),
  ('310a1e46-1u','{"options": ["A 5/8-inch steel ball dropped from 50 inches", "A 1/2-inch ball dropped from 25 inches", "A 5/8-inch ball dropped from 100 inches", "A 1-inch ball dropped from 100 inches"], "correct": 0, "explanation": "The standard FDA drop-ball test drops a 5/8-inch steel ball onto the lens from a height of 50 inches. The lens must not fracture to pass."}'),
  ('6b487543-2w','{"options": ["Crown glass (2.54)", "Polycarbonate (1.20)", "CR-39 (1.32)", "Trivex (1.11)"], "correct": 3, "explanation": "Trivex has the lowest specific gravity (about 1.11), lighter than polycarbonate (1.20) and CR-39 (1.32), and far lighter than crown glass (2.54). Lower specific gravity means a lighter finished lens of the same volume."}'),
  ('6d6d69fb-24','{"options": ["Because denser (higher specific gravity) materials often have a higher index, allowing a thinner lens", "Because all materials have the same specific gravity when edged", "Because thicker lenses always weigh less", "Because specific gravity changes with tint"], "correct": 0, "explanation": "Specific gravity is weight per unit volume, but a denser material often has a higher refractive index, which lets the lens be made thinner. The reduced volume can offset the higher density, so the finished weights are closer than specific gravity alone suggests."}'),
  ('b16165a8-3e','{"options": ["Its high specific gravity", "Its high impact resistance", "Its low Abbe value (about 30)", "Its UV absorption"], "correct": 2, "explanation": "Polycarbonate''s chief optical drawback is its low Abbe value (about 30), meaning high dispersion and noticeable chromatic aberration (color fringing) in peripheral gaze. Abbe value is the reciprocal of dispersive power, so a low Abbe means more color spread."}'),
  ('07edd4e5-2j','{"options": ["Between 8 and 9", "Exactly 10", "Between 1 and 2", "Between 4 and 5"], "correct": 3, "explanation": "The Moh''s hardness scale is the oldest and most quoted scratch-resistance test. Most ophthalmic lens materials fall between 4 and 5 on it, which is why plastic lenses usually need a hard (scratch-resistant) coating."}'),
  ('99da0c03-28','{"options": ["Refractive index", "Chemical resistance", "Chromatic dispersion", "Impact resistance"], "correct": 1, "explanation": "The Thermodyne test measures chemical resistance by simulating prolonged atmospheric exposure using heat and humidity. It hints at a lens material''s life expectancy and its resistance to solvents."}'),
  ('56839681-1u','{"options": ["Glass never fogs because it is inorganic", "Neither material fogs", "Glass fogs more easily and demists slowly due to its thermal conductivity", "Plastic fogs more easily and demists slowly"], "correct": 2, "explanation": "Glass fogs easily and demists slowly because of its thermal conductivity, while plastic is slower to fog and quicker to demist. This is one practical advantage of plastic in humid or temperature-changing environments."}'),
  ('3bdb2f7b-2q','{"options": ["10.40%", "3.87%", "1.99%", "7.80%"], "correct": 1, "explanation": "R = 100(0.49/2.49)^2 = 100(0.1968)^2 = 3.87% per surface. This is why an uncoated CR-39 surface transmits about 96.13% (100 minus 3.87)."}'),
  ('df9d5bcb-2z','{"options": ["50%", "35%", "85%", "99%"], "correct": 0, "explanation": "By the lecture''s reference values, a mirror-coated surface transmits about 50% (it reflects roughly half the light), while an AR-coated surface transmits about 99%. Tints A/B/C transmit 85/65/35%."}'),
  ('c691c545-2h','{"options": ["96.13%", "92.40%", "88.60%", "99.00%"], "correct": 1, "explanation": "Transmission through elements in sequence multiplies: T_total = 0.9613 x 0.9613 = 0.9241, or 92.40%. Every surface, tint, and coating in the light path contributes its own factor."}'),
  ('d01cb2b3-36','{"options": ["99.00%", "96.13%", "92.40%", "95.17%"], "correct": 3, "explanation": "T_total = 0.99 x 0.9613 = 0.9517, or about 95.17%. The AR front raises the front-surface transmission from about 96% to 99%, while the uncoated back stays at 96.13%."}'),
  ('1a334c35-27','{"options": ["0.301", "0.700", "0.495", "0.194"], "correct": 0, "explanation": "OD = log10(1/0.50) = log10(2) = 0.301. Optical density is a logarithmic measure of light blocking, so denser (darker) filters add up in OD."}'),
  ('3c945e08-1n','{"options": ["Tint B (medium) at 65%", "All transmit equally", "Tint A (light) at 85%", "Tint C (dark) at 35%"], "correct": 3, "explanation": "Tint grades describe absorption through the lens material: Tint A (light) transmits 85%, Tint B (medium) 65%, and Tint C (dark) 35%. The darker the tint, the lower the transmission."}'),
  ('79135c47-2r','{"options": ["0.75", "4.0", "2.0", "0.25"], "correct": 1, "explanation": "Opacity = 1/T = 1/0.25 = 4.0. Opacity rises as transmission falls, describing how strongly a medium blocks light."}'),
  ('65857ac2-3q','{"options": ["65.0%", "50.0%", "31.1%", "95.7%"], "correct": 2, "explanation": "Multiply every element: 0.50 (mirror front) x 0.957 (uncoated back) x 0.65 (Tint B) = 0.311, about 31.1%. Adding any absorbing element always lowers the combined transmission."}'),
  ('f1934d5c-2f','{"options": ["Peripheral rays focus farther from the lens than paraxial rays", "Peripheral and paraxial rays focus at the same point", "Peripheral rays are not refracted at all", "Peripheral rays focus sooner (closer to the lens) than paraxial rays"], "correct": 3, "explanation": "In spherical aberration the peripheral rays are refracted more strongly and focus sooner (nearer the lens) than the paraxial rays, so a point images as a blur. Aspheric lens design is the standard correction."}'),
  ('bb7f07a7-38','{"options": ["Coma", "Chromatic aberration", "Curvature of field", "Distortion"], "correct": 0, "explanation": "Coma is essentially off-axis spherical aberration: oblique rays refracted by the lens periphery form a comet-shaped image of a point source. It is reduced by eliminating peripheral rays or adjusting lens shape."}'),
  ('743aa91b-2o','{"options": ["Marginal (radial) astigmatism; corrected with a corrected-curve meniscus lens", "Chromatism; corrected with an achromatic doublet", "Distortion; corrected with a prism", "Coma; corrected with a plano-convex lens"], "correct": 0, "explanation": "Oblique astigmatism, also called marginal or radial astigmatism, arises when a narrow beam enters obliquely and the refracted rays form the interval of Sturm. Best-form (corrected-curve) meniscus or aspheric lenses correct it, which is why modern lenses are curved."}'),
  ('5d6ab846-14','{"options": ["Exactly midway between the two focal lines", "At the optical center of the lens", "At the anterior focal line", "At the posterior focal line"], "correct": 0, "explanation": "The circle of least confusion is the smallest blur circle in the interval of Sturm, located exactly midway between the two (sagittal and tangential) focal lines."}'),
  ('b0eae9a1-21','{"options": ["Because the pupil blocks the curved rays", "Because the retina is a curved surface that compensates for the curved image", "Because spectacle lenses never produce it", "Because it only affects minus lenses"], "correct": 1, "explanation": "Curvature of field images a flat object on a curved (Petzval) surface concave toward the lens. The retina is itself curved, so it compensates, making this aberration a bigger issue for camera makers who need a flat image plane."}'),
  ('d618072e-3d','{"options": ["High plus power produces barrel distortion", "Distortion never occurs in plus lenses", "High plus power produces pincushion distortion", "High minus power produces pincushion distortion"], "correct": 2, "explanation": "High-power plus lenses produce pincushion distortion, while high-power minus lenses produce barrel distortion. Distortion changes image shape and lateral position but not clarity; a distortion-free lens is called orthoscopic."}'),
  ('5b08ad62-2v','{"options": ["All wavelengths refract equally", "Green waves only", "Short violet waves", "Long red waves"], "correct": 2, "explanation": "Short violet wavelengths are refracted most and long red wavelengths least, with intermediate hues in between. This unequal refraction is chromatic aberration (chromatism)."}'),
  ('eb7a83dd-2p','{"options": ["Achromatic doublet", "Corrected-curve meniscus", "Aspheric surface", "Limiting the aperture to paraxial rays"], "correct": 0, "explanation": "An achromatic doublet pairs two lenses so that each partially offsets the other''s chromatic aberration. Choosing a higher-Abbe material also helps. Aspheric surfaces, aperture limits, and corrected curves address monochromatic aberrations."}'),
  ('84709530-16','{"options": ["Only green is affected", "Different colors focus at different distances along the optical axis", "All colors focus in one plane but off the optical axis", "There is no color separation"], "correct": 1, "explanation": "Longitudinal (axial) chromatic aberration focuses different spectral hues at different distances along the optical axis. Lateral chromatic aberration instead places the colors in the same plane but off the axis."}'),
  ('e245862f-2e','{"options": ["Higher lens power produces greater chromatic aberration", "Lens power has no effect on chromatic aberration", "Only plano lenses show chromatic aberration", "Lower lens power produces greater chromatic aberration"], "correct": 0, "explanation": "The higher the lens power, the greater the chromatic aberration. This compounds the effect of a low Abbe material, so strong polycarbonate prescriptions show the most color fringing."}'),
  ('d67c3e2c-33','{"options": ["-8.00 D", "+20.00 D", "+6.00 D", "+8.00 D"], "correct": 3, "explanation": "Nominal power Dn = D1 + D2 = +14.00 + (-6.00) = +8.00 D. Nominal power simply adds the surface powers and ignores thickness, which is what a lens clock reads."}'),
  ('98138b4a-2o','{"options": ["+10.00 D", "+11.20 D", "+9.58 D", "+10.42 D"], "correct": 3, "explanation": "Deq = D1 + D2 - (t/n)(D1 x D2) = +10.00 - (0.0085/1.523)(-75) = +10.00 + 0.42 = +10.42 D. Equivalent power accounts for thickness and is the true thin-lens-equivalent power."}'),
  ('bb979aea-22','{"options": ["+8.00 D", "+8.08 D", "+8.72 D", "+9.00 D"], "correct": 2, "explanation": "BVP = D1 + D2 + (t/n)(D1)^2 = +8.00 + (0.008/1.6)(144) = +8.00 + 0.72 = +8.72 D. Back vertex power uses the front surface power squared and is the lensometer''s standard reading."}'),
  ('e37ba4c9-2e','{"options": ["+8.08 D", "+7.28 D", "+8.72 D", "+8.00 D"], "correct": 0, "explanation": "FVP = D1 + D2 + (t/n)(D2)^2 = +8.00 + (0.008/1.6)(16) = +8.00 + 0.08 = +8.08 D. Front vertex power uses the back surface power squared and is the neutralizing power measured with the convex side against the stop."}'),
  ('5fcb5f08-27','{"options": ["The convex (front) surface against the lens stop", "Either surface, since it does not matter", "The concave (back) surface against the lens stop", "The lens held away from the stop"], "correct": 0, "explanation": "Front vertex power is measured with the convex (front) surface against the lens stop. The default lensometer reading is back vertex power, taken with the concave (back) surface against the stop."}'),
  ('61506938-3h','{"options": ["-8.93 D", "-10.00 D", "-9.50 D", "-11.36 D"], "correct": 0, "explanation": "F_cl = F/(1 - dF) = -10.00/(1 - 0.012 x -10.00) = -10.00/1.12 = -8.93 D. A minus lens moved toward the eye (onto the cornea) becomes less minus, so the contact lens power is weaker than the spectacle power."}'),
  ('ca9f863d-2z','{"options": ["+10.00 D", "+8.93 D", "+11.36 D", "+9.00 D"], "correct": 2, "explanation": "F_cl = F/(1 - dF) = +10.00/(1 - 0.012 x 10.00) = +10.00/0.88 = +11.36 D. A plus lens moved toward the eye becomes more plus, so the contact lens power is stronger than the spectacle power."}'),
  ('3859b888-2k','{"options": ["Plus or minus 1.00 D", "Plus or minus 10 D", "Plus or minus 4 to 5 D", "Any power, always"], "correct": 2, "explanation": "Effective (vertex) power change is clinically significant for lenses stronger than about plus or minus 4 to 5 D. Below that the change with a few millimeters of vertex distance is negligible."}'),
  ('65b631ae-30','{"options": ["-1.24 D", "-3.00 D", "-2.30 D", "-0.76 D"], "correct": 0, "explanation": "The angle from the axis is a = 180 - 40 = 140 degrees. D = Fc x sin^2(140) = -3.00 x (0.643)^2 = -3.00 x 0.413 = -1.24 D. A cylinder has no power along its axis and full power 90 degrees away."}'),
  ('688bf150-2i','{"options": ["Full power", "One-half", "Three-fourths", "One-fourth"], "correct": 1, "explanation": "By the sin^2 rule, a cylinder shows one-fourth power at 30 degrees, one-half at 45 degrees, three-fourths at 60 degrees, and full power at 90 degrees from its axis."}'),
  ('4e9ed6a4-2q','{"options": ["+4.00 D", "+3.50 D", "+5.00 D", "+3.00 D"], "correct": 1, "explanation": "a = 70 - 130 = 60 degrees (magnitude). D = +5.00 + (-2.00)(sin^2 60) = +5.00 + (-2.00)(0.75) = +5.00 - 1.50 = +3.50 D."}'),
  ('9df0dcae-33','{"options": ["-8.80 D", "-8.08 D", "-8.00 D", "-7.92 D"], "correct": 1, "explanation": "S'' = -8.00[1 + sin^2(10)/3] = -8.00[1 + 0.0301/3] = -8.00(1.01) = -8.08 D. Tilting a lens always increases the magnitude of the sphere and induces cylinder along the tilt axis."}'),
  ('624eaab5-2c','{"options": ["0.1 mm", "1 mm", "0.5 mm", "2 mm"], "correct": 2, "explanation": "The rule of thumb is to lower the optical center 0.5 mm (half a millimeter) for each degree of pantoscopic tilt, keeping the visual axis near the optical center to limit induced astigmatism."}'),
  ('b268ae56-24','{"options": ["No meridian; it has no optical effect", "The 180 degree meridian", "The 45 degree meridian", "The 90 degree meridian"], "correct": 3, "explanation": "Face-form tilt induces power changes along the 90 degree meridian, whereas pantoscopic and retroscopic tilt act along the 180 degree meridian. This is why a face-form problem is first transposed to axis 90."}'),
  ('4e5e738e-3r','{"options": ["14 mm", "12 mm", "Equal to the spectacle vertex distance", "Zero"], "correct": 3, "explanation": "A contact lens sits on the cornea, so its vertex distance is zero. Spectacle lenses are normally set 12 to 14 mm from the corneal vertex to sit near the eye''s anterior nodal point."}'),
  ('e3563b9c-20','{"options": ["24 prism diopters", "0.24 prism diopters", "0.375 prism diopters", "2.4 prism diopters"], "correct": 3, "explanation": "Prentice''s rule: P = h(cm) x D = 0.3 cm x 8.00 = 2.4 prism diopters. Decentration must be converted to centimeters (3 mm = 0.3 cm) before multiplying by the lens power."}'),
  ('59eb1b4a-2x','{"options": ["0.4 mm outward", "4 mm outward (temporal)", "10 mm outward", "4 mm inward (nasal)"], "correct": 1, "explanation": "h = P/D = 2/5.00 = 0.4 cm = 4 mm. For a plus lens, decentering outward (temporal) gives base-out prism. A common trap is confusing centimeters with millimeters or reversing the base direction."}'),
  ('4e20ce29-13','{"options": ["The reading add and the distance from the segment top to its optical pole", "The frame PD and the vertex distance", "The distance prescription and the lens material", "The Abbe value and the tint"], "correct": 0, "explanation": "Image jump = h x D, where h is the distance from the segment top to the segment optical pole (in cm) and D is the add power. The distance prescription does not affect image jump."}'),
  ('a7293dd4-2s','{"options": ["3.50 prism diopters", "0.7 prism diopters", "1.75 prism diopters", "2.50 prism diopters"], "correct": 2, "explanation": "Image jump = h x D = 0.7 cm x 2.50 = 1.75 prism diopters. Flat-top segments have less image jump than round segments because their optical pole sits nearer the segment top."}'),
  ('853cc08f-1g','{"options": ["Ultex, because it is one-piece", "Executive, because its optical pole lies on the dividing line (h = 0)", "Flat-top, because it is fused", "Round Kryptok, because it is circular"], "correct": 1, "explanation": "The executive (monocentric) bifocal has its optical center on the dividing line, so h = 0 and image jump = 0. Its distance and near optical centers both sit on the segment line."}'),
  ('e5137776-1o','{"options": ["Ultex", "Flat-top (D-seg)", "Round Kryptok (22 mm)", "Executive"], "correct": 0, "explanation": "The Ultex has its optical pole about 19 to 20 mm below the segment top, giving the largest h and therefore the greatest image jump. Executive has zero, flat-top is small, and round Kryptok is intermediate."}'),
  ('e8a296ce-3e','{"options": ["5 prism diopters", "12 prism diopters", "7 prism diopters", "1 prism diopter"], "correct": 0, "explanation": "For perpendicular prisms the resultant magnitude is R = sqrt(H^2 + V^2) = sqrt(3^2 + 4^2) = sqrt(25) = 5 prism diopters. The base direction is found from the arctangent of vertical over horizontal."}'),
  ('9ba63488-2k','{"options": ["Ignoring it; it is within tolerance", "Switching to a larger frame", "Slab-off (bicentric grinding) or prism-segment lenses", "Dropping the distance optical center only"], "correct": 2, "explanation": "Imbalance under 1.5 prism diopters can be handled by dropping the distance optical center or using dissimilar segments. Above 1.5 prism diopters, slab-off (bicentric grinding) or prism in the segments is needed."}'),
  ('55b5c0b9-2f','{"options": ["Base-down prism, on the most-plus lens", "Base-in prism, on either lens", "Base-out prism, on the most-minus lens", "Base-up prism, on the most-minus (or least-plus) lens"], "correct": 3, "explanation": "Regular slab-off is bicentric grinding that creates base-up prism in the reading area and is applied to the lens with the most minus (or least plus) power on the 90 degree meridian. Reverse slab-off creates base-down prism and goes on the most-plus lens."}'),
  ('fa41f89c-2c','{"options": ["+2.40 D", "+1.00 D", "+3.40 D", "+2.20 D"], "correct": 3, "explanation": "Intermediate power = distance power + (1/2 x add) = +1.00 + 1.20 = +2.20 D. The intermediate zone is designed to cover the working distance between distance and near."}'),
  ('76447a18-29','{"options": ["A single fixed prism", "A prism plus a cylinder", "Two counter-rotating prisms whose bases oppose at the zero position", "A mirror and a prism"], "correct": 2, "explanation": "A Risley prism combines two counter-rotating prisms. At the zero position the bases oppose and cancel; as they rotate the resultant is 2 x delta x sin(theta), allowing a continuously variable prism."}'),
  ('e2bf8f84-2o','{"options": ["1.1 prism diopters", "3.3 prism diopters", "2.2 prism diopters", "0.33 prism diopters"], "correct": 1, "explanation": "Image jump = h x D = 1.1 cm x 3.00 = 3.3 prism diopters. The round segment''s optical pole is at its center, about 11 mm (its radius) below the top of a 22 mm segment."}'),
  ('4cb77183-1s','{"options": ["Benjamin Franklin, 1784", "Isaac Schnaitman, 1837", "Irvin Rips, 1955", "John Isaac Hawkins, 1826"], "correct": 0, "explanation": "Benjamin Franklin invented the bifocal in 1784 (the Franklin split bifocal). Hawkins introduced the trifocal in 1826; Schnaitman made the first one-piece (solid upcurve) bifocal in 1837; Rips made the blended bifocal in 1955."}'),
  ('b576ef81-v','{"options": ["Executive", "Perfection bifocal", "Kryptok", "Ultex"], "correct": 2, "explanation": "The Kryptok, introduced by John Borsch Jr. in 1908, was the first fused bifocal. The Ultex (O''Conner, 1910) and executive (American Optical, 1954) came later."}'),
  ('d3d1aec8-2d','{"options": ["John Borsch Jr. in 1908", "American Optical in 1954", "Zeiss in 1970", "Essilor of France in 1958 to 1959"], "correct": 3, "explanation": "Essilor of France introduced Varilux, the first progressive multifocal lens, in 1958 to 1959. It eliminated the visible segment line of bifocals."}'),
  ('bcb3ae40-1q','{"options": ["It has no vertical image jump because the optical centers lie at the dividing line", "Its segment never collects dust", "It has the highest add powers available", "It is the lightest bifocal made"], "correct": 0, "explanation": "The Franklin split bifocal holds two half-lenses edge to edge with their optical centers at the dividing line, so there is no vertical image jump. Its drawbacks are that the halves come apart and the dividing line reflects and collects dust."}'),
  ('ab315865-2l','{"options": ["Loss of the segment over time", "Poor scratch resistance", "Excess weight", "High chromatic aberration"], "correct": 3, "explanation": "The higher-index flint segment fused into the crown major lens has a low Abbe value, so it produces high chromatic aberration. An advantage is that the fused segment does not collect dirt, discolor, or chip."}'),
  ('46fc9069-2a','{"options": ["Cemented bifocal", "Progressive lens", "Fused bifocal", "One-piece (solid) bifocal"], "correct": 3, "explanation": "A visible ledge marks a solid one-piece bifocal. Cemented and fused bifocals show no ledge; the fused type instead shows a segment of denser, higher-index glass."}'),
  ('24e187f3-24','{"options": ["Cyanoacrylate", "Canada Balsam", "UV-curing cement", "Epoxy resin"], "correct": 1, "explanation": "Canada Balsam was the adhesive used to cement the small wafer segment to the major crown-glass lens. Its drawback was that temperature changes could loosen the wafer."}'),
  ('7bc34905-1j','{"options": ["7 mm bridge, 28 mm eye size", "7 mm add height, 28 D total power", "7 diopter intermediate, 28 diopter near", "7 mm segment depth and 28 mm near-segment width"], "correct": 3, "explanation": "In trifocal notation such as 7 x 28, the first number is the segment (intermediate) depth and the second is the diameter or width of the near segment. Common sizes include 7 x 28, 8 x 35, 10 x 35, and 14 x 35."}'),
  ('d3af0d3f-1y','{"options": ["18 to 19 mm", "13 to 14 mm", "10 to 11 mm", "25 mm"], "correct": 0, "explanation": "A lined trifocal needs a minimum segment height of about 18 to 19 mm so that both the intermediate and near zones fit usefully in the lens."}'),
  ('ac38a69c-2y','{"options": ["Double-D trifocal", "Rede-Rite (minus-add upcurve)", "Golfer''s bifocal", "Executive single-vision"], "correct": 0, "explanation": "The double-D trifocal (librarian lens) places flat-top segments at both the top and bottom, giving near or intermediate vision above and below distance. It suits librarians and pilots who view near objects overhead."}'),
  ('2b5bbd9c-1l','{"options": ["It has no near correction", "The distance segment sits on top and the main body of the lens is the near zone", "It has three segments", "The near zone is a small round segment low in the lens"], "correct": 1, "explanation": "The Rede-Rite (also called the minus-add upcurve or dental bifocal) puts the distance portion in a segment on top, with the main body of the lens being the near zone. It suits workers who view near objects above them."}'),
  ('4f141d08-3c','{"options": ["A full executive segment", "A progressive corridor", "A small round near segment low in the outer corner of one lens", "Two flat-top segments"], "correct": 2, "explanation": "The golfer''s bifocal places a small round near segment low in the outer corner of a single lens (the right lens for a right-handed golfer), keeping the rest of both lenses clear for distance play."}'),
  ('172c726a-22','{"options": ["Has two segments", "Uses conical curves (such as ellipsoids) to become flatter and thinner while reducing aberrations", "Is always made of glass", "Cannot correct astigmatism"], "correct": 1, "explanation": "Aspheric lenses use conical curves, notably ellipsoids, producing a flatter, thinner, lighter lens and reducing spherical aberration, oblique astigmatism, and distortion. They are commonly made in high-index plastic."}'),
  ('f8192bf4-1e','{"options": ["No unwanted astigmatism anywhere", "A wide corridor with gradual astigmatism and small clear zones", "Identical zones to a soft design", "Wide distance and near zones with a narrow corridor and rapid increase in unwanted astigmatism"], "correct": 3, "explanation": "Hard-design progressives give wide distance and near zones but a narrow, short intermediate corridor, with a rapid rise in unwanted peripheral astigmatism. Soft designs spread the astigmatism over a wider corridor at the cost of smaller clear zones."}'),
  ('bcdc4331-1t','{"options": ["The horizontal locators (about 34 mm apart), the lens logo, and the add power", "The pantoscopic angle", "The fitting cross and prism reference point", "The distance and near reference circles"], "correct": 0, "explanation": "Permanent micro-engravings are the two horizontal locators (about 34 mm apart), the manufacturer''s logo, and the add power. The fitting cross, reference circles, and prism reference point are temporary ink markings."}'),
  ('79a3eeb9-2u','{"options": ["Near reference circle", "Distance reference circle", "Prism reference point", "Fitting cross"], "correct": 3, "explanation": "The fitting cross is the ink-stamped point aligned directly in front of the pupil in primary gaze. The distance circle reads distance power, the near circle checks the add, and the prism reference point checks prism."}'),
  ('0beb40ec-21','{"options": ["Prism reference point", "Fitting cross", "Horizontal locator", "Distance reference circle"], "correct": 0, "explanation": "The prism reference point is the temporary marking used to verify the presence or amount of prism. The distance and near circles are for reading powers, and the fitting cross is for pupil alignment."}'),
  ('eb98d4a8-1t','{"options": ["Is the darkest available", "Blocks all blue light", "Transmits evenly across the visible spectrum, preserving true color perception", "Enhances contrast more than any other tint"], "correct": 2, "explanation": "Gray transmits evenly across the visible spectrum, so it reduces intensity without distorting color, giving true color perception. That neutrality makes it the most popular general-purpose protection tint."}'),
  ('8a7db0f3-39','{"options": ["Pink (rose)", "Yellow", "Green", "Gray"], "correct": 0, "explanation": "Pink (rose) is described as the color of choice when a neurological condition is present. It attenuates light pleasantly and absorbs in the UV and blue-light regions."}'),
  ('839539a0-31','{"options": ["Gray", "Green", "Blue", "Amber"], "correct": 3, "explanation": "Amber improves contrast and depth perception, brightening the darkness ahead while reducing glare from oncoming headlights, which suits night driving. Gray and green are neutral daytime tints."}'),
  ('7af68d0b-2a','{"options": ["Strongly blocks blue-green wavelengths, sharpening contrast and aiding hue discrimination", "Blocks only UV", "Adds no optical effect", "Eliminates all color perception"], "correct": 0, "explanation": "Red strongly blocks blue-green wavelengths, producing sharp contrast and improving depth perception in low light. This can aid hue discrimination in some color-deficient patients."}'),
  ('c183de60-19','{"options": ["Cobalt oxide", "Gold oxide", "Ferrous oxide", "Manganese oxide"], "correct": 2, "explanation": "Ferrous oxide tints glass green. Cobalt oxide gives blue, gold oxide gives red, and manganese oxide gives violet. Glass is tinted by adding these metal oxides during manufacture."}'),
  ('a386c188-20','{"options": ["Car glass reflects the lenses", "The cabin is too warm", "They only respond to infrared", "The windshield blocks the UV that triggers darkening"], "correct": 3, "explanation": "Photochromic darkening is triggered by UV, and a car windshield blocks most UV, so the lenses stay relatively clear inside a vehicle. They also darken more in cold and less in heat."}'),
  ('e4b1a554-26','{"options": ["Blocking all light equally", "Blocking vertically aligned light and passing horizontal light", "Darkening only in sunlight", "Blocking horizontally aligned light and passing vertical light"], "correct": 3, "explanation": "Reflection off a horizontal surface aligns light horizontally, creating glare. Polarized lenses block that horizontally aligned light while allowing vertically aligned light through, cutting glare while preserving useful vision."}'),
  ('d0b6e87f-2l','{"options": ["1 to 5%", "80 to 95%", "10 to 60%", "Exactly 50% always"], "correct": 2, "explanation": "Mirror coatings, applied by vacuum deposition of oxides or metals on the front surface, block about 10 to 60% of light transmission and also cosmetically shield the eyes. They suit bright, reflective settings like water and snow."}'),
  ('6cb6fadd-2m','{"options": ["Are more scratch resistant", "Are always tinted", "Reflect more light at each surface (higher index means higher reflectance)", "Absorb more UV"], "correct": 2, "explanation": "Reflectance rises with refractive index, so high-index lenses reflect more light at each surface. AR coatings use destructive interference to cut those reflections, sharpening vision and reducing distracting ghost images."}'),
  ('3ac44795-12','{"options": ["Adding a mirror layer", "Increasing the refractive index", "Heating the lens electrically", "Creating a hydrophilic surface or applying a surfactant film so water does not bead"], "correct": 3, "explanation": "Anti-fog coatings prevent water from condensing as tiny droplets by making the surface hydrophilic or by applying a surfactant film, so moisture spreads into a clear layer instead of scattering fog."}'),
  ('43aa1fd6-1y','{"options": ["Only children under 5", "Patients who never go outdoors", "Night-shift office workers only", "Skiers, mountaineers, astronomers, and pseudophakic patients"], "correct": 3, "explanation": "UV coatings suit those with high UV exposure or added risk, including skiers, mountaineers, and astronomers, and pseudophakic patients whose natural lens no longer filters UV. UV exposure contributes to cataract and macular degeneration."}'),
  ('24c4021b-22','{"options": ["Polycarbonate tint can be modified after the initial application, unlike glass", "Glass is tinted by dyeing", "Glass tint can be freely changed after dispensing", "CR-39 cannot be tinted at all"], "correct": 0, "explanation": "Polycarbonate tint can be modified after the initial application. Glass tint is permanent (a color change means new lenses), and CR-39 is dyed, so re-darkening an old tinted CR-39 lens can reveal scratches or ruin it."}'),
  ('31fa4854-1q','{"options": ["Regulation of circadian rhythm, alertness, and mood", "Digital eyestrain", "Immediate retinal burns", "Cataract formation"], "correct": 0, "explanation": "Beneficial blue light helps regulate the circadian rhythm, boosts alertness, and elevates mood. Excessive blue-light exposure, by contrast, is linked with digital eyestrain, which blue-light coatings aim to reduce."}'),
  ('3897e0e0-2s','{"options": ["An anti-reflective coating", "A thicker lens", "A mirror coating", "A darker tint"], "correct": 0, "explanation": "Anti-reflective coating increases transmittance and reduces surface reflection, cutting the glassy appearance and ghost images that are most noticeable on high-index lenses. It also helps night drivers and computer users."}'),
  ('43f7595b-2v','{"options": ["A prism only", "Plano", "Minus power in that meridian, neutralized with a minus trial lens", "Plus power in that meridian, neutralized with a plus trial lens"], "correct": 3, "explanation": "Against motion indicates plus power in that meridian, neutralized by adding a plus trial lens. With motion indicates minus power, neutralized with a minus lens. Neutralization is reached when there is no movement."}'),
  ('979efccc-2b','{"options": ["Equivalent power; only for toric lenses", "Back vertex power; when a lensometer is available", "Nominal power; for progressive lenses", "Front vertex power; when no lensometer is available, and better for low-power than toric lenses"], "correct": 3, "explanation": "Hand neutralization measures front vertex power and is used when a lensometer is unavailable. It works better for low-power spheres than for toric lenses, whose rotational motion complicates the reading."}'),
  ('63d33632-44','{"options": ["Use the lens clock only on the back surface", "Ignore the difference", "Double the reading", "Apply the true-and-marked-power correction T = [(n - 1)/0.530] x D"], "correct": 3, "explanation": "The Geneva lens clock is calibrated for index 1.530. For other materials, true power T = [(n - 1)/0.530] x D corrects the marked (clock) reading to the actual power for that material."}'),
  ('bd03a8ef-3c','{"options": ["A plano lens", "A progressive lens", "A cylindrical (toric) lens", "A prism"], "correct": 2, "explanation": "In the lensometer mires, a circle of dots corresponds to a spherical lens, while two perpendicular sets of lines indicate a cylindrical (toric) lens. The cylinder power is the difference between the two meridian readings."}'),
  ('d017d063-1q','{"options": ["Measuring the patient''s interpupillary distance", "Locating the optical center", "Neutralizing an unknown prescription", "Measuring prism amount"], "correct": 0, "explanation": "The lensometer neutralizes, verifies, and duplicates prescriptions, locates the optical center, and measures prism. It does not measure the patient''s interpupillary distance, which is taken with a PD rule or pupillometer."}'),
  ('96d0fb2d-1c','{"options": ["The vertical depth of the lens", "The bridge width", "The distance between optical centers", "The horizontal eye size, between the vertical sides of the box"], "correct": 3, "explanation": "The ''A'' measurement is the horizontal distance between the furthest temporal and nasal edges of the lens (the vertical sides of the box), commonly called the eye size. The ''B'' measurement is the vertical depth."}'),
  ('3801745b-1z','{"options": ["Frame PD", "Segment height", "Effective diameter", "Bridge size"], "correct": 3, "explanation": "The DBL is the shortest distance between the nasal edges of the two lenses and corresponds to the bridge size. The frame PD is the DBC (distance between centers), which equals A plus DBL."}'),
  ('d083ef06-2c','{"options": ["DBC = A x DBL", "DBC = A - DBL", "DBC = A + DBL", "DBC = DBL - A"], "correct": 2, "explanation": "In theory the distance between centers (frame PD) equals the eye size plus the bridge: DBC = A + DBL. The practical measured value can differ slightly from this calculation."}'),
  ('9322b400-1n','{"options": ["Measure vertex distance", "Determine the add power", "Select the minimum blank size that will cut out for the frame", "Set the tint density"], "correct": 2, "explanation": "The effective diameter is twice the distance from the geometric center to the furthest edge of the lens shape. Combined with the decentration, it is used to choose the smallest lens blank that will cut out for a given frame."}'),
  ('d5485b45-30','{"options": ["2 mm above the geometric center", "At the nasal edge", "5 mm below the geometric center", "At the geometric center"], "correct": 0, "explanation": "The mechanical center is placed about 2 mm above the geometric center; the lens is cut and edged around this point to account for the typical position of the eye in the frame."}'),
  ('9527f95b-2c','{"options": ["The hinges", "The bridge", "The temples", "The end pieces"], "correct": 1, "explanation": "The bridge, the arched part resting on the nose, supports about 90% of the frame''s weight and largely determines the fit. A saddle bridge spreads that weight for heavy frames or pressure-sensitive patients."}'),
  ('2090efba-2t','{"options": ["Double bridge", "Saddle bridge", "No bridge", "Keyhole bridge"], "correct": 1, "explanation": "A saddle bridge spreads the weight across the sides and top of the nose, making it comfortable for heavy glasses or pressure-sensitive patients. A keyhole bridge instead rests on the sides of the upper nose for small or flat bridges."}'),
  ('09c03221-1o','{"options": ["Patients with very large heads", "Children and sports participants who need the frame to stay on", "Adults wanting easy on-and-off reading glasses", "Patients needing the lightest possible temple"], "correct": 1, "explanation": "Comfort-cable temples wrap behind the ear with a flexible metal cable, holding the frame securely, which suits children and sports use. Library (paddle) temples are the straight, easy on-and-off style for reading glasses."}'),
  ('9ae7f890-2m','{"options": ["1948", "1908", "1984", "1962"], "correct": 3, "explanation": "The boxing system was adopted in 1962. It draws an imaginary box around each lens shape and uses the box sides as the reference points for all standard frame and lens measurements."}'),
  ('078e1b64-3c','{"options": ["The front (convex) surface", "The back (concave) surface", "The edge", "Either surface"], "correct": 0, "explanation": "Centering marks the optical center, cylinder axis, and base-apex line on the front surface of the lens, using a centering device or lensometer. Keeping all marks on the front surface keeps the layout consistent."}'),
  ('519b9bf9-u','{"options": ["Applying an anti-reflective coating", "Grinding the surface curves", "Drilling holes for a rimless mount", "Placing the finished lens into the channeled eye wire"], "correct": 3, "explanation": "Glazing (insertion) is placing the lens into the channeled eye wire. Mounting refers to seating the lens in a full-rim frame, and drilling is boring holes for rimless or three-piece mountings."}'),
  ('ca9ca2f6-44','{"options": ["Round (Kryptok) segment", "Double-D segment", "Flat-top (D) segment", "Executive segment"], "correct": 0, "explanation": "The round Kryptok segment is the least visible cosmetically, but its optical pole sits about 11 mm below the top, giving more image jump, and the circular shape is often too narrow for comfortable reading."}'),
  ('7f951cc5-4h','{"options": ["Executive lens", "Aspheric lens", "Spherical/toroidal lens", "Lenticular lens"], "correct": 2, "explanation": "The spherical and toroidal single-vision lenses are the most common design: a meniscus or toric form with a spherical positive front and a spherical or toroidal negative back, available in most materials. Aspheric lenses instead use conical curves."}'),
  ('19c2f144-3f','{"options": ["High-index lenses have a higher Abbe value", "Higher refractive index increases surface reflectance", "High-index materials absorb more UV", "High-index lenses are always thicker"], "correct": 1, "explanation": "Reflectance rises with refractive index (R = 100(n-1)^2/(n+1)^2), so higher-index lenses reflect more light per surface and look more reflective. This is exactly why AR coating is strongly recommended for high-index lenses."}'),
  ('cf0bf592-47','{"options": ["19 mm", "7 mm", "11 mm", "28 mm"], "correct": 0, "explanation": "The Ultex is a one-piece crown-glass bifocal ground with a roughly 38 mm central disk; after the blank is cut in two, each lens has a segment height of about 19 mm. Its large segment gives a wide reading field but the greatest image jump."}'),
  ('c3d98749-28','{"options": ["Its optical centers are far from the segment line", "It creates image jump", "It is thick, heavy, and its crevice collects dirt", "It has a narrow reading field"], "correct": 2, "explanation": "The executive segment gives the widest near field and zero image jump, but it is thick and heavy, cosmetically obvious, and its deep cleft collects dirt while the segment edge can chip. Its optical centers sit on the dividing line."}'),
  ('d6ac0ef9-1p','{"options": ["Wants a wider, more gradual intermediate corridor and better adaptation, accepting smaller clear zones", "Needs a lined segment", "Needs the widest possible distance and near zones and accepts a narrow corridor", "Cannot tolerate any peripheral blur at all"], "correct": 0, "explanation": "Soft-design progressives use a wider, longer corridor with a more gradual increase in unwanted astigmatism, which aids adaptation, at the cost of smaller clear distance and near zones. Hard designs do the opposite."}'),
  ('78697d47-3g','{"options": ["A flint fused segment", "A round segment whose edge is blended so no line is visible", "A visible ledge at the segment", "Two separate lens pieces"], "correct": 1, "explanation": "The blended bifocal blends the round segment edge so the dividing line is cosmetically invisible, at the cost of a blurred blend zone. Rips introduced it in 1955; it is also called the invisible, seamless, or Younger bifocal."}'),
  ('bf5b98d0-54','{"options": ["Aspheric surface", "Corrected-curve meniscus", "Plano-convex lens", "Achromatic doublet"], "correct": 3, "explanation": "The complaint is chromatic aberration, which worsens with higher power and lower Abbe value. The achromatic doublet pairs two lenses so their chromatic aberrations cancel; switching to a higher-Abbe material also reduces it."}'),
  ('9fa58745-2i','{"options": ["Cameras use plastic lenses", "Film (or a sensor) is flat while the retina is curved and compensates", "Spectacle lenses are always aspheric", "Curvature of field does not exist in cameras"], "correct": 1, "explanation": "Curvature of field forms the image on a curved Petzval surface. The curved retina compensates in spectacle wear, but a camera''s flat film or sensor cannot, so instrument makers must correct it carefully."}'),
  ('034c3c83-1f','{"options": ["Free from chromatic aberration", "Free from reflection", "Free from scratches", "Free from distortion"], "correct": 3, "explanation": "Orthoscopic means free from distortion, so straight lines image as straight lines. Distortion affects image shape and lateral position but not clarity, and is most evident in high-power plus and minus lenses."}'),
  ('6e83ca6b-4h','{"options": ["Dropping the distance optical center", "A larger frame", "Reverse slab-off molded on the convex side of the most-plus lens", "Regular slab-off on the most-minus lens"], "correct": 2, "explanation": "Because the imbalance exceeds 1.5 prism diopters, slab-off is indicated. Reverse slab-off is molded on the convex side of a plastic lens, creating base-down prism, and is applied to the lens with the most plus (or least minus) power on the 90 degree meridian."}'),
  ('c3c42a4b-24','{"options": ["Taking the difference between the two perpendicular meridian readings", "Adding the two meridian readings", "Reading a single meridian only", "Reading the circle of dots"], "correct": 0, "explanation": "For a toric lens, you focus the perpendicular line targets at one meridian, rotate 90 degrees to the second, and the cylinder power is the difference between the two sphere readings. A circle of dots indicates a pure sphere."}'),
  ('e9f456b2-3z','{"options": ["Randomly varied", "Steeper than the central curvature", "Flatter than the central curvature (aplanatic principle)", "Identical to the central curvature"], "correct": 2, "explanation": "Aspheric (aplanatic) surfaces flatten the peripheral curvature relative to the center so peripheral rays are not over-refracted, controlling spherical aberration while also making the lens thinner and flatter."}'),
  ('adce1175-3d','{"options": ["Corlon (C-Lite)", "Barium crown", "Trivex", "PMMA"], "correct": 0, "explanation": "Corlon (C-Lite) bonds a glass front to a plastic back, giving roughly 25% reduction in both thickness and weight compared with an all-glass lens, combining the scratch resistance of glass with reduced weight."}'),
  ('c6afee98-34','{"options": ["Add base-down prism", "Increase pantoscopic effect", "Clear the lower rim from a protruding cheek", "Lower the optical center"], "correct": 2, "explanation": "Retroscopic tilt angles the bottom rim away from the face, generally to keep the lower rim off a protruding cheek. Like pantoscopic tilt it acts along the 180 degree meridian."}'),
  ('23314be5-19','{"options": ["Temple length", "Bridge width", "Horizontal eye size", "Vertical distance between the top and bottom edges of the lens shape"], "correct": 3, "explanation": "The ''B'' measurement is the vertical distance between the furthest top and bottom edges of the lens shape, that is, between the horizontal sides of the box. The ''A'' measurement is the horizontal eye size."}'),
  ('3cfbead3-1y','{"options": ["Top of the box to the optical center", "Bottom of the box to the segment top", "Nasal edge to the segment", "Datum line to the segment top"], "correct": 3, "explanation": "Seg drop is the vertical distance from the datum line (horizontal midline) to the top of the segment, whereas seg height is measured from the bottom edge of the box to the segment top."}'),
  ('46a085a5-46','{"options": ["Minus power", "Prism only", "No power", "Plus power"], "correct": 3, "explanation": "Against motion signals plus power in that meridian, so it is neutralized with a plus trial lens. Observing the horizontal limb while moving the lens vertically isolates that meridian''s power."}'),
  ('172aa6c5-2x','{"options": ["Scratch-resistant (hard) coating", "Mirror coating", "Anti-fog coating", "Photochromic treatment"], "correct": 0, "explanation": "Plastic lenses have low scratch resistance (Moh''s 4 to 5), so a scratch-resistant hard coating is recommended to protect the surface. Glass is inherently more scratch resistant and does not always require it."}'),
  ('125004ed-2f','{"options": ["A night driver who keeps lenses clean", "A patient with high-index lenses", "A computer user", "A patient wearing polycarbonate expecting strong photochromic activation, since PC already blocks UV"], "correct": 3, "explanation": "On polycarbonate, which already blocks UV, an accompanying photochromic may not activate well, so AR is a poor pairing there. AR otherwise benefits computer users, high-index wearers, and night drivers who keep the coating clean."}'),
  ('9d18cc0e-1t','{"options": ["Nasal edge of each lens", "Horizontal line through the vertical center of the frame", "Vertical center line of the frame", "Top of the segment"], "correct": 1, "explanation": "The datum line is the horizontal line running through the vertical center of the frame. Its intersection with the horizontal center of each lens defines the geometric (box) center."}'),
  ('94b4f4bb-1y','{"options": ["Liquid crystal alignment", "Electrochromic voltage", "Organic dye molecules that open and close", "Silver halide (silver chloride) crystals reacting to UV"], "correct": 3, "explanation": "Glass photochromics rely on silver halide (silver chloride) crystals that react to UV and darken, then clear when UV is removed. Plastic photochromics instead use organic dye molecules that change structure. The reaction is reversible and repeatable."}'),
  ('dacc4c24-42','{"options": ["99.00%", "96.13%", "95.70%", "94.81%"], "correct": 3, "explanation": "Polycarbonate (n = 1.59) reflects about 5.19% per surface, giving a per-surface transmission near 94.81%, lower than CR-39 (96.13%) and crown glass (95.70%) because higher index reflects more."}'),
  ('8e6c8591-2e','{"options": ["Perkins handheld tonometer", "Schiotz tonometer", "Goldmann tonometer", "Biomicroscope"], "correct": 1, "explanation": "The Schiotz tonometer uses the INDENTATION principle — a weighted plunger indents the cornea. Goldmann uses APPLANATION (flattening). Perkins is also applanation."}'),
  ('5f7b6186-2l','{"options": ["Brock string", "Panum''s area", "Visual fields", "Visuoscope"], "correct": 3, "explanation": "The Visuoscope (fixation ophthalmoscope) directly maps fixation behavior on the retina, allowing the examiner to determine whether the patient uses centric or eccentric fixation."}'),
  ('53994efe-24','{"options": ["Amblyopia", "Suppression", "Diplopia", "Centric fixation"], "correct": 3, "explanation": "Orthoptic treatment aims to ACHIEVE centric fixation — it is not needed when centric fixation is already present. Amblyopia, suppression, and diplopia are all indications for orthoptic treatment."}'),
  ('ba76da84-38','{"options": ["Visual field test", "Shadow test", "Goldmann three-mirror test", "Gonioscopy"], "correct": 3, "explanation": "Gonioscopy directly visualizes the drainage angle to determine if glaucoma is open-angle or closed-angle — a critical distinction for diagnosis and management."}'),
  ('618d5283-33','{"options": ["0.00 D", "2.50 D", "0.17 D", "1.00 D"], "correct": 0, "explanation": "At 6 meters (optical infinity for clinical purposes), vergence = 0. An emmetropic eye is relaxed with no accommodation needed. Equivalent power = 1/6 = 0.17 D, but clinically = 0.00 D."}'),
  ('26f69460-3n','{"options": ["Diabetes mellitus", "Heart disease", "Glaucoma", "Hypertension"], "correct": 2, "explanation": "Glaucoma is itself an ocular disease — it is not a systemic condition asked about as a cause. Diabetes, heart disease, and hypertension are systemic conditions that can threaten sight and are asked about in the history."}'),
  ('f1057b58-2q','{"options": ["Small amount of accommodative convergence", "Small amount of accommodation", "Use of negative fusional vergence", "Small amount of positive fusional vergence"], "correct": 2, "explanation": "An uncorrected myope''s near point is within their far point — they do NOT need to diverge (negative fusional vergence) to read near targets. They still use accommodation, accommodative convergence, and positive fusional vergence."}'),
  ('0bc47e74-32','{"options": ["43.00 D to 44.00 D", "46.00 D to 49.00 D", "40.00 D to 42.00 D", "36.00 D to 39.00 D"], "correct": 0, "explanation": "The cornea averages 43–44 D of refractive power (Gullstrand''s schematic eye: 43.05 D). Total eye power is ~58.64 D; cornea = ~2/3 of that."}'),
  ('28338cc6-39','{"options": ["Against-the-rule astigmatism", "Irregular astigmatism", "Oblique astigmatism", "With-the-rule astigmatism"], "correct": 0, "explanation": "With aging, the vertical meridian flattens (decreasing WTR) and the horizontal meridian becomes relatively steeper, resulting in a shift toward against-the-rule (ATR) astigmatism."}'),
  ('a2838f74-43','{"options": ["5X", "2X", "3X", "4X"], "correct": 3, "explanation": "Magnification needed = 200/50 = 4×. The telescope magnifies the image 4 times so the patient can resolve detail equivalent to 20/50."}'),
  ('27c33513-31','{"options": ["Esotropia", "Exotropia", "Hyperopia", "Exophoria"], "correct": 0, "explanation": "Prominent epicanthal folds cover the medial sclera and create the appearance of esotropia (pseudoesotropia). The eyes are actually straight — it is a common cause of false esotropia referral in children."}'),
  ('883dfb17-46','{"options": ["180 degrees", "30 degrees", "90 degrees", "60 degrees"], "correct": 0, "explanation": "The 9 o''clock spoke on a fan dial is horizontal (180° orientation). The clearest line under fog indicates the axis of the MINUS cylinder. 9 o''clock = horizontal = axis 180°."}'),
  ('58be971a-2b','{"options": ["Base-down prism", "Base-out prism", "Contact lenses", "Base-up prism"], "correct": 1, "explanation": "For esotropia (inward manifest deviation), base-out (BO) prism displaces the image temporally, reducing the convergence demand and allowing the deviated eye to straighten and achieve fusion."}'),
  ('446027c2-1f','{"options": ["2 to 4 weeks", "Birth", "2 to 3 months", "6 months"], "correct": 2, "explanation": "Fixation (the ability to hold steady foveal regard on a target) develops at approximately 2–3 months of age. At birth, infants can track briefly but fixation is not well-established."}'),
  ('7585748e-5c','{"options": ["Perkins tonometer", "Pulse air tonometry", "Goldmann tonometer", "Digital tonometry"], "correct": 2, "explanation": "The Goldmann applanation tonometer uses a biprism that splits the fluorescein ring into two semicircles. When the inner margins touch, the applanated area = 3.06mm diameter, and IOP is read from the dial."}'),
  ('705f8468-3g','{"options": ["0.50 to 1.00 D of hyperopia", "4.00 to 8.00 D of hyperopia", "2.00 to 6.00 D of hyperopia", "6.00 to 10.00 D of hyperopia"], "correct": 2, "explanation": "By age 6, most children retain 2.00–6.00 D of hyperopia after emmetropization. This range is considered within physiologic norms for school-age children."}'),
  ('cbddde3f-3s','{"options": ["10.00 to 20.00 D of hyperopia", "0.25 to 6.00 D of hyperopia", "10.00 to 20.00 D of myopia", "0.25 to 6.00 D of myopia"], "correct": 1, "explanation": "Premature infants with mature fundi (and birth weight > 1,700g) typically show low-to-moderate hyperopia (0.25–6.00 D). High myopia is more characteristic of premature infants with retinopathy of prematurity (ROP)."}'),
  ('a0329dbf-3l','{"options": ["Weak accommodative facility", "Strong accommodative facility", "Normal accommodative facility", "Adequate accommodative facility"], "correct": 2, "explanation": "Normal accommodative facility for adults = 8–12 cycles per minute with ±2.00 D flippers. 8–10 cpm falls within the normal range, indicating normal accommodative flexibility."}'),
  ('087e8f82-40','{"options": ["25", "8", "16", "45"], "correct": 3, "explanation": "Convergence at NPC = PD(cm)/NPC(m) = 6 cm / 0.125 m = 48 △. Subtract exophoria (divergent tendency at distance reduces convergence demand): 48 − 3 = 45 △."}'),
  ('01f5087e-4c','{"options": ["Steep", "Loose", "Tight", "Flat"], "correct": 0, "explanation": "OS has a steep meridian of 47.75 D at 180° — the horizontal meridian is steeper (higher diopters) than OD''s 46.75 D at 180°. Higher diopter value = steeper curvature. OS is classified as a steep cornea relative to OD."}'),
  ('fe586fef-21','{"options": ["Convergence insufficiency", "Convergence excess", "Divergence excess", "Accommodative insufficiency"], "correct": 0, "explanation": "Normal NPC = 6–10 cm. NPC > 12 cm means the patient cannot converge normally to a close target — this is the hallmark of convergence insufficiency."}'),
  ('75382c89-1l','{"options": ["Concave sphere with convex cylinder lens", "Concave sphere with concave cylinder", "Convex sphere with concave cylinder lens", "Convex sphere with convex cylinder lens"], "correct": 1, "explanation": "Compound myopic astigmatism = both focal lines in FRONT of the retina. Correction requires a CONCAVE (minus) sphere + CONCAVE (minus) cylinder to push both focal lines back to the retina."}'),
  ('1d7277d3-2u','{"options": ["15 prism diopters", "20 prism diopters", "10 prism diopters", "5 prism diopters"], "correct": 0, "explanation": "Convergence at 40 cm (0.40 m) with standard PD of 60 mm (6 cm): = PD(cm) / distance(m) = 6 / 0.40 = 15 prism diopters."}'),
  ('90263339-3l','{"options": ["70", "55", "63", "47"], "correct": 1, "explanation": "Presbyopia progresses from age 40 onward and typically stabilizes at approximately age 55–60 when the crystalline lens has lost virtually all elasticity. The add power plateaus around +2.50 to +3.00 D."}'),
  ('58df1a4f-1y','{"options": ["Crystalline lens", "Vitreous humor", "Aqueous humor", "Cornea"], "correct": 3, "explanation": "The cornea is the most powerful refracting surface in the eye at ~43 D (2/3 of total eye power). The crystalline lens adds ~19 D (1/3), but cornea has greater total power due to the large air-cornea refractive index difference."}'),
  ('0f793dfb-2o','{"options": ["Compound myopic astigmatism", "Compound hyperopic astigmatism", "Simple myopic astigmatism", "Mixed astigmatism"], "correct": 3, "explanation": "+3.00 DS − 6.00 DC × 175: one meridian = +3.00 D (hyperopic), other = +3.00 − 6.00 = −3.00 D (myopic). One focal line in front, one behind the retina = MIXED astigmatism."}'),
  ('7a3ae5bf-2s','{"options": ["About 1.00 or 1.25 D per year", "About 0.75 or 1.00 D per year", "About 0.40 or 0.50 D per year", "About 1.00 or 1.50 D per year"], "correct": 2, "explanation": "Myopia typically progresses at approximately 0.40–0.50 D per year during school age (6–16 years). This is the most evidence-based figure from population studies."}'),
  ('497c2b22-28','{"options": ["Magnify the retinal image size", "Create spherical aberration", "Minify the retinal image size", "Cause distorted image"], "correct": 0, "explanation": "Moving a plus lens away from the eye (past the anterior focal point) increases the spectacle magnification. The image size on the retina increases — clinically important in aphakia correction with spectacles."}'),
  ('5acdd22a-1o','{"options": ["Plus lens and BI prism", "Minus lens and BI prism", "Plus lens and BO prism", "Minus lens and BO prism"], "correct": 1, "explanation": "Exotropia = eyes turn OUT. Management: minus lenses stimulate accommodation and AC/A ratio to drive convergence. BI (base-in) prism relieves divergence demand. Combination = minus lens + BI prism."}'),
  ('d9318a75-46','{"options": ["180 degrees", "30 degrees", "90 degrees", "60 degrees"], "correct": 2, "explanation": "3 o''clock on a clock dial corresponds to the 90° orientation (vertical spoke). The clearest line under fog = axis of minus cylinder. 3 o''clock = 3 × 30° = 90° axis."}'),
  ('2ee8387e-1x','{"options": ["6 to 8 weeks", "2 to 5 months", "Birth", "15 to 30 days"], "correct": 1, "explanation": "The visual menace (threat) response develops at approximately 2–5 months of age as the visual cortex matures. It is NOT present at birth. Full blink-to-threat is usually established by 3–4 months."}'),
  ('54520d33-1d','{"options": ["Point of neutrality", "Working distance power", "Maximum plus to relax", "Plane conjugate to retina"], "correct": 3, "explanation": "Autorefractors use the optometer principle — the measurement target is placed conjugate to the retina. When the patient''s far point coincides with the target, the reflex is neutral and the refractive error is determined."}'),
  ('1cdd0cb5-4e','{"options": ["Absolute hyperopia", "Latent hyperopia", "Facultative hyperopia", "Total hyperopia"], "correct": 0, "explanation": "Absolute hyperopia is the portion that CANNOT be overcome by any amount of accommodation. Vision remains subnormal without correction. It represents the most advanced/severe component of hyperopia."}'),
  ('96d47ac1-2v','{"options": ["Hyperopia", "Myopia", "Astigmatism", "Presbyopia"], "correct": 1, "explanation": "A deeper anterior chamber means the crystalline lens is set further back, reducing the effective converging power. This leads to a relatively longer optical path, resulting in myopia."}'),
  ('98fe7d19-32','{"options": ["Stenopaic slit", "Prism dissociation", "Robinson Cohen", "Paraboline test"], "correct": 1, "explanation": "Prism dissociation (Humphriss immediate contrast method) is a binocular balancing technique for spherical balance — it is NOT used to determine the cylindrical component of the correction."}'),
  ('61aba929-3w','{"options": ["16.00 D", "4.10 D", "20.00 D", "6.60 D"], "correct": 0, "explanation": "AA = 1/PP − 1/PR = (100/5) − (100/20) = 20 − 5 = 15 D. With vertex correction (+1.2cm), near point from cornea ≈ 6.2cm → 100/6.2 ≈ 16.1 D. Clinically rounded to 16.00 D."}'),
  ('94f1eed1-2n','{"options": ["Ill-sustained accommodation", "Divergence excess", "Convergence excess", "Accommodative excess"], "correct": 2, "explanation": "Normal NPC = 6–10 cm. NPC < 5 cm (e.g., 3 cm) means the patient converges TOO strongly — indicating convergence excess. This is associated with esophoria at near and symptomatic near headaches."}'),
  ('432dc7f2-2k','{"options": ["Divergence excess", "Convergence excess", "Divergence insufficiency", "Convergence insufficiency"], "correct": 1, "explanation": "NPC < 5 cm = excessive convergence = convergence excess. The patient converges too strongly, characteristic of esophoria at near, sometimes with associated accommodative excess."}'),
  ('81f7244a-38','{"options": ["Prism dissociation", "Duochrome test", "Maddox Rod", "Bichrome test"], "correct": 2, "explanation": "The Maddox Rod is used to measure phorias (dissociated binocular testing) — NOT for determining the spherical endpoint of refraction. Duochrome (bichrome), prism dissociation, and polarized fogging are all used for spherical balance."}'),
  ('18de88d5-3e','{"options": ["Diabetic retinopathy", "Glaucoma", "Traumatic injury", "Age-related maculopathy"], "correct": 2, "explanation": "Traumatic injury is NOT a leading cause of blindness in the ELDERLY. The top causes in the aging population are: AMD, diabetic retinopathy, glaucoma, and cataract. Trauma predominantly affects younger patients."}'),
  ('e3aaaa4e-2c','{"options": ["Patient demographics", "Chief complaints", "Medical history", "Ocular history"], "correct": 2, "explanation": "Hypertension and diabetes are SYSTEMIC conditions asked about under the MEDICAL HISTORY section of the case history. Ocular history covers previous eye conditions and surgeries."}'),
  ('221ce8a1-2i','{"options": ["−0.50 cyl × 90", "−0.50 D sphere", "−0.50 cyl × 180", "−1.00 D sphere"], "correct": 3, "explanation": "−1.00 D sphere is the most commonly cited threshold for significant myopia requiring correction. A −0.50 cyl × 90 (WTR) might be significant for some patients, but −1.00 D sphere is the standard clinical cutoff."}'),
  ('d389d34c-1s','{"options": ["Crystalline lens provides 1/3 power of the eye", "Crystalline lens is situated 3.6 mm behind the cornea", "Complete power of the eye is 45.00 D", "Cornea contributes 2/3 of refracting power"], "correct": 2, "explanation": "The complete (total) power of the eye is approximately 58.64 D (Gullstrand), NOT 45.00 D. All other statements are correct: lens = 1/3, lens at ~3.6 mm behind cornea, cornea = 2/3."}'),
  ('bfa42bf4-1u','{"options": ["Duction tests", "Maddox Double Prism", "Maddox Wing", "Phoria test"], "correct": 1, "explanation": "Cyclophoria (torsional deviation) is measured with the double Maddox Rod test or Maddox Double Prism test. One red and one white Maddox Rod are used before each eye; a tilted line indicates cyclophoria."}'),
  ('7da13120-27','{"options": ["Increase accommodative convergence", "Reduce the accommodative demand and convergence", "Strengthen the medial rectus muscles", "Improve fusional vergence amplitudes"], "correct": 1, "explanation": "In accommodative esotropia, excess accommodation drives excess convergence through the AC/A ratio. Full plus correction (or minus reduction) reduces the accommodative effort and thus convergence, bringing the eyes into alignment."}'),
  ('c6dc0131-2i','{"options": ["Stereoacuity level", "The presence of suppression or diplopia", "Fusional vergence amplitude", "Accommodative convergence ratio"], "correct": 1, "explanation": "The Worth 4-dot test evaluates binocular sensory status — specifically whether the patient has normal fusion, suppression of one eye, or diplopia. It uses red-green dissociation to separate the two eyes'' inputs."}'),
  ('837ce60c-5k','{"options": ["Hyperopia", "Myopia", "Astigmatism", "Presbyopia"], "correct": 1, "explanation": "Myopia (nearsightedness) presents with clear near vision but blurred far vision. Night difficulty and squinting to see at distance are classic myope behaviors as pupils enlarge in dim lighting and squinting reduces the circle of confusion."}'),
  ('778d8f35-3t','{"options": ["Against motion — myopia present", "With motion — hyperopia or low myopia present", "Neutralization — emmetropia at working distance", "Scissors reflex — irregular astigmatism"], "correct": 1, "explanation": "''With'' motion (reflex moves in the same direction as the streak) in retinoscopy indicates hyperopia or myopia less than the working distance correction (~+1.50 D for 67 cm). Plus lenses are added to reach neutralization."}'),
  ('d7b1c47d-3w','{"options": ["0.00 D", "0.25 D", "0.50 D", "1.00 D"], "correct": 1, "explanation": "Interocular difference = |-3.00 - (-3.25)| = 0.25 D. An anisometropia of 0.25 D is within normal limits and typically well-tolerated."}'),
  ('efeaa54f-63','{"options": ["Acquired myopia", "Absolute hyperopia", "Presbyopia", "Convergence insufficiency"], "correct": 2, "explanation": "A plano distance refraction with near blur in a 45-year-old is classic presbyopia — the age-related loss of accommodation. The crystalline lens hardens and can no longer adjust for near focus."}'),
  ('0c8f5e27-4w','{"options": ["25 cm", "33 cm", "40 cm", "50 cm"], "correct": 2, "explanation": "+1.50 D corresponds to a focal point at 1/1.50 = 0.67 m = 67 cm — but as an add, it supplements residual accommodation. Standard reading at ~40 cm requires about +2.50 D total; a +1.50 add targets approximately 40 cm for patients with some remaining amplitude."}'),
  ('d44e94d3-5d','{"options": ["Exophoria", "Esophoria", "Esotropia", "Exotropia"], "correct": 1, "explanation": "Esophoria is a latent inward deviation controlled by fusion. The alternating cover test breaks fusion, revealing the phoria. On cover removal, fusional divergence re-establishes binocular alignment."}'),
  ('27767501-5c','{"options": ["Prism therapy", "Vision therapy for fusional divergence", "Plus addition lenses for near", "Surgical correction"], "correct": 2, "explanation": "High AC/A convergence excess esophoria is managed with plus addition lenses at near (bifocals) — reducing the near accommodative demand decreases convergence through the high AC/A ratio. This is the standard non-surgical first approach."}'),
  ('8323cb6e-4e','{"options": ["Increase the plus add", "Base-out prism", "Base-in prism", "Occlusion therapy"], "correct": 1, "explanation": "Residual symptomatic esophoria (an inward, over-converging deviation) is relieved with base-out prism. The prism apex points nasally, shifting the image toward where the esophoric eyes already turn, so the fusional system has less to overcome. Base-in prism is the correction for exophoria; here it would add to the convergence demand and worsen the esophoria. Increasing the plus add gives little more once the eso is already down to 4Δ, and occlusion does not treat a phoria."}'),
  ('16ff3151-4o','{"options": ["Accommodative esotropia", "Convergence insufficiency", "Divergence excess exotropia", "Basic exophoria"], "correct": 1, "explanation": "Convergence insufficiency (CI) presents with near symptoms: asthenopia, diplopia at near, and difficulty sustaining near work. Distance vision is typically unaffected. Reduced NPC and low PFV are hallmarks."}'),
  ('bb5cf8eb-3p','{"options": ["Base-out prism reading glasses", "Pencil push-up convergence exercises", "Minus lens therapy", "Surgical recession of lateral rectus"], "correct": 1, "explanation": "Pencil push-ups (and office-based vergence/accommodative therapy) are the first-line treatment for CI. They train convergence by having the patient maintain single vision while advancing a fixation target toward the nose."}'),
  ('f599478a-4a','{"options": ["Stimulating accommodation to drive convergence", "Reducing the convergence demand at near", "Increasing fusional divergence reserves", "Correcting the underlying AC/A ratio"], "correct": 1, "explanation": "Base-in prism displaces the near image slightly outward, reducing the amount of convergence the patient must exert. This relieves asthenopia and diplopia while the underlying insufficiency is treated or monitored."}'),
  ('ce1337b2-4m','{"options": ["Optic neuritis", "Central retinal vein occlusion", "Glaucomatous optic nerve damage", "Macular degeneration"], "correct": 2, "explanation": "A C/D ratio ≥0.7, especially with asymmetry between eyes, is a risk factor for glaucoma. Normal C/D is typically ≤0.5. Glaucoma causes progressive loss of rim tissue and cup enlargement."}'),
  ('92c409a2-3p','{"options": ["Cotton-wool spot", "Drusen", "Flame-shaped hemorrhage", "Neovascularization"], "correct": 1, "explanation": "Drusen are yellow-white deposits beneath the RPE, characteristic of age-related macular degeneration (AMD). Hard drusen are small and well-defined; soft drusen are larger and confluent with higher AMD risk."}'),
  ('6afb1f07-1k','{"options": ["Hard lipid exudate from capillary leakage", "Focal ischemia of the nerve fiber layer", "Drusen accumulation in Bruch''s membrane", "Subretinal neovascular membrane"], "correct": 1, "explanation": "Cotton-wool spots are fluffy white superficial retinal lesions representing focal nerve fiber layer infarcts (microinfarctions from capillary occlusion). They are associated with hypertension, diabetes, HIV retinopathy, and other vascular diseases."}'),
  ('793f1e17-6d','{"options": ["15Δ exotropia", "30Δ exotropia", "45Δ exotropia", "60Δ exotropia"], "correct": 2, "explanation": "Hirschberg estimation: pupil center ~15Δ, halfway to limbus ~30Δ, limbus ~45Δ, beyond limbus ~60Δ. Reflex at the nasal limbus of the left eye = the left eye is deviated outward (exo) by approximately 45Δ."}'),
  ('9005394d-51','{"options": ["Tropias (manifest deviations)", "Phorias (latent deviations)", "Anisometropia", "Fixation preference"], "correct": 0, "explanation": "In the cover-uncover test, observing the UNCOVERED eye detects tropias — if the uncovered eye moves to take up fixation when the other eye is covered, a manifest deviation (tropia) exists in the covered eye."}'),
  ('91130385-1j','{"options": ["With-the-rule astigmatism", "Against-the-rule astigmatism", "Oblique astigmatism", "Irregular astigmatism"], "correct": 0, "explanation": "With-the-rule (WTR) astigmatism: steeper meridian is vertical (near 90°). K-readings: 46.00 at 090 (steeper) and 43.00 at 180 (flatter). The steeper vertical meridian = WTR. Spectacle correction: minus cylinder axis 180."}'),
  ('131aea47-1j','{"options": ["With-the-rule astigmatism", "Against-the-rule astigmatism", "Oblique astigmatism", "Spherical cornea"], "correct": 1, "explanation": "Against-the-rule (ATR) astigmatism: steeper meridian is horizontal (near 180°). Here 45.00 at 180 > 43.25 at 090, so the steeper meridian is horizontal → ATR. The minus cylinder correction axis is 090. ATR becomes more common with age."}'),
  ('0f9a2013-4f','{"options": ["Hyperopic shift due to corneal edema", "Myopic shift due to lens swelling from sorbitol accumulation", "Irregular astigmatism from corneal neovascularization", "Presbyopic onset from ciliary muscle neuropathy"], "correct": 1, "explanation": "In uncontrolled DM, sorbitol accumulates in the lens via aldose reductase, causing osmotic lens swelling (increased thickness and power) → transient myopia. Blood glucose spikes post-meal worsen this effect."}'),
  ('d5f5ceeb-50','{"options": ["Grade I", "Grade II", "Grade III", "Grade IV"], "correct": 2, "explanation": "KWB Grade III: flame hemorrhages, cotton-wool spots, hard exudates. Grade I: arteriolar narrowing only. Grade II: AV nicking. Grade IV: papilledema added to Grade III findings."}'),
  ('9c7ab9e6-4w','{"options": ["Nuclear sclerotic cataract", "Anterior subcapsular cataract", "Posterior subcapsular cataract", "Cortical cataract"], "correct": 2, "explanation": "Posterior subcapsular cataracts (PSC) are classically associated with chronic corticosteroid use (systemic or topical) and diabetes. PSC is located at the posterior pole of the lens and causes significant glare and near vision symptoms."}'),
  ('af162010-l','{"options": ["Binocular version movements", "Monocular rotations of one eye", "Vergence amplitude of both eyes simultaneously", "Accommodative convergence ratio"], "correct": 1, "explanation": "Ductions are monocular eye movements performed with one eye covered. They test the range of rotation of a single eye in each direction (abduction, adduction, supraduction, infraduction, incycloduction, excycloduction)."}'),
  ('3da6cd6a-23','{"options": ["Right medial rectus overaction", "Right lateral rectus underaction or palsy", "Left lateral rectus overaction", "Thyroid-related inferior rectus restriction"], "correct": 1, "explanation": "Abduction is the action of the lateral rectus. Reduced right abduction implicates right lateral rectus underaction (e.g., CN VI palsy), causing esotropia that worsens in right gaze."}'),
  ('6b6bdab3-34','{"options": ["Right superior rectus", "Right inferior oblique", "Right superior oblique", "Right inferior rectus"], "correct": 0, "explanation": "The superior rectus is the primary elevator, especially in abduction. However, the inferior oblique is the primary elevator in adduction. Limited elevation in adduction suggests inferior oblique palsy or superior oblique overaction. The superior rectus elevates best in abduction."}'),
  ('0227289f-50','{"options": ["Open-angle glaucoma", "Angle-closure glaucoma", "Ocular hypertension", "Corneal edema from contact lens overwear"], "correct": 1, "explanation": "Narrow angle on gonioscopy with elevated IOP and halos indicates angle-closure glaucoma. The iris occludes the trabecular meshwork, reducing aqueous outflow. Halos occur from corneal edema secondary to IOP spike."}'),
  ('4218e1dd-61','{"options": ["Diabetic macular edema", "Central retinal artery occlusion", "Anterior ischemic optic neuropathy", "Posterior vitreous detachment"], "correct": 2, "explanation": "Anterior ischemic optic neuropathy (AION) presents with sudden monocular visual loss, APD, and segmental or diffuse optic disc edema with peripapillary hemorrhages — classic for arteritic or non-arteritic AION."}'),
  ('e5a9ae11-63','{"options": ["Myopic anisometropia only", "Functional amblyopia", "Organic amblyopia", "Strabismic suppression"], "correct": 1, "explanation": "Functional (or deprivation/refractive/strabismic) amblyopia is reduced BCVA with no structural cause. A 7-year-old with 20/80 BCVA in one eye despite full correction meets the criteria. The visual cortex fails to develop normal acuity due to abnormal visual input during the critical period."}'),
  ('c85e39cc-36','{"options": ["Penalization of the amblyopic eye with atropine", "Full optical correction and patching of the dominant eye", "Vision therapy without spectacles", "Surgical correction of refractive error"], "correct": 1, "explanation": "First-line amblyopia treatment: full optical correction of both eyes (spectacles or contact lenses), then patching the dominant (better-seeing) eye to force use of the amblyopic eye. Correction alone can sometimes improve acuity, especially in anisometropic amblyopia."}'),
  ('2a58b8e0-5e','{"options": ["20/40 or better with improvement", "20/30 or better", "Equal BCVA in both eyes or near-equal", "20/20 in the amblyopic eye"], "correct": 2, "explanation": "Amblyopia treatment goal is equal or near-equal BCVA in both eyes — not necessarily 20/20. Achieving symmetrical acuity (within 1–2 Snellen lines) between eyes is the clinical endpoint for treatment success."}'),
  ('6116dafd-25','{"options": ["Snellen notation (e.g., 20/20)", "logMAR notation", "Jaeger notation", "Point notation"], "correct": 1, "explanation": "logMAR (logarithm of the Minimum Angle of Resolution) is directly derived from MAR. logMAR 0.0 = 20/20 (MAR = 1 arcminute). LogMAR is the preferred clinical research notation because it is linear and statistically valid."}'),
  ('f57ca4ce-1f','{"options": ["logMAR 0.1", "logMAR 0.2", "logMAR 0.3", "logMAR 0.4"], "correct": 1, "explanation": "logMAR = log10(MAR). For 20/40: MAR = 40/20 = 2 arcminutes; log10(2) = 0.301 ≈ 0.3. Therefore 20/40 = logMAR 0.3."}'),
  ('53f4b1c0-4c','{"options": ["Minimum visible acuity", "Minimum resolvable (resolution) acuity", "Minimum recognizable (identification) acuity", "Hyperacuity (Vernier acuity)"], "correct": 1, "explanation": "Minimum resolvable (resolution) acuity measures the ability to discriminate two point stimuli as separate. The Snellen letter chart tests minimum recognizable (identification) acuity. Hyperacuity (Vernier) detects misalignment finer than a single receptor spacing."}'),
  ('e2578fdc-43','{"options": ["Corneal staining", "Aqueous flare from blood-aqueous barrier breakdown", "Vitreous hemorrhage", "Posterior synechiae"], "correct": 1, "explanation": "Aqueous flare (Tyndall effect) is protein-laden aqueous in the anterior chamber visible as a white beam scattering — indicating blood-aqueous barrier breakdown due to uveitis, trauma, or surgery."}'),
  ('4c098138-2d','{"options": ["Corneal stroma thickness", "Endothelial cell mosaic", "Tear film breakup time", "Anterior chamber angle"], "correct": 1, "explanation": "Specular reflection positions the angle of incidence equal to the angle of reflection at a smooth surface (e.g., corneal endothelium), revealing the endothelial cell mosaic. This allows assessment of cell density and morphology."}'),
  ('53d9313a-38','{"options": ["Lissamine green", "Rose Bengal", "Sodium fluorescein", "Trypan blue"], "correct": 2, "explanation": "Sodium fluorescein stains aqueous in corneal epithelial defects and is most visible under cobalt blue (465 nm) illumination, which excites fluorescein to emit a bright green fluorescence. Used for abrasion, ulcer, and RGP fit assessment."}'),
  ('14ea6e56-3d','{"options": ["Anterior chamber cells and flare", "Corneal opacities and edema", "Iris transillumination defects", "Vitreous opacities"], "correct": 1, "explanation": "Sclerotic scatter directs the beam at the limbus; total internal reflection conducts light through the cornea. Normal cornea appears dark; any opacity (edema, scar, infiltrate) scatters light and becomes visible as bright areas against a dark background."}'),
  ('e02593d2-1w','{"options": ["Central corneal thickness", "Anterior chamber depth (angle grade)", "Tear film breakup time", "Intraocular pressure"], "correct": 1, "explanation": "Van Herick technique: a narrow slit beam is placed at the temporal limbus at 60°. The ratio of the anterior chamber shadow to the corneal thickness estimates the peripheral chamber depth and predicts the angle grade. A ratio <1/4 suggests a narrow, potentially occludable angle."}'),
  ('f2a476b5-5j','{"options": ["5 seconds", "10 seconds", "15 seconds", "20 seconds"], "correct": 1, "explanation": "Normal TBUT is ≥10 seconds. TBUT <10 seconds suggests tear film instability consistent with dry eye disease (aqueous-deficient or evaporative). Values ≤5 seconds indicate significant instability."}'),
  ('2bc4b858-5u','{"options": ["Bacterial conjunctivitis", "Anterior uveitis (iritis)", "Episcleritis", "Acute angle-closure glaucoma"], "correct": 1, "explanation": "Anterior uveitis presents with ciliary flush (perilimbal injection), photophobia, AC cells and flare, and KPs (inflammatory cells deposited on the endothelium). Bacterial conjunctivitis lacks ciliary flush and KPs."}'),
  ('74c44a6f-2z','{"options": ["Herpetic keratouveitis", "Granulomatous uveitis (e.g., sarcoidosis, TB)", "Bacterial endophthalmitis", "Fuchs heterochromic iridocyclitis"], "correct": 1, "explanation": "Large, greasy ''mutton-fat'' KPs are characteristic of granulomatous uveitis, seen in sarcoidosis, tuberculosis, sympathetic ophthalmia, and VKH syndrome. Small, fine (stellate) KPs are associated with non-granulomatous uveitis."}'),
  ('a9b436ba-1r','{"options": ["Sudden painful increase in IOP", "Optic disc cupping with visual field loss", "Corneal edema and halos", "Shallow anterior chamber"], "correct": 1, "explanation": "Primary open-angle glaucoma (POAG) is characterized by progressive optic disc cupping, loss of retinal nerve fiber layer, and corresponding visual field defects — typically asymptomatic until advanced. The angle remains open."}'),
  ('1fc4e6eb-6u','{"options": ["Mild non-proliferative diabetic retinopathy", "Moderate non-proliferative diabetic retinopathy", "Severe non-proliferative diabetic retinopathy", "Proliferative diabetic retinopathy"], "correct": 0, "explanation": "Mild NPDR: characterized only by microaneurysms. Moderate NPDR adds dot-blot hemorrhages, hard exudates, and cotton-wool spots. The description (dot-blot hemorrhages + microaneurysms, no NV, no venous beading) fits mild-to-moderate NPDR. Mild = microaneurysms only; presence of hemorrhages elevates to moderate."}'),
  ('f1791a7f-37','{"options": ["Homonymous hemianopia", "Bitemporal hemianopia", "Binasal hemianopia", "Monocular central scotoma"], "correct": 1, "explanation": "A pituitary adenoma compresses the crossing nasal fibers at the chiasm, interrupting temporal visual field input from both eyes → bitemporal hemianopia. This is the classic chiasmal field defect."}'),
  ('ee06112d-42','{"options": ["Posterior vitreous detachment (PVD)", "Retinal detachment", "Vitreous syneresis", "Benign peripheral vitreous degeneration"], "correct": 1, "explanation": "A curtain or shadow in the visual field (scotoma) associated with floaters and photopsia (flashes) suggests a retinal detachment — a sight-threatening emergency requiring same-day ophthalmological evaluation."}'),
  ('47b467e4-6q','{"options": ["Diabetic macular edema", "Central serous chorioretinopathy", "Age-related macular degeneration (AMD)", "Macular hole"], "correct": 2, "explanation": "AMD presents with drusen, geographic atrophy, and CNV in older patients. Metamorphopsia (lines appear wavy) on Amsler grid and gradual central vision loss are hallmarks. It is the leading cause of vision loss in those over 50."}'),
  ('6cb0d285-31','{"options": ["Movement of the uncovered eye when the cover is placed over the other eye", "Movement of the covered eye when the cover is removed", "Refixation movement only during alternating cover test", "No movement of either eye during cover-uncover test"], "correct": 0, "explanation": "In the cover-uncover test, if the UNCOVERED eye moves to take up fixation when the cover is placed over the fellow eye, the uncovered eye was previously deviated — indicating a manifest tropia in that eye."}'),
  ('095fe975-6d','{"options": ["Single vision distance lenses only", "Single vision reading lenses only", "Progressive addition lenses", "Occupational bifocal or trifocal lenses"], "correct": 3, "explanation": "An occupational bifocal or trifocal (e.g., flat-top with reading and intermediate segments) is most appropriate for a presbyopic patient who needs both distance (driving) and near (bookkeeping) correction with clear intermediate vision — progressive lenses are another excellent option but the occupational design is purpose-built for desk work."}'),
  ('23b3f56c-3n','{"options": ["Dry eye disease", "Glaucoma (to increase aqueous outflow)", "Uveitis (to dilate the pupil)", "Allergic conjunctivitis"], "correct": 1, "explanation": "Pilocarpine is a cholinergic (muscarinic) agonist that constricts the pupil (miosis) and contracts the ciliary muscle, widening the trabecular meshwork and increasing aqueous outflow — used in glaucoma management. It is a miotic, not a mydriatic."}'),
  ('ec9e66e2-36','{"options": ["Determining the refractive error type", "Establishing the working distance and prescription design needed", "Ruling out systemic disease", "Assessing the need for low vision rehabilitation"], "correct": 1, "explanation": "Occupational and lifestyle visual demands (working distance, near vs. distance tasks, outdoor exposure) directly determine the appropriate spectacle design, lens type, and add power. This guides the prescription to functional real-world needs."}'),
  ('6156e343-24','{"options": ["Zeiss", "Haag-Streit", "Both are bottom-illuminated", "Neither uses a top light"], "correct": 1, "explanation": "On the Haag-Streit the light source sits at the TOP (a mirror throws the beam down); on the Zeiss it sits at the BASE. Memory hook: ''Haag hangs high.''"}'),
  ('7ece5cd1-2f','{"options": ["Galilean (telescopic)", "Greenough (converging tubes)", "Keplerian", "Indirect condensing system"], "correct": 1, "explanation": "The Greenough microscope uses two converging tubes and changes power with a rotating drum/lever. The Galilean (telescopic) design changes power by flipping fixed telescopes in and out, giving stepped magnifications. The drill point is the Greenough vs Galilean split."}'),
  ('9213571c-1j','{"options": ["-10 D", "+10 D", "+20 D", "+22 D"], "correct": 1, "explanation": "The eyepiece (ocular) is a +10 D magnifier and the objective is +22 D. Memory hook: ''10 in, 22 out'' (you peer through the +10, the +22 faces the patient)."}'),
  ('3aa614b4-1d','{"options": ["+10 D", "+12 D", "+20 D", "+22 D"], "correct": 3, "explanation": "The objective lens (facing the patient) is +22 D; the eyepiece you look through is +10 D."}'),
  ('a79796fb-2a','{"options": ["Field of view increases", "Field of view decreases", "No change to field of view", "It first increases then decreases"], "correct": 1, "explanation": "Higher magnification always gives a SMALLER (decreased) field of view and less depth of focus. Start low (6x) to find the target, then zoom in for detail."}'),
  ('4f5d7125-2q','{"options": ["0 degrees (coaxial with the microscope)", "30 degrees", "45 degrees", "60 degrees"], "correct": 0, "explanation": "The illumination arm is set to 0 degrees (coaxial with the viewing microscope) when you focus on the focusing rod, so the beam and the oculars share one focal plane before you begin."}'),
  ('98d37b5b-2h','{"options": ["6x", "16x", "25x", "40x"], "correct": 0, "explanation": "The adnexa and a lids/lashes survey use LOW power, about 6x (lids and lashes 6x-10x), for a wide field. The cornea, iris, and Van Herick sit at 16x; anterior-chamber cells and flare need 25x-40x."}'),
  ('27b9cb67-1w','{"options": ["6x", "10x", "16x", "40x"], "correct": 2, "explanation": "The cornea is viewed at about 16x (the same middle magnification used for the iris and the Van Herick angle estimate). Adnexa/lids sit lower at 6x-10x; anterior-chamber cells and flare go higher at 25x-40x."}'),
  ('3fa7ee56-2g','{"options": ["6x in a bright room", "16x with the overhead light on", "25x-40x in a fully dark room", "40x with the cobalt blue filter"], "correct": 2, "explanation": "Cells and flare are dim, subtle findings, so they need high magnification (25x-40x) and a fully DARK room. This is the one part of the exam where the overhead light is switched completely off."}'),
  ('615e0204-2q','{"options": ["30 degrees; it overestimates the angle", "45 degrees; no effect", "60 degrees; a smaller angle underestimates the angle", "90 degrees; it overestimates the angle"], "correct": 2, "explanation": "Van Herick uses a 60-degree illumination angle (with the diffuser/gray filter OFF). Setting the beam at LESS than 60 degrees distorts the shadow-to-section ratio and UNDERestimates the true angle."}'),
  ('65024ecf-3s','{"options": ["Cells (inflammatory white blood cells)", "Flare (protein leaked into the aqueous)", "Pigment on the endothelium", "A closed anterior chamber angle"], "correct": 1, "explanation": "Flare is the Tyndall haze of leaked PROTEIN, a diffuse glow with no distinct particles. CELLS are discrete floating white blood cells (like dust in a sunbeam). Flare = protein; cells = inflammatory cells."}'),
  ('3d9cb7b5-30','{"options": ["Below the tarsal plate", "Above the tarsal plate (at the superior tarsal border)", "Directly over the lid margin", "At the medial canthus"], "correct": 1, "explanation": "To evert the upper lid you press at the SUPERIOR tarsal border (above the tarsal plate) while the patient looks down, then flip the lid over that fulcrum."}'),
  ('35e0c82e-1n','{"options": ["In one quick horizontal sweep", "In sections, scanning systematically", "Only with the cobalt blue filter", "At the highest available magnification"], "correct": 1, "explanation": "The lids and lashes are examined in SECTIONS, not one quick sweep. A single pass misses the lid margin, meibomian orifices, and lash-base pathology (an internal hordeolum of the meibomian gland, early trichiasis)."}'),
  ('4a65dada-p','{"options": ["The relationship between the anterior chamber and lens", "The relationship between the posterior principal focus, refractive mechanism, and retina with accommodation relaxed", "The power of the cornea relative to the lens", "The axial length of the eye"], "correct": 1, "explanation": "Refractive status describes the relationship between the posterior principal focus of the eye''s refractive mechanism and the retina with accommodation relaxed."}'),
  ('f6def6ee-20','{"options": ["1/3", "1/2", "2/3", "3/4"], "correct": 2, "explanation": "The cornea contributes 2/3 of the eye''s refractive power, ranging from 36.00 D to 50.00 D with an average of 43.00 D."}'),
  ('f48c3448-2r','{"options": ["43.05 D", "50.00 D", "58.64 D", "62.00 D"], "correct": 2, "explanation": "The complete unaccommodated eye has a total refractive power of 58.64 D."}'),
  ('7125971a-1g','{"options": ["1.336", "1.376", "1.386", "1.406"], "correct": 0, "explanation": "The aqueous humor has an index of refraction of 1.336."}'),
  ('cf9307e0-19','{"options": ["1.336", "1.376", "1.386", "1.406"], "correct": 1, "explanation": "The cornea has an index of refraction of 1.376."}'),
  ('3918a067-22','{"options": ["15.00 D", "19.11 D", "21.00 D", "24.00 D"], "correct": 1, "explanation": "The unaccommodated lens has a power of 19.11 D."}'),
  ('f5907dd8-1q','{"options": ["3.6 mm", "7.08 mm", "7.33 mm", "15.70 mm"], "correct": 1, "explanation": "The primary nodal point is located 7.08 mm from the corneal apex."}'),
  ('e319148c-1r','{"options": ["7.08 mm", "15.70 mm", "24.38 mm", "31.00 mm"], "correct": 1, "explanation": "The primary focal length is 15.70 mm from the corneal apex."}'),
  ('b3b82093-1s','{"options": ["15.70 mm", "20.00 mm", "24.38 mm", "30.00 mm"], "correct": 2, "explanation": "The secondary focal length is 24.38 mm."}'),
  ('99d5b1b4-1n','{"options": ["0.5 mm", "1.0 mm", "1.5 mm", "2.0 mm"], "correct": 0, "explanation": "The corneal thickness is 0.5 mm."}'),
  ('fd64c390-1w','{"options": ["0.5 mm", "3.6 mm", "7.2 mm", "10.0 mm"], "correct": 1, "explanation": "The distance from the corneal apex to the front lens surface is 3.6 mm."}'),
  ('ba46fac6-1t','{"options": ["On the retina", "Behind the retina", "In front of the retina", "At the cornea"], "correct": 2, "explanation": "In myopia, parallel rays focus in front of the retina with accommodation relaxed."}'),
  ('6f1b09ae-1w','{"options": ["On the retina", "Behind the retina", "In front of the retina", "At the lens"], "correct": 1, "explanation": "In hyperopia, parallel rays focus behind the retina with accommodation relaxed."}'),
  ('048f6333-1m','{"options": ["Low", "Medium", "High", "Extreme"], "correct": 0, "explanation": "Myopia from 0.25 D to 3.00 D is classified as low degree."}'),
  ('0105da21-1p','{"options": ["Low", "Medium", "High", "Severe"], "correct": 2, "explanation": "Hyperopia from 5.00 D and above is classified as high degree."}'),
  ('048c8e5b-1n','{"options": ["Absolute", "Facultative", "Latent", "Manifest"], "correct": 0, "explanation": "Absolute hyperopia cannot be overcome by accommodation and results in subnormal vision."}'),
  ('e5473eb4-1s','{"options": ["Absolute", "Facultative", "Latent", "Manifest"], "correct": 2, "explanation": "Latent hyperopia is hidden and requires cycloplegic refraction to reveal."}'),
  ('ec940f28-1j','{"options": ["Absolute hyperopia", "Total hyperopia", "Facultative hyperopia", "Complete hyperopia"], "correct": 1, "explanation": "Total hyperopia is the sum of manifest and latent hyperopia."}'),
  ('c111c371-1v','{"options": ["15 - 0.25(age)", "18.5 - 0.30(age)", "25 - 0.40(age)", "20 - 0.30(age)"], "correct": 0, "explanation": "The minimum amplitude of accommodation is calculated as 15 - 0.25(age)."}'),
  ('5297a428-1v','{"options": ["15 - 0.25(age)", "18.5 - 0.30(age)", "25 - 0.40(age)", "20 - 0.35(age)"], "correct": 1, "explanation": "The average amplitude of accommodation is calculated as 18.5 - 0.30(age)."}'),
  ('bf4349cb-1v','{"options": ["15 - 0.25(age)", "18.5 - 0.30(age)", "25 - 0.40(age)", "30 - 0.50(age)"], "correct": 2, "explanation": "The maximum amplitude of accommodation is calculated as 25 - 0.40(age)."}'),
  ('78885806-1v','{"options": ["35 years", "40 years", "45 years", "50 years"], "correct": 2, "explanation": "Presbyopia typically becomes clinically apparent around age 45, though it can range from 40 to 50."}'),
  ('ff516483-20','{"options": ["Thomas Young", "Christopher Scheiner", "George Biddle Airy", "Johannes Kepler"], "correct": 1, "explanation": "Christopher Scheiner proved the existence of accommodation in 1619 using Scheiner''s disc."}'),
  ('2137cb81-1p','{"options": ["Thomas Young", "Christopher Scheiner", "George Biddle Airy", "John Green"], "correct": 2, "explanation": "George Biddle Airy was the first to correct astigmatism using a spherocylindrical lens."}'),
  ('43f98710-15','{"options": ["Aristotle", "Johannes Kepler", "Donders", "Thomas Young"], "correct": 1, "explanation": "Johannes Kepler gave the actual definition of myopia in 1611."}'),
  ('a4ade236-1x','{"options": ["Horizontal meridian", "Vertical meridian", "45 degrees", "135 degrees"], "correct": 1, "explanation": "In with-the-rule astigmatism, the curvature of greatest power is near the vertical meridian (60-120 degrees)."}'),
  ('e9e7aea1-20','{"options": ["Horizontal meridian", "Vertical meridian", "45 degrees", "Oblique"], "correct": 0, "explanation": "In against-the-rule astigmatism, the curvature of greatest power is near the horizontal meridian (0-30, 150-180 degrees)."}'),
  ('11e491f6-28','{"options": ["Simple myopic", "Compound myopic", "Simple hyperopic", "Compound hyperopic"], "correct": 3, "explanation": "Compound hyperopic astigmatism has both principal meridians focusing behind the retina."}'),
  ('7a11a019-2f','{"options": ["Simple myopic", "Compound myopic", "Mixed", "Simple hyperopic"], "correct": 0, "explanation": "Simple myopic astigmatism has one meridian on the retina and the other in front."}'),
  ('5a1bd655-24','{"options": ["Simple myopic", "Compound myopic", "Mixed", "Compound hyperopic"], "correct": 2, "explanation": "Mixed astigmatism has one meridian focusing in front and one behind the retina."}'),
  ('f8b6b7c2-39','{"options": ["0.25 D", "0.50 D", "1.00 D", "2.00 D"], "correct": 2, "explanation": "According to Grosvenor, anisometropia requires at least 1.00 D difference between eyes."}'),
  ('26062e1a-1x','{"options": ["Isometropia", "Isoanisometropia", "Antimetropia", "Aniso-oxyopia"], "correct": 2, "explanation": "Antimetropia is a condition where one eye is myopic and the other is hyperopic."}'),
  ('8c49d7cb-21','{"options": ["Refraction", "Accommodation", "Convergence", "Adaptation"], "correct": 1, "explanation": "Accommodation is the process by which the crystalline lens varies its focal length in response to changes in vergence."}'),
  ('12973a53-16','{"options": ["Dynamic accommodation", "Refractive status with accommodation relaxed", "Near vision testing", "Convergence ability"], "correct": 1, "explanation": "Static refraction is used to describe the refractive status of the eye with accommodation relaxed."}'),
  ('c388f597-2j','{"options": ["8.00 D", "10.00 D", "12.50 D", "17.00 D"], "correct": 1, "explanation": "For a 20-year-old: Min AOA = 15 - 0.25(20) = 10.00 D."}'),
  ('6f7d737c-2j','{"options": ["10.00 D", "12.50 D", "15.00 D", "17.00 D"], "correct": 1, "explanation": "For a 20-year-old: Ave AOA = 18.5 - 0.30(20) = 12.50 D."}'),
  ('0161a26e-21','{"options": ["Increase with age", "No change", "Diminution with age", "Fluctuation with age"], "correct": 2, "explanation": "Presbyopia is the condition where amplitude of accommodation diminishes with increasing age."}'),
  ('b48993c0-24','{"options": ["Length of the eyeball", "Power of the cornea", "Colour of the iris", "Depth of anterior chamber"], "correct": 2, "explanation": "The four factors that influence refractive status are: length of eyeball, power of cornea, power of lens, and depth of anterior chamber."}'),
  ('42e00321-1e','{"options": ["1.336", "1.376", "1.386", "1.406"], "correct": 2, "explanation": "The lens cortex has an index of refraction of 1.386."}'),
  ('6685eb76-1n','{"options": ["6.0 mm", "6.8 mm", "7.7 mm", "10.0 mm"], "correct": 1, "explanation": "The back corneal surface has a radius of curvature of 6.8 mm."}'),
  ('608e9dac-1l','{"options": ["6.0 mm", "6.8 mm", "7.7 mm", "10.0 mm"], "correct": 3, "explanation": "The front lens surface has a radius of curvature of 10.0 mm."}'),
  ('6d859960-1k','{"options": ["6.0 mm", "6.8 mm", "7.7 mm", "10.0 mm"], "correct": 0, "explanation": "The back lens surface has a radius of curvature of 6.0 mm."}'),
  ('75638d29-16','{"options": ["3.6 mm", "7.08 mm", "7.33 mm", "15.70 mm"], "correct": 2, "explanation": "The secondary nodal point is located at 7.33 mm."}'),
  ('5a7aac80-1m','{"options": ["Low", "Medium", "High", "Severe"], "correct": 1, "explanation": "Myopia from 3.00 D to 6.00 D is classified as medium degree."}'),
  ('87cea699-1p','{"options": ["Low", "Medium", "High", "Extreme"], "correct": 1, "explanation": "Hyperopia from 3.00 D to 5.00 D is classified as medium degree."}'),
  ('a05ffd66-1u','{"options": ["0.25 D to 3.00 D", "0.25 D to 6.00 D", "Above 6.00 D", "3.00 D to 6.00 D"], "correct": 1, "explanation": "Correlative hyperopia includes errors from 0.25 D to 6.00 D."}'),
  ('f62a2a51-1s','{"options": ["0.25 D to 3.00 D", "0.25 D to 6.00 D", "Above 6.00 D", "3.00 D to 5.00 D"], "correct": 2, "explanation": "Component hyperopia includes errors above 6.00 D."}'),
  ('aec75c49-u','{"options": ["Temporary spasm", "Permanent spasm", "No spasm", "Variable spasm"], "correct": 1, "explanation": "Tonic latent hyperopia is a relatively fixed or permanent state of spasm."}'),
  ('bb9e0f1a-v','{"options": ["Temporary spasm", "Permanent spasm", "No spasm", "Chronic spasm"], "correct": 0, "explanation": "Clonic latent hyperopia is a temporary state of spasm."}'),
  ('9893e173-z','{"options": ["Asthenopia", "Photophobia", "Improved near vision", "Tearing"], "correct": 2, "explanation": "Improved near vision is not a symptom. Hyperopes have blurred vision at near."}'),
  ('e658bd44-s','{"options": ["Dilated pupil", "Constricted pupil", "Normal pupil", "Irregular pupil"], "correct": 1, "explanation": "Constricted pupil is a sign of hyperopia."}'),
  ('4c5cc997-1k','{"options": ["Aristotle", "Johannes Kepler", "Donders", "Scheiner"], "correct": 2, "explanation": "Donders definitively described and classified myopia in 1866."}'),
  ('99e3d5de-z','{"options": ["Kastner", "Donders", "Helmholtz", "Kepler"], "correct": 2, "explanation": "Helmholtz used the term ''hyperopia'' in 1859."}'),
  ('bc00bfcf-r','{"options": ["Greatest power 0-30 degrees", "Greatest power 60-120 degrees", "Greatest power 30-60 or 120-150 degrees", "No specific meridian"], "correct": 2, "explanation": "Oblique astigmatism has greatest power within 30-60 and 120-150 degrees."}'),
  ('75ee0825-1u','{"options": ["Vertical oval", "Horizontal oval", "Circle", "Vertical line"], "correct": 1, "explanation": "In compound hyperopic astigmatism with WTR, the image is a horizontal oval."}'),
  ('b7a27963-1r','{"options": ["Vertical oval", "Horizontal oval", "Circle", "Horizontal line"], "correct": 0, "explanation": "In compound myopic astigmatism with WTR, the image is a vertical oval."}'),
  ('323d5fbc-1o','{"options": ["Plus sphere with plus cylinder", "Minus sphere with minus cylinder", "Plus sphere with minus cylinder", "Minus sphere with plus cylinder"], "correct": 0, "explanation": "Compound hyperopic astigmatism is corrected with plus sphere and plus cylinder."}'),
  ('10c8b104-1l','{"options": ["Plus sphere with plus cylinder", "Minus sphere with minus cylinder", "Plus sphere with minus cylinder", "Simple plus cylinder"], "correct": 1, "explanation": "Compound myopic astigmatism is corrected with minus sphere and minus cylinder."}'),
  ('432cc4cb-1m','{"options": ["Simple plus cylinder", "Simple minus cylinder", "Plus sphere with plus cylinder", "Minus sphere"], "correct": 0, "explanation": "Simple hyperopic astigmatism is corrected with a simple plus cylinder."}'),
  ('2b94da21-1j','{"options": ["Simple plus cylinder", "Simple minus cylinder", "Minus sphere with minus cylinder", "Plus sphere"], "correct": 1, "explanation": "Simple myopic astigmatism is corrected with a simple minus cylinder."}'),
  ('03c6180a-13','{"options": ["Corneal changes", "Sclerosis of lens fibres and capsule", "Retinal degeneration", "Vitreous liquefaction"], "correct": 1, "explanation": "The generally accepted cause is sclerosis of the lens fibres and capsule."}'),
  ('73750749-26','{"options": ["Below 10.00 D", "Below 7.00 D", "Below 5.00 D", "Below 3.00 D"], "correct": 2, "explanation": "Presbyopia symptoms typically appear when amplitude is below 5.00 D."}'),
  ('cb8165e4-r','{"options": ["Early presbyopia", "Presbyopia with some accommodation", "Presbyopia with practically no accommodation", "Temporary presbyopia"], "correct": 2, "explanation": "Absolute presbyopia is when accommodation is at minimum or practically absent."}'),
  ('d54d3f42-s','{"options": ["Terminal presbyopia", "Early stage presbyopia", "Complete presbyopia", "Severe presbyopia"], "correct": 1, "explanation": "Incipient presbyopia is the early stage where small print can be read with effort."}'),
  ('03740176-s','{"options": ["Presbyopia after 50", "Presbyopia before 40", "Presbyopia at 45", "Presbyopia after 60"], "correct": 1, "explanation": "Premature presbyopia manifests at an early age, before 40 years."}'),
  ('c0ee64cf-s','{"options": ["Presbyopia during day", "Presbyopia with bright light", "Reduced accommodation with reduced illumination", "Presbyopia with near work"], "correct": 2, "explanation": "Nocturnal presbyopia is reduction in accommodation induced by reduced illumination."}'),
  ('9491911e-49','{"stem": "A patient''s right spectacle lens is OD −3.00 −1.00 × 90. The patient views through a point 3 mm temporal to the optical center (horizontal displacement). What is the horizontal prismatic effect?", "options": ["1.2Δ base out", "0.9Δ base up", "1.5Δ base in", "0.9Δ base in"], "correct": 0, "decode": "Formula (Prentice): P = d(cm) × F, using the power in the meridian of the decentration. Horizontal decentration → 180° meridian. Axis 90 puts the cyl power in the 180° meridian, so horizontal power = −3.00 + (−1.00) = −4.00 D. Steps: 3 mm = 0.3 cm; P = 0.3 × 4.00 = 1.2Δ. Minus lens displaced temporally → base out.", "ow": ["Correct. Horizontal power = −4.00 D (sphere + cyl, axis 90); 0.3 cm × 4.00 = 1.2Δ, base out.", "0.9Δ base-up applies vertical decentration, but the displacement here is horizontal.", "1.5Δ base-in uses the wrong magnitude and direction.", "0.9Δ comes from using only the −3.00 sphere; it forgets that the −1.00 cyl (axis 90) also acts in the horizontal meridian, making it −4.00 D."]}')
)
UPDATE question_reviews r
SET payload = r.payload || d.patch::jsonb
FROM d
WHERE r.question_id = d.qid;
